  const box = el('input');
  box.type = 'checkbox'; box.checked = Boolean(on); box.disabled = disabled;
  if (label) box.setAttribute('aria-label', label);
  box.addEventListener('change', () => void change(box.checked, box));
  wrap.append(box, el('i'));
