  const width = card.offsetWidth || 340;
  card.style.top = `${Math.round(key.bottom + 8)}px`;
  card.style.left = `${Math.round(Math.max(16, Math.min(window.innerWidth - width - 16, key.left + key.width / 2 - width / 2)))}px`;
