/* ---------- agent spheres: click to expand session usage ---------- */

const pop = document.querySelector('#agent-pop');
function statsFor(id) {
  if (!state.agentStats.has(id)) state.agentStats.set(id, { turns: 0, lastTurnMs: null, lastTurnTokens: null, cost: 0, started: new Map() });
  return state.agentStats.get(id);
}
function trackStats(event) {
  if (event.type === 'agent.started') {
    statsFor(event.payload.agent).started.set(event.payload.messageId, new Date(event.timestamp).getTime());
  } else if (event.type === 'agent.completed' || event.type === 'message.failed') {
    const stats = statsFor(event.payload.agent ?? event.payload.target);
    const t0 = stats.started.get(event.payload.messageId);
    if (t0) { stats.lastTurnMs = new Date(event.timestamp).getTime() - t0; stats.started.delete(event.payload.messageId); }
    stats.turns += 1;
  } else if (event.type === 'usage.recorded') {
    const stats = statsFor(event.payload.agent);
    stats.lastTurnTokens = event.payload.usage?.totalTokens ?? null;
    if (Number.isFinite(event.payload.usage?.costUsd)) { stats.cost += event.payload.usage.costUsd; if (event.payload.usage.costEstimated && event.payload.usage.costUsd > 0) stats.costEstimated = true; }
  }
}

// Dollars as a person reads them: cents, and «< $0.01» for less than one rather than «$0.00».
function fmtUsd(value) { return value > 0 && value < 0.01 ? '< $0.01' : `$${value.toFixed(2)}`; }
function fmtMs(ms) { return ms === null ? '—' : ms < 1000 ? `${ms}ms` : `${Math.round(ms / 1000)}s`; }

function capabilityBadges(id) {
  const caps = state.capabilities[id] ?? {};
  const wrap = el('div', 'caps');
  wrap.style.marginTop = '10px';
  for (const [key, labelText] of Object.entries(CAP_LABELS)) {
    const badge = el('span', `cap${caps[key] ? ' on' : ''}`, labelText);
    const detail = caps.detail?.[key];
    badge.title = caps[key] ? `${labelText}: ${detail?.how ?? t('available')}${detail?.note ? ` · ${detail.note}` : ''}` : t('{what}: not available from this CLI', { what: labelText });
    wrap.append(badge);
  }
  return wrap;
}

// Where a card stands: under what opened it, inside the window.
function placeAgentPop(anchor) {
  pop.hidden = false;
  const rect = anchor.getBoundingClientRect();
  const width = pop.offsetWidth || 260;
  pop.style.top = `${rect.bottom + 10}px`;
  pop.style.left = `${Math.max(12, Math.min(window.innerWidth - width - 12, rect.left + rect.width / 2 - width / 2))}px`;
  document.querySelectorAll('.agents .avatar.open, #agents-compact.open').forEach((node) => node.classList.remove('open'));
  anchor.classList.add('open');
}

// The crew, from the one button that stands for the spheres: each agent as its sphere shows it —
// ring, name, how much of its window is spent — and a press opens that agent's card. CONNECTIONS,
// where all of it is set, is one press further.
function openCrewPop(anchor) {
  const all = [...state.agents.values()];
  pop.style.removeProperty('--agent');
  delete pop.dataset.agent;
  pop.replaceChildren();
  const head = el('div', 'head');
  head.append(el('b', null, t('AGENTS')), el('span', 'vendor', t('{ready} of {total} ready', { ready: all.filter((agent) => agent.ready).length, total: all.length })));
  pop.append(head);
  const list = el('div', 'crew-list');
  for (const agent of all) {
    const shown = ringPercent(agent);
    const row = paint(el('button', `crew-row${agent.ready ? '' : ' cold'}`), agent.id);
    row.type = 'button';
    const words = el('span', 'crew-words');
    words.append(el('b', null, `@${agent.id}`), el('span', null, agent.ready ? vendorWord(agent.id) : t('no session')));
    row.append(avatar(agent.id, { size: 24, ring: agent.ready, pct: shown, status: agent.ready ? 'ready' : agent.detected ? 'detected' : 'offline' }), words, el('span', `crew-pct${shown >= 80 ? ' hot' : ''}`, `${Math.round(shown)}%`));
    row.addEventListener('click', (event) => { event.stopPropagation(); openAgentPop(agent.id, anchor, { back: () => openCrewPop(anchor) }); });
    list.append(row);
  }
  pop.append(list);
  const go = el('button', 'crew-go');
  go.type = 'button';
  const gear = el('span', 'crew-go-icon');
  gear.innerHTML = GEAR_ICON; // trusted: our own SVG string
  go.append(gear, el('span', null, t('Agents in Settings')));
  go.addEventListener('click', () => {
    closeAgentPop();
    openSettings(true, { category: 'agents' });
  });
  pop.append(go);
  pop.dataset.for = 'crew';
  pop.dataset.from = 'crew';
  placeAgentPop(anchor);
}

function openAgentPop(id, anchor, { back = null } = {}) {
  const agent = state.agents.get(id);
  if (!agent) return;
  const stats = statsFor(id);
  const session = state.sessions?.[id];
  const percent = localPercent(agent);
  const official = liveOfficial(agent);
  const shown = ringPercent(agent);
  paint(pop, id);
  pop.replaceChildren();
  const head = el('div', 'head');
  if (back) {
    const previous = el('button', 'crew-back', '‹');
    previous.type = 'button';
    previous.setAttribute('aria-label', t('Back to the agents'));
    previous.addEventListener('click', (event) => { event.stopPropagation(); back(); });
    head.append(previous);
  }
  head.append(avatar(id, { size: 24 }));
  const who = el('div', 'pop-who');
  who.append(el('b', null, agent.label), el('span', 'vendor', vendorWord(id)));
  head.append(who);
  // The session in the corner: the one thing to know before asking it anything.
  const lamp = session?.state === 'signed-in' ? 'ok' : session?.state === 'signed-out' || !agent.ready ? 'bad' : 'wait';
  head.append(el('span', `pop-session ${lamp}`, session ? ({ 'signed-in': t('signed in'), 'signed-out': t('signed out') }[session.state] ?? t('unknown')) : agent.ready ? t('unknown') : t('not ready')));
  pop.append(head);
  // Read top to bottom (2026-10-14): one figure and its gauge, four plain numbers, what the
  // provider says (or that it says nothing), the connection in one line, what it can do, and the
  // way to its settings.
  const hero = el('div', 'pop-hero');
  let figure;
  let caption;
  if (official !== null) {
    figure = `${Math.round(official)}%`;
    caption = t("of the provider's {window} limit", { window: fmtWindow(agent.officialWindows?.primary?.windowMinutes ?? 300) });
  } else if (state.budget) {
    figure = `${Math.round(percent)}%`;
    caption = t("of this project's limit · last 5 h");
  } else {
    figure = formatTokens(agent.tokens ?? 0) || '0';
    caption = t('tokens in the last 5 h');
  }
  const big = el('div', 'big', figure);
  big.append(el('small', null, caption));
  hero.append(big);
  const gauge = el('div', `gauge${shown >= 80 ? ' hot' : ''}`);
  const fill = el('i'); fill.style.width = `${shown}%`; gauge.append(fill);
  hero.append(gauge);
  const under = official !== null
    ? (agent.officialResetAt ? t(' · resets {when}', { when: fmtReset(agent.officialResetAt) }) : t(' · window reset')).replace(/^\s*·\s*/, '')
    : state.budget ? t('{used} of {total} tokens', { used: formatTokens(agent.tokens ?? 0) || '0', total: formatTokens(state.budget) }) + (agent.rollsOverAt ? t(' · oldest turn drops {when}', { when: fmtReset(agent.rollsOverAt) }) : '') : null;
  if (under) hero.append(el('div', 'pop-reset', under));
  pop.append(hero);

  const grid = el('div', 'pop-stats');
  const stat = (label, value) => { const box = el('div', 'pop-stat'); box.append(el('span', null, label), el('b', null, value)); grid.append(box); };
  stat(t('In this project'), `${formatTokens(agent.rawTokens ?? 0) || '0'} tok`);
  stat(t('Answers'), String(stats.turns));
  stat(t('Last answer'), stats.lastTurnMs ? `${fmtMs(stats.lastTurnMs)}${stats.lastTurnTokens ? ` · ${formatTokens(stats.lastTurnTokens)}` : ''}` : '—');
  stat(stats.costEstimated ? t('Cost (estimated)') : t('Cost'), stats.cost > 0 ? `${stats.costEstimated ? '≈ ' : ''}${fmtUsd(stats.cost)}` : '—');
  pop.append(grid);

  const provider = el('section', 'pop-provider');
  if (agent.officialWindows) {
    const { primary, secondary } = agent.officialWindows;
    const line = (one) => {
      const row = el('div', `pop-limit${one.usedPercent >= 80 ? ' hot' : ''}`);
      row.append(el('span', null, t('{window} limit', { window: fmtWindow(one.windowMinutes) })), el('b', null, one.resetAt ? t('{pct}% · resets {when}', { pct: Math.round(one.usedPercent), when: fmtReset(one.resetAt) }) : `${Math.round(one.usedPercent)}%`));
      provider.append(row);
    };
    provider.append(el('h4', null, t('Your plan')));
    if (primary) line(primary);
    if (secondary) line(secondary);
  } else if (Number.isFinite(agent.officialPercent)) {
    provider.append(el('h4', null, t('Your plan')), el('p', 'pop-note', t('{pct}% used', { pct: Math.round(official ?? 0) })));
  } else {
    provider.append(el('p', 'pop-note', t("{agent}'s app does not say how much of your plan is left. What you see here is only what this project spent.", { agent: agent.label })));
  }
  pop.append(provider);

  const timeout = Math.round((state.timeouts[id] ?? 180000) / 1000);
  const meta = [session?.detail, agent.version ? t('version {version}', { version: agent.version }) : null, t('waits up to {time}', { time: timeout >= 120 ? t('{n} min', { n: Math.round(timeout / 60) }) : `${timeout}s` })].filter(Boolean);
  pop.append(el('p', 'pop-meta', meta.join(' · ')));
  pop.append(capabilityBadges(id));
  const go = el('button', 'pop-go', t('Connection and limits in Settings'));
  go.type = 'button';
  go.addEventListener('click', (event) => { event.stopPropagation(); closeAgentPop(); openSettingsOn('agents', { agent: id }); });
  pop.append(go);
  pop.dataset.for = id;
  pop.dataset.from = back ? 'crew' : 'sphere';
  placeAgentPop(anchor);
}
function closeAgentPop() {
  pop.hidden = true;
  delete pop.dataset.for;
  delete pop.dataset.from;
  document.querySelectorAll('.agents .avatar.open, #agents-compact.open').forEach((node) => node.classList.remove('open'));
}
els.agents.addEventListener('click', (event) => {
  const sphere = event.target.closest('.avatar');
  if (!sphere) return;
  const id = sphere.dataset.agent;
  if (pop.dataset.for === id && !pop.hidden) closeAgentPop(); else openAgentPop(id, sphere);
});
document.addEventListener('click', (event) => { if (!pop.hidden && !pop.contains(event.target) && !event.target.closest('.agents, #agents-compact')) closeAgentPop(); });
document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeAgentPop(); });

/* ---------- ⚙ connections & settings inside MU/TH/UR ---------- */

const settingsUI = {
  button: document.querySelector('#mother-settings-button'),
  data: null,
  open: false,
  loginLogs: new Map(),
  // The agents whose card is open in AJUSTES › Agents, kept while the page lives.
  agentsOpen: new Set(),
};

function loginAskSlot(agentId) {
  const box = el('div', 'login-ask');
  box.dataset.agent = agentId;
  fillLoginAsk(box);
  return box;
}
function repaintLoginAsk() { for (const box of document.querySelectorAll('.login-ask')) fillLoginAsk(box); }
function fillLoginAsk(box) {
  const agentId = box.dataset.agent;
  box.replaceChildren();
  const live = loginNow.agent === agentId;
  box.hidden = !live;
  if (!live) return;
  if (loginNow.url) {
    const open = el('a', 'sx-btn primary', t('Open the sign-in page'));
    open.href = loginNow.url;
    open.target = '_blank';
    open.rel = 'noopener noreferrer';
    box.append(open);
  }
  // A device sign-in (GitHub Copilot through OpenCode): the code is MADRE's to show, the page's
  // to be typed into. Nothing comes back here; the sign-in ends on its own once it is typed.
  if (loginNow.deviceCode) {
    const said = el('div', 'login-device');
    said.append(el('span', null, t('Type this code on that page:')), el('code', null, loginNow.deviceCode));
    const copy = el('button', 'sx-btn', t('Copy'));
    copy.type = 'button';
    copy.addEventListener('click', async () => {
      try { await navigator.clipboard.writeText(loginNow.deviceCode ?? ''); copy.textContent = t('Copied'); } catch { copy.textContent = t('Select it'); }
    });
    said.append(copy);
    box.append(said);
  }
  if (loginNow.asksForCode || loginNow.awaiting) {
    const form = el('form', 'login-code');
    const input = el('input');
    input.type = 'text';
    input.autocomplete = 'off';
    input.spellcheck = false;
    input.placeholder = t('Paste the code the page gave you');
    const send = el('button', 'primary', t('Send the code'));
    send.type = 'submit';
    const said = el('p', 'key-said');
    form.append(input, send, said);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      send.disabled = true;
      said.className = 'key-said';
      said.textContent = t('CHECKING…');
      try {
        const response = await fetch(`/api/agents/${agentId}/login/code`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ code: input.value }) });
        const result = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(result.error ?? `HTTP ${response.status}`);
        input.value = '';
        loginNow.awaiting = false;
        said.textContent = t('Sent. The sign-in finishes on its own.');
      } catch (error) {
        said.textContent = error.message;
        said.className = 'key-said bad';
      } finally { send.disabled = false; }
    });
    box.append(form);
  }
  const stop = el('button', 'sx-btn', t('Cancel the sign-in'));
  stop.type = 'button';
  stop.addEventListener('click', async () => { stop.disabled = true; await fetch(`/api/agents/${agentId}/login/cancel`, { method: 'POST' }).catch(() => {}); });
  box.append(stop);
}
// One door or two: Claude's CLI knows the subscription and the Console, and only the human can
// say which account is paying. `null` is the single flow every other CLI has.
// With a session, every agent offers the same «sign in again» as Codex. A single door (Gemini's
// Google account) is that door; two doors (Claude's subscription and Console) are chosen after the
// click, and which agent is choosing is kept here so a repaint does not fold the choice away.
const choosingAccount = new Set();
function loginDoors(agent, signedIn) {
  const methods = agent.login?.methods;
  if (!methods?.length) return [{ id: null, label: signedIn ? t('Sign in again') : t('Sign in'), note: agent.login?.note ?? '' }];
  if (signedIn && methods.length === 1) return [{ id: methods[0].id, label: t('Sign in again'), note: methods[0].note ?? '', again: true }];
  if (signedIn && !choosingAccount.has(agent.id)) return [{ id: null, label: t('Sign in again'), note: agent.login?.note ?? '', again: true, choose: true }];
  return methods.map((method) => ({ id: method.id, label: t(method.label), note: method.note ?? '' }));
}
async function startLogin(agentId, method = null) {
  state.loginLogs.set(agentId, []);
  const response = await fetch(`/api/agents/${agentId}/login`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ method }) });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error ?? `HTTP ${response.status}`);
  loginNow.agent = agentId;
  loginNow.method = method;
  loginNow.url = null;
  loginNow.deviceCode = null;
  loginNow.awaiting = false;
  loginNow.asksForCode = Boolean(result.asksForCode);
  repaintLoginAsk();
  return result;
}


function renderLoginEvent(event) {
  const { agent, command, session, code, error } = event.payload;
  const finished = event.type === 'connection.login.finished';
  const ok = finished && session?.state === 'signed-in';
  const node = el('div', `system login${finished && !ok ? ' failed' : ''}`);
  tint(node, agent);
  node.append(el('b', null, t('connections › ')));
  node.append(finished
    ? (ok ? t('@{agent} signed in', { agent }) + (sessionDetail(session) ? ` · ${sessionDetail(session)}` : '') : t('@{agent} sign-in did not complete', { agent }) + (error ? ` · ${error}` : code ? t(' · exit {code}', { code }) : ''))
    : t('signing in @{agent} · {command}', { agent, command }));
  if (finished) { state.sessions[agent] = session ?? state.sessions[agent]; renderAgents(); renderPicker(); renderOnboarding(); if (state.settingsOpen) void loadSettings(); }
  if (!replaying) {
    if (finished) { if (loginNow.agent === agent) { loginNow.agent = null; loginNow.url = null; loginNow.deviceCode = null; loginNow.awaiting = false; } }
    else { loginNow.agent = agent; loginNow.method = event.payload.method ?? null; loginNow.url = null; loginNow.deviceCode = null; loginNow.awaiting = false; loginNow.asksForCode = Boolean(state.agents.get(agent)?.login?.asksForCode); }
    repaintLoginAsk();
  }
  state.lastSender = null;
  return node;
}
// connections › installing @codex · npm install -g @openai/codex
function renderAgentInstall(event) {
  const { agent, label, command, code, error, detected, version, where, prefix } = event.payload;
  const finished = event.type === 'connection.install.finished';
  const node = paint(el('div', `system connections${finished && !detected ? ' failed' : ''}`), agent);
  node.append(el('b', null, t('connections › ')));
  node.append(finished
    ? (detected ? `${t('{name} installed', { name: label ?? agent })}${version ? ` · ${version}` : ''}${where === 'madre' ? t(" · in MADRE's own folder ({prefix}), no administrator needed", { prefix }) : ''}${t(' · sign in to finish')}` : `${t('{name} was not installed', { name: label ?? agent })}${error ? ` · ${error}` : code ? t(' · exit {code}', { code }) : ''}`)
    : t('installing {label} · {command}', { label: label ?? agent, command }));
  if (finished && !replaying) toast(detected ? t('Diagnostics › {label} is on this computer. Sign in and the project opens.', { label: label ?? agent }) : t('Diagnostics › {label} could not be installed. The log is above.', { label: label ?? agent }));
  if (finished) { renderOnboarding(); if (state.settingsOpen) void loadSettings(); }
  state.lastSender = null;
  return node;
}

function appendLoginOutput(event) {
  const { agent, line, url, deviceCode } = event.payload;
  if (!replaying && loginNow.agent === agent) {
    // The address stays on screen instead of scrolling past: the heartbeat used to be the only
    // line left, so the one thing the human had to open was the first thing MADRE lost.
    if (url) loginNow.url = url;
    // "Enter code: 3475-C193" is a code to show, not a question: no box to paste into.
    if (deviceCode) loginNow.deviceCode = deviceCode;
    else if (looksLikeCodePrompt(line)) loginNow.awaiting = true;
    if (url || deviceCode || looksLikeCodePrompt(line)) repaintLoginAsk();
  }
  // The heartbeat («… still running · 42s · …») says one thing, how long: it takes the place of
  // the one before instead of piling up thirty lines over the address the person needs.
  const beat = HEARTBEAT.test(line ?? '');
  const log = state.loginLogs.get(agent) ?? [];
  if (beat && HEARTBEAT.test(log.at(-1)?.line ?? '')) log.pop();
  log.push({ line, url });
  state.loginLogs.set(agent, log.slice(-60));
  for (const id of [`login-log-${agent}`, `bridge-log-${agent}`]) {
    const box = document.getElementById(id);
    if (!box) continue;
    box.hidden = false;
    if (beat && box.lastElementChild?.classList.contains('beat')) box.lastElementChild.remove();
    box.append(loginLine({ line, url }));
    box.scrollTop = box.scrollHeight;
  }
  // Only while it is happening: a sign-in from earlier in the room, replayed when the page loads,
  // used to come back as a toast carrying a link that expired hours ago.
  if (url && !replaying) toast(t('@{agent}: open {url} to finish signing in', { agent, url }));
}
const HEARTBEAT = /^… still running · \d+s · /;
// MADRE's own «still running» line (src/extensions.mjs, runInstaller), said in the room's language;
// what the installer itself printed stays as it printed it (2026-10-20).
function saidLine(line) {
  const beat = String(line ?? '').match(/^… still running · (\d+)s · (.*)$/);
  return beat ? t('… still running · {seconds}s · {note}', { seconds: beat[1], note: t(beat[2]) }) : line;
}
function loginLine({ line, url }) {
  const div = el('div', HEARTBEAT.test(line ?? '') ? 'beat' : null);
  line = saidLine(line);
  if (url) {
    const a = el('a', null, line); a.href = url; a.target = '_blank'; a.rel = 'noopener noreferrer';
    div.append(a);
  } else div.append(line);
  return div;
}

async function loadSettings() {
  settingsUI.data = await fetch('/api/settings').then((response) => response.json());
  if (settingsUI.data?.settings?.override) state.override = settingsUI.data.settings.override;
  state.sessions = settingsUI.data.sessions ?? state.sessions;
  renderAgents();
  renderPicker();
  // The server is the one that knows whether a sign-in is still waiting: a page reloaded in the
  // middle of one has to find the same address and the same box, not an empty card.
  readLoginState(settingsUI.data.login ?? null);
  renderSettings();
}
// What the server says about the sign-in running right now, adopted as this page's own.
function readLoginState(live) {
  loginNow.agent = live?.agent ?? null;
  loginNow.method = live?.method ?? null;
  loginNow.url = live?.url ?? null;
  loginNow.deviceCode = live?.deviceCode ?? null;
  loginNow.awaiting = Boolean(live?.awaitingCode);
  loginNow.asksForCode = Boolean(live?.asksForCode);
  repaintLoginAsk();
}

/* ---------- the core ---------- */

// Inside the core. Every turn, MADRE writes a document in the human's name and hands it to a
// process, and until now that document existed only for the instant the process was reading it:
// nothing stored it, nobody had ever read one. This is that document, built for the turn that
// has not happened yet, block by block, with what each block weighs and the words themselves.
//
// It is read, never written. What MADRE promises about the crew — that they read by default,
// that they are told not to touch .env — is true because these words are fixed. A core you could
// edit would turn every one of those sentences into a claim about a text somebody may have
// changed. Blocks that can be switched off say where their switch is.
//
// THE SHAPE OF IT. There are four things to see in here and they used to be one scroll: the
// document, the command that carries it, what has left this machine, and MU/TH/UR answering. A
// person looking for one of them had to walk past the other three. So the frame is a terminal —
// four panes, one at a time, the prompt always at the bottom — and it is laid out the way the
// terminal this room is styled after lays out its own output: `==>` over each section, names in
// one column and numbers in another, nothing said twice. Asking for a pane at the prompt opens
// it, so the console and the panes are one way of working rather than two.
const core = {
  dialog: document.querySelector('#core'),
  boot: document.querySelector('#core-boot'),
  body: document.querySelector('#core-body'),
  agent: null,
  mode: 1,
  text: '',
  typing: null,
  last: null,
  outbound: null,
  verdict: null,
  privacy: null,
  strikes: 0,
  history: [],
  console: null,
  pane: 'document',
  panes: null,
  paneNodes: {},
  tabs: null,
};

// Which pane an inquiry is really asking for. The three that are already a screen open that
// screen instead of printing it twice.
const CORE_PANE_FOR = { blocks: 'document', launch: 'launch', egress: 'egress' };

// `==> TITLE        meta`, which is how the terminal this frame is dressed as says "a new thing
// starts here". One rule for every section in every pane, so nothing needs a heading of its own.
function brewHead(title, meta = null) {
  const head = el('p', 'brew-head');
  head.append(el('b', null, '==>'), el('span', 'title', title));
  if (meta) head.append(el('span', 'meta', meta));
  return head;
}

// A name in one column and its value in the other. Homebrew prints its facts this way and it is
// the reason its output is readable at a glance; two dense paragraphs of uppercase are not.
function brewRow(key, value, className = null) {
  const row = el('div', `brew-row${className ? ` ${className}` : ''}`);
  row.append(el('span', 'k', key), el('span', 'v'));
  const slot = row.lastChild;
  if (typeof value === 'string' || typeof value === 'number') slot.textContent = String(value);
  else if (value) slot.append(value);
  return row;
}

async function openCore() {
  if (!core.dialog) return;
  core.agent ??= [...state.agents.values()].find((agent) => agent.ready && agent.id !== 'madre')?.id
    ?? [...state.agents.values()].find((agent) => agent.ready)?.id ?? null;
  // Whatever is half-written in the composer is what you are about to send, so that is what the
  // document is built around.
  core.text = els.input?.value?.trim() ? els.input.value : (core.text ?? '');
  core.strikes = 0;
  // It opens on the board — you and your local model — and the document is one tab away.
  core.pane = 'board';
  core.body.hidden = true;
  core.body.replaceChildren(renderCoreTabs(), renderCoreStrip(), renderCorePanes(), renderCoreConsole());
  showPane(core.pane);
  core.dialog.showModal();
  void fillCoreBoard();
  // On a phone the console is touched to be written in: focused for you, it would put the keyboard
  // up over the core the moment it opened.
  // No typed boot any more (2026-10-09): the core opens as a window of the room, its content at
  // once. The console line stays, at the bottom, for whoever asks it something.
  core.boot.hidden = true;
  core.body.hidden = false;
  if (!state.device) core.console?.field?.focus();
  // What has left this machine is about the room rather than about this turn, so it is read
  // once per visit.
  core.outbound = await fetch('/api/outbound').then((response) => response.json()).catch(() => null);
  await loadCore();
}

async function loadCore() {
  core.panes?.classList.add('reading');
  let briefing;
  try {
    const query = new URLSearchParams({ mode: String(core.mode), ash: String(state.ashInstalled && state.ash), ...(core.agent ? { agent: core.agent } : {}), ...(core.text ? { text: core.text } : {}) });
    briefing = await fetch(`/api/briefing?${query}`).then((response) => response.json());
    if (briefing.error) throw new Error(briefing.error);
  } catch (error) {
    paneInto('document', el('p', 'mother-answer', String(error.message).toUpperCase()));
    core.panes?.classList.remove('reading');
    return;
  }
  core.last = briefing;
  core.agent = briefing.agent;
  // An agent answers at its own ceiling, whatever the strip says.
  const ceiling = core.body.querySelector('.core-ceiling');
  if (ceiling) ceiling.textContent = briefing.ceiling < briefing.mode ? t('MAX MODE FOR @{agent} IS #{max}, SO THIS TURN WOULD BE ANSWERED AT #{ceiling}', { agent: briefing.agent.toUpperCase(), max: briefing.maxMode, ceiling: briefing.ceiling }) : '';
  paneInto('document', renderCoreDoc(briefing));
  paneInto('launch', renderCoreLaunch(briefing.launch ?? null));
  paneInto('egress', renderCoreOutbound(core.outbound));
  drawCoreTabs();
  core.panes?.classList.remove('reading');
}

const paneInto = (id, node) => { core.paneNodes[id]?.replaceChildren(node); };

// The core speaks in sentences (2026-10-09). Its words were written for the terminal, in capitals;
// the room now reads them the way the question sheet does (askWords): a line mostly in capitals is
// lowered, its first letter raised, and what is a name stays as it is — MU/TH/UR, MADRE, a mode, a
// figure («11.0M», «5h»), a path or a version. Unlike the sheet, an @agent is written as the room
// writes it, in lower case. What is literal (pre, code, a select, the console's log) is not touched.
const CORE_KEEP = /^(MADRE|MOTHER|MU\/TH\/UR|CONTROL|AIRLOCK|CREATE|GHOST|EXCHANGE|NOSTROMO|ASH|BISHOP|MCP|SDK|URL|API|CLI|CLIs|JSON|ID|#\d.*|.*[\/\d].*)$/;
function coreWords(text) {
  const words = String(text ?? '');
  const letters = words.replace(/[^\p{L}]/gu, '');
  if (!letters.length || letters.replace(/[^\p{Lu}]/gu, '').length / letters.length <= 0.5) return words;
  // Only a word written all in capitals is lowered: «Claude Code» or «mié» were already written
  // the way they are meant.
  const lower = (word) => {
    const bare = word.replace(/[.,:;?!¿¡…·()]+$/u, '').replace(/^[(¿¡]+/u, '');
    return CORE_KEEP.test(bare) || /\p{Ll}/u.test(bare) ? word : word.toLowerCase();
  };
  // A sentence that starts after a full stop starts with its capital too.
  const said = words.split(/(\s+)/).map(lower).join('').replace(/([.!?]\s+)(\p{Ll})/gu, (_, stop, letter) => stop + letter.toUpperCase());
  // The first letter rises when the line starts with a word; «18 bloques» and «@codex» stay low.
  const lead = said.match(/^[\s"'«(¿¡]*/u)[0].length;
  return /\p{Ll}/u.test(said.charAt(lead)) ? said.slice(0, lead) + said.charAt(lead).toUpperCase() + said.slice(lead + 1) : said;
}
function coreSentences(root) {
  if (!root || typeof document.createTreeWalker !== 'function') return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: (node) => (node.parentElement?.closest('pre, code, kbd, textarea, select, option, .console-log') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT) });
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const said = coreWords(node.nodeValue);
    if (said !== node.nodeValue) node.nodeValue = said;
  }
  for (const field of root.querySelectorAll?.('input[placeholder], textarea[placeholder]') ?? []) field.placeholder = coreWords(field.placeholder);
}
// Whatever the core draws, whenever it draws it, is read in sentences. A lowered line is already
// in sentences, so a second pass changes nothing and the watch never feeds itself.
if (core.body && typeof MutationObserver === 'function') new MutationObserver(() => coreSentences(core.body)).observe(core.body, { childList: true, subtree: true });

/* ---------- pane · your core ---------- */

// The first thing the core shows, as a board in the console's own pieces — the tiles, cards and
// meters of MEMORY: the person the room speaks for, and the model on this computer that keeps the
// room's memory. Who has a session and how much of each limit is spent; what the local model is,
// what it runs on and how well it knows this room; what the archive holds; and the settings that
// decide who reads it. Every figure comes from what the room already holds (its agents and their
// sessions) or from a route it already has (/api/ollama, /api/maturity, /api/memory/dashboard,
// /api/settings), and every switch calls one. What nobody has measured says so.
const SESSION_WORDS = { 'signed-in': t('SIGNED IN'), 'signed-out': t('SIGNED OUT') };
async function fillCoreBoard() {
  const pane = core.paneNodes.board;
  if (!pane) return;
  const read = (url) => fetch(url).then((response) => (response.ok ? response.json() : null)).catch(() => null);
  const [olla, grown, dash, settings] = await Promise.all([read('/api/ollama'), read('/api/maturity'), read('/api/memory/dashboard'), read('/api/settings')]);
  const o = olla?.ollama ?? null;
  const d = dash?.dashboard ?? null;
  const m = grown?.maturity ?? null;
  const v = grown?.verdict ?? null;
  core.local = o ? { running: Boolean(o.running), chatModel: o.chatModel ?? null } : null;
  drawCoreTabs();
  const board = el('div', 'mem-dash core-board');

  // You: the sessions, the room's window, and each agent's limit.
  const crew = [...state.agents.values()].filter((agent) => agent.detected && !agent.local);
  const signed = crew.filter((agent) => sessionOf(agent) === 'signed-in');
  const spent = crew.reduce((sum, agent) => sum + (agent.tokens ?? 0), 0);
  const ever = crew.reduce((sum, agent) => sum + (agent.rawTokens ?? 0), 0);
  board.append(brewHead(t('YOU'), projectDesignation() || null));
  const you = el('div', 'mem-kpis');
  memTile(you, { label: t('SIGNED IN'), value: `${signed.length}/${crew.length}`, sub: signed.length ? signed.map((agent) => `@${agent.id}`).join(' · ') : t('NOBODY YET') });
  memTile(you, { label: t('PROJECT USAGE'), value: formatTokens(spent) || '0', sub: state.budget ? t('OF {budget} TOKENS · 5H', { budget: formatTokens(state.budget) }) : t('NO BUDGET SET'), meter: state.budget ? Math.min(1, spent / state.budget) : null });
  memTile(you, { label: t('ALL-TIME IN PROJECT'), value: formatTokens(ever) || '0', sub: t('TOKENS THE AGENTS HAVE SPENT HERE') });
  board.append(you);
  if (crew.length) {
    const grid = el('div', 'mem-grid');
    const card = memCard(grid, t('BY AGENT'), 'span-12');
    for (const agent of crew) {
      const official = liveOfficial(agent);
      const shown = ringPercent(agent);
      const row = el('div', `mem-signal${shown >= 80 ? ' hot' : ''}`);
      const top = el('div', 'top');
      top.append(el('b', null, `@${agent.id.toUpperCase()} · ${SESSION_WORDS[sessionOf(agent)] ?? t('SESSION UNKNOWN')}`), el('span', null, `${Math.round(shown)}%`));
      const facts = [
        official === null ? (state.budget ? t('LOCAL 5H WINDOW') : null) : t("PROVIDER'S {window} LIMIT", { window: fmtWindow(agent.officialWindows?.primary?.windowMinutes ?? 300) }),
        agent.officialResetAt ? t('RESETS {when}', { when: fmtReset(agent.officialResetAt) }) : null,
        agent.rawTokens ? t('{n} TOKENS IN THE PROJECT', { n: formatTokens(agent.rawTokens) }) : null,
        agent.version ?? null,
      ].filter(Boolean);
      row.append(top, memMeter(shown / 100), el('span', 'detail', facts.join(' · ')));
      card.append(row);
    }
    board.append(grid);
  }

  // The local model: what runs, what it is given, and when it was last asked.
  const localHead = brewHead(t('YOUR LOCAL MODEL'), o ? (o.running ? t('RUNNING') : t('OFF')) : t('UNAVAILABLE'));
  board.append(localHead);
  if (!o) board.append(el('p', 'note', t('LOCAL AI IS NOT WIRED IN THIS PROJECT · OPEN MODULES → LOCAL AI')));
  else {
    // When it was read and the way to read it again, at the end of its own heading.
    const head = el('span', 'brew-actions');
    head.append(el('span', 'when', t('READ {time}', { time: formatTime(new Date().toISOString()) })));
    if (!o.running && o.binary) {
      const start = el('button', 'primary', t('START OLLAMA'));
      start.type = 'button';
      start.addEventListener('click', async () => { start.disabled = true; await fetch('/api/ollama/start', { method: 'POST' }).catch(() => null); await fillCoreBoard(); });
      head.append(start);
    }
    const recheck = el('button', null, t('RECHECK'));
    recheck.type = 'button';
    recheck.addEventListener('click', async () => { recheck.disabled = true; await fetch('/api/ollama/probe', { method: 'POST' }).catch(() => null); await fillCoreBoard(); });
    head.append(recheck);
    localHead.append(head);

    const local = el('div', 'mem-kpis');
    memTile(local, { label: t('SERVER'), value: o.running ? (o.version ? `v${o.version}` : t('ON')) : t('OFF'), sub: o.running ? o.host : (o.error ?? t('not running')) });
    memTile(local, { label: t('CHAT'), value: o.madreModel ?? o.chatModel ?? '—', sub: o.madreModel ? t('TRAINED FOR THIS PROJECT') : t('NOT TRAINED FOR THIS PROJECT YET') }).classList.add('word');
    memTile(local, { label: t('SEARCH BY MEANING'), value: o.embedModel ?? '—', sub: d?.vectors ? t('{n} SEARCHABLE BY MEANING', { n: memFmt((d.vectors.memories ?? 0) + (d.vectors.entries ?? 0)) }) : t('RECALL MATCHES WORDS ONLY') }).classList.add('word');
    const measured = state.localModel?.checked;
    memTile(local, { label: t('MEASURED HERE'), value: measured ? `${measured.matched}/${measured.n}` : '—', sub: measured ? t('LANDED WHERE THE AGENTS DID · {verdict}', { verdict: measured.passed ? t('READY') : t('NOT YET') }) : t('NOT MEASURED YET'), meter: measured?.n ? measured.matched / measured.n : null });
    board.append(local);

    const models = o.models ?? [];
    if (models.length) {
      const grid = el('div', 'mem-grid');
      const card = memCard(grid, t('INSTALLED · {n}', { n: models.length }), 'span-12');
      const largest = Math.max(1, ...models.map((model) => model.size || 0));
      for (const model of models) {
        const row = el('div', 'mem-signal');
        const top = el('div', 'top');
        top.append(el('b', null, model.name), el('span', null, formatSize(model.size || 0)));
        const role = [model.name === o.madreModel ? '@MADRE' : null, model.name === o.chatModel ? t('CHAT') : null, model.name === o.embedModel ? t('SEARCH BY MEANING') : null].filter(Boolean);
        const facts = [...role, model.details?.parameter_size, model.details?.quantization_level, model.family].filter(Boolean);
        row.append(top, memMeter((model.size || 0) / largest));
        if (facts.length) row.append(el('span', 'detail', facts.join(' · ')));
        card.append(row);
      }
      board.append(grid);
    }
  }

  // How well it knows this room: the stage, the archive's figures, what it is made of, the tests.
  board.append(brewHead(t('THE QUALITY'), m?.stage?.label ?? null));
  if (!m || !v || !d) board.append(el('p', 'note', t('NOTHING TO READ YET: THE PROJECT HAS NO ARCHIVE.')));
  else {
    const figures = el('div', 'mem-kpis');
    memTile(figures, { label: t('MEMORY PROGRESS'), value: memPct(m.score), sub: m.stage.label, meter: m.score, title: m.stage.says });
    memTile(figures, { label: t('EXCHANGES'), value: memFmt(d.totals.entries), sub: memWeek(d.weeks.entries) });
    memTile(figures, { label: t('MEMORIES'), value: memFmt(d.totals.memories), sub: memWeek(d.weeks.memories) });
    memTile(figures, { label: t('WAITING'), value: memFmt(d.totals.pending), sub: d.totals.pending ? t('EXCHANGES NOBODY HAS DISTILLED YET') : t('THE ARCHIVIST IS UP TO DATE') });
    board.append(figures, memVerdict(m, v));
    const grid = el('div', 'mem-grid');
    memSignals(memCard(grid, t('WHAT THE ARCHIVE IS MADE OF'), 'span-12'), m);
    memCard(grid, t('MEMORY REVIEW'), 'span-12').append(examsBlock(grown.exams ?? null, { pass: d.pass ?? null }));
    board.append(grid);
  }

  // Who reads the archive, and what the local model is given to do.
  board.append(brewHead(t('SETTINGS')));
  const grid = el('div', 'mem-grid');
  if (o) {
    const does = memCard(grid, t('WHAT THE LOCAL MODEL DOES'), 'span-6');
    const role = (key, word, said) => {
      const label = el('label', 'core-role');
      const box = el('input');
      box.type = 'checkbox';
      box.checked = o.settings?.[key] !== false;
      box.addEventListener('change', async () => {
        box.disabled = true;
        const response = await fetch('/api/ollama/settings', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ [key]: box.checked }) }).catch(() => null);
        if (!response?.ok) { box.checked = !box.checked; toast(t('Diagnostics › that could not be changed.')); }
        box.disabled = false;
      });
      const words = el('span', 'core-role-words');
      words.append(el('b', null, word), el('span', 'detail', said));
      label.append(box, words);
      return label;
    };
    does.append(
      role('embeddings', t('SEARCH BY MEANING'), t('Prepares each memory so recall can find it by meaning.')),
      role('archivist', t('ARCHIVIST'), t('Distils the exchanges into memories, on this computer.')),
      role('agent', '@MADRE', t('Answers in the project as the fifth agent.')),
    );
  }
  const mem = settings?.settings?.memory;
  if (mem) {
    const reads = memCard(grid, t('WHO READS THE ARCHIVE'), o ? 'span-6' : 'span-12');
    const save = async (patch, said) => { try { await saveSettingNow({ memory: patch }, said); } catch (error) { toast(`${t('Diagnostics › ')}${error.message}`); } };
    const archivist = el('select');
    for (const [value, text] of [['auto', t('AUTO')], ...mem.candidates.map((one) => [one.id, one.label])]) {
      const option = el('option', null, text);
      option.value = value;
      if (value === (mem.archivist ?? 'auto')) option.selected = true;
      archivist.append(option);
    }
    archivist.addEventListener('change', () => save({ archivist: archivist.value }, t('archivist: {what}.', { what: archivist.options[archivist.selectedIndex].textContent })));
    const embed = el('select');
    for (const [value, text] of [['auto', t('AUTO · Ollama if running, else Gemini')], ['ollama', `OLLAMA · ${t('local')}${mem.ollama?.embedModel ? ` · ${mem.ollama.embedModel}` : t(' · no model yet')}`], ['gemini', t('GEMINI · needs your key')], ['off', t('OFF · words only')]]) {
      const option = el('option', null, text);
      option.value = value;
      if (value === (mem.embedProvider ?? 'auto')) option.selected = true;
      embed.append(option);
    }
    embed.addEventListener('change', () => save({ embedProvider: embed.value }, t('search by meaning: {what}.', { what: embed.options[embed.selectedIndex].textContent.toLowerCase() })));
    const field = (word, control) => { const label = el('label', 'core-field'); label.append(el('span', 'k', word), control); return label; };
    reads.append(field(t('ARCHIVIST'), archivist), field(t('SEARCH BY MEANING'), embed));
    if (mem.envWins) reads.append(el('p', 'note', t('AN ENVIRONMENT VARIABLE IS SETTING SOME OF THIS, AND IT WINS OVER WHAT YOU CHOOSE HERE.')));
  }
  if (grid.childElementCount) board.append(grid);
  paneInto('board', board);
}

/* ---------- the strip: who it goes to, at what mode, around what ---------- */

// Built once per visit and never rebuilt, so what you are typing survives every rebuild of the
// panes underneath it.
function renderCoreStrip() {
  const strip = el('div', 'core-strip');
  core.strip = strip;

  const pick = el('div', 'core-pick');
  pick.append(el('span', 'k', t('TO')));
  const who = el('div', 'core-agents');
  for (const agent of [...state.agents.values()].filter((agent) => agent.detected)) {
    const chip = el('button', `core-agent${agent.id === core.agent ? ' on' : ''}${agent.ready ? '' : ' cold'}`, `@${agent.id}`);
    chip.type = 'button';
    chip.dataset.agent = agent.id;
    chip.title = agent.ready ? t('What @{agent} would be told', { agent: agent.id }) : t('{label} has no session; this is what it would be told', { label: agent.label });
    chip.addEventListener('click', () => {
      core.agent = agent.id;
      for (const other of who.children) other.classList.toggle('on', other.dataset?.agent === agent.id);
      void loadCore();
    });
    who.append(chip);
  }
  pick.append(who, el('span', 'k', t('AT')));
  const modes = el('select');
  for (const [value, label] of [0, 1, 2, 3, 4].map((n) => [n, `#${n} ${MODES[n].label}`])) {
    const option = el('option', null, label);
    option.value = String(value);
    if (value === core.mode) option.selected = true;
    modes.append(option);
  }
  modes.addEventListener('change', () => { core.mode = Number(modes.value); void loadCore(); });
  pick.append(modes, el('span', 'core-ceiling', ''));
  strip.append(pick);

  // What you are about to ask. Recall, the memories and the closing question are written around
  // it, so a briefing for an empty message is a briefing for a turn nobody is going to have.
  const asking = el('label', 'core-asking');
  asking.append(el('span', 'k', t('IF YOU SENT')));
  const field = el('textarea');
  field.id = 'core-text';
  field.rows = 1;
  field.placeholder = t('type the question you would send, and see here what MADRE would send the agent');
  field.value = core.text ?? '';
  field.addEventListener('input', () => {
    core.text = field.value;
    field.rows = Math.min(3, field.value.split('\n').length);
    clearTimeout(core.typing);
    core.typing = setTimeout(() => { void loadCore(); }, 450);
  });
  asking.append(field);
  asking.append(el('span', 'note', t('NOTHING IS SENT FROM HERE.')));
  strip.append(asking);
  return strip;
}

/* ---------- the panes ---------- */

const CORE_TABS = [
  { id: 'board', label: t('WHAT IS SENT') },
  { id: 'document', label: t('DOCUMENT') },
  { id: 'launch', label: t('LAUNCH') },
  { id: 'egress', label: t('OUTBOUND') },
  { id: 'console', label: t('DIAGNOSTICS') },
];
// The strip — who it goes to, at what mode, around what — is about the next turn, so it shows
// with the two panes that are about the next turn and nowhere else.
const CORE_STRIP_PANES = new Set(['document', 'launch']);

function renderCoreTabs() {
  const tabs = el('nav', 'core-tabs');
  tabs.setAttribute('role', 'tablist');
  for (const tab of CORE_TABS) {
    const button = el('button', 'core-tab');
    button.type = 'button';
    button.dataset.tab = tab.id;
    button.setAttribute('role', 'tab');
    button.append(el('b', null, tab.label), el('span', 'meta', ''));
    button.addEventListener('click', () => showPane(tab.id));
    tabs.append(button);
  }
  core.tabs = tabs;
  return tabs;
}

// What each tab says about what is behind it, so nobody has to open a pane to find out whether
// it holds anything.
function drawCoreTabs() {
  if (!core.tabs) return;
  const briefing = core.last;
  const tokens = briefing ? t(' · ≈{n} TOKENS', { n: tokensFor(briefing.chars).toLocaleString() }) : '';
  const on = (core.outbound?.destinations ?? []).filter((one) => one.on === true).length;
  const meta = {
    document: briefing ? t('{n} BLOCKS · {ch} CH', { n: briefing.parts.length, ch: briefing.chars.toLocaleString() }) + tokens : t('READING…'),
    launch: briefing?.launch ? (briefing.launch.local ? t('NO PROCESS') : t('@{agent} · {n} ARGS', { agent: briefing.agent, n: briefing.launch.args.length })) : '—',
    egress: core.outbound ? t('{n} ADDRESSES · {on} ON', { n: core.outbound.destinations.length, on }) : '—',
    board: core.local ? (core.local.running ? (core.local.chatModel ?? t('NO CHAT MODEL')) : t('LOCAL MODEL OFF')) : t('READING…'),
    console: core.history.length ? t('{n} ASKED', { n: core.history.length }) : t('ASK ME'),
  };
  for (const button of core.tabs.children) {
    button.classList.toggle('on', button.dataset.tab === core.pane);
    button.setAttribute('aria-selected', button.dataset.tab === core.pane ? 'true' : 'false');
    button.lastChild.textContent = meta[button.dataset.tab] ?? '';
  }
}

function renderCorePanes() {
  const panes = el('div', 'core-panes');
  // The panes are held by name rather than looked up: there are four of them, they never move,
  // and a selector is a way of being wrong about that later.
  core.paneNodes = {};
  for (const tab of CORE_TABS) {
    const pane = el('section', 'core-pane');
    pane.dataset.pane = tab.id;
    pane.setAttribute('role', 'tabpanel');
    if (tab.id !== core.pane) pane.hidden = true;
    core.paneNodes[tab.id] = pane;
    panes.append(pane);
  }
  core.panes = panes;
  return panes;
}

function showPane(id) {
  core.pane = id;
  for (const [name, pane] of Object.entries(core.paneNodes)) pane.hidden = name !== id;
  if (core.strip) core.strip.hidden = !CORE_STRIP_PANES.has(id);
  drawCoreTabs();
  if (core.panes) core.panes.scrollTop = 0;
}

/* ---------- pane · the document ---------- */

function renderCoreDoc(briefing) {
  const doc = el('div', 'core-doc');
  doc.append(brewHead(t('THE DOCUMENT'), t('{n} BLOCKS · {ch} CH · ≈{tokens} TOKENS', { n: briefing.parts.length, ch: briefing.chars.toLocaleString(), tokens: tokensFor(briefing.chars).toLocaleString() })));
  doc.append(el('p', 'note', t('BUILT NOW AND SENT NOWHERE. CHANGE WHO IT GOES TO AND THE WORDS CHANGE; RAISE THE MODE AND THE PERMISSION IT WOULD BE GIVEN APPEARS, WRITTEN OUT.')));
  if (briefing.dynamic) doc.append(el('p', 'note', t('The Coordinator fetches notes from signed connections when you send. They are not shown in this preview, so looking here does not use a connection reading.')));

  // The blocks in the document's own order, which is the order they are said in.
  const widest = briefing.parts.reduce((top, part) => Math.max(top, part.chars), 1);
  const blocks = el('div', 'core-blocks');
  for (const part of briefing.parts) {
    const row = el('details', 'core-block');
    const head = el('summary');
    head.append(el('i', 'sign', '+'));
    head.append(el('b', null, part.id.toUpperCase()));
    head.append(el('span', 'n', `${part.chars.toLocaleString()} CH`));
    // `weigh`, not `bar`: .bar is the room's own top bar, and a name taken twice in one
    // stylesheet is a rule you did not write arriving on an element you did not mean.
    const weigh = el('i', 'weigh');
    weigh.style.setProperty('--fill', `${Math.max(2, Math.round((part.chars / widest) * 100))}%`);
    head.append(weigh);
    head.append(el('span', 'when', part.when === 'always' ? t('ALWAYS') : part.when));
    row.addEventListener('toggle', () => { head.querySelector('.sign').textContent = row.open ? '−' : '+'; });
    const body = el('div', 'core-text');
    // What put these words here, and where the human takes them away. Nothing in the core can be
    // rewritten; some of it can be switched off, and this says exactly where.
    if (part.when || part.where) {
      const from = el('p', 'core-from');
      from.append(el('b', null, part.when === 'always' ? t('ALWAYS') : t('HERE BECAUSE')));
      if (part.when !== 'always') from.append(` ${part.when}`);
      if (part.where) from.append(el('span', 'where', ` · ${part.where}`));
      else if (part.when !== 'always') from.append(el('span', 'where', t(' · nothing switches it off; it goes when the reason goes')));
      body.append(from);
    }
    body.append(el('pre', null, part.text));
    const copy = el('button', 'core-copy-one', t('COPY'));
    copy.type = 'button';
    copy.addEventListener('click', async () => {
      try { await navigator.clipboard.writeText(part.text); copy.textContent = t('COPIED'); setTimeout(() => { copy.textContent = t('COPY'); }, 1200); }
      catch { toast(t('The clipboard is not available here.')); }
    });
    body.append(copy);
    row.append(head, body);
    blocks.append(row);
  }
  doc.append(blocks);

  // What the window holds and what it leaves behind: the one thing that explains the heaviest
  // block in the document. As two columns, because it is four facts and not a paragraph.
  const window = briefing.window ?? {};
  doc.append(brewHead(t('WHAT IT CARRIES')));
  const carried = el('div', 'brew-rows');
  carried.append(brewRow(t('TRANSCRIPT'), window.from && window.through
    ? t('#{from} → #{through} · {n} MESSAGES', { from: window.from, through: window.through, n: window.carried })
    : t('THE WHOLE PROJECT STILL FITS')));
  if (window.omitted) carried.append(brewRow(t('LEFT BEHIND'), t('{n} OLDER MESSAGES · WHICH IS WHAT RECALL IS FOR', { n: window.omitted })));
  carried.append(brewRow(t('READ TO BUILD IT'), t('{m} MEMORIES · {q} EXACT QUOTES', { m: briefing.recalled, q: briefing.quoted })));
  carried.append(brewRow(t('NOT COUNTED'), t('NONE OF THEM COUNTS AS USED: THIS IS A PREVIEW, NOT A REAL ANSWER')));
  carried.append(brewRow(t('WEIGHT'), t('{ch} CH · ≈{tokens} TOKENS · ESTIMATED AT {rate} CH/TOKEN, NOT MEASURED: MADRE DOES NOT HAVE THE PROVIDER\'S TOKENIZER', { ch: briefing.chars.toLocaleString(), tokens: tokensFor(briefing.chars).toLocaleString(), rate: CH_PER_TOKEN })));
  if (briefing.spared) carried.append(brewRow(t('LEFT OUT'), t('{n} CHARACTERS THIS TURN HAS NO USE FOR', { n: briefing.spared.toLocaleString() })));
  doc.append(carried);

  doc.append(brewHead(t('FIXED')));
  doc.append(el('p', 'core-fixed', t('YOU CANNOT EDIT THIS. WHAT MADRE PROMISES ABOUT THE AGENTS IS TRUE BECAUSE THESE WORDS ARE FIXED. OPEN A BLOCK AND IT SAYS WHAT PUT IT THERE AND WHERE YOU TAKE IT AWAY: SWITCHED OFF, NEVER REWRITTEN.')));
  return doc;
}

/* ---------- pane · the launch ---------- */

// THE LAUNCH. The document is the half a person can read; this is the half that runs it.
// A briefing is handed to a process, and until you can see which process, with which flags, in
// which directory, reading which servers, "the agent works read-only" is a claim rather than a
// fact. So the exact command is printed, built by the same adapters that would build it for real.
//
// Environment values are never printed — only the names. A command line is something people
// screenshot, and the values are where keys live.
function shellArg(value) {
  return /^[\w@%+=:,./-]+$/.test(value) ? value : `'${String(value).replaceAll("'", `'\\''`)}'`;
}

function renderCoreLaunch(launch) {
  const floor = el('div', 'core-launch');
  floor.append(brewHead(t('THE LAUNCH'), t('WHAT MADRE WOULD RUN TO DELIVER IT')));

  if (!launch) { floor.append(el('p', 'note', t('NO AGENT IS PICKED, SO THERE IS NO COMMAND TO SHOW.'))); return floor; }
  if (launch.local || !launch.args) { floor.append(el('p', 'note', String(launch.says ?? '').toUpperCase())); return floor; }

  const command = [launch.executable, ...launch.args].map(shellArg);
  floor.append(commandBlock([t('# run in {dir}', { dir: launch.cwd }), ...command.map((part, at) => (at === 0 ? part : `  ${part}`) + (at === command.length - 1 ? '' : ' \\'))]));
  floor.append(el('p', 'note', t('THE BRIEFING GOES WHERE {marker} IS WRITTEN. NOTHING IS RUN FROM HERE.', { marker: launch.promptMarker.toUpperCase() })));

  if (launch.isolation?.length) {
    floor.append(brewHead(t('WHAT KEEPS IT TO THIS TURN')));
    const rows = el('div', 'brew-rows');
    for (const line of launch.isolation) {
      const [name, rest] = line.includes(':') ? [line.slice(0, line.indexOf(':')), line.slice(line.indexOf(':') + 1).trim()] : ['', line];
      rows.append(brewRow(name || '—', rest));
    }
    floor.append(rows);
  }

  if (launch.env?.length) {
    floor.append(brewHead(t('ENVIRONMENT IT IS GIVEN'), t('NAMES ONLY. NO VALUE IS EVER SHOWN HERE.')));
    const rows = el('div', 'brew-rows');
    for (const one of launch.env) rows.append(brewRow(one.name, one.note));
    floor.append(rows);
  }

  const servers = [...(launch.memoryServer ? [{ ...launch.memoryServer, brief: t('the archive of this project, read and written through MADRE') }] : []), ...(launch.mcpServers ?? [])]
    .filter((server, at, all) => all.findIndex((other) => other.name === server.name) === at);
  if (servers.length) {
    floor.append(brewHead(t('OUTSIDE TOOLS (MCP) IT CAN USE'), `${servers.length}`));
    const rows = el('div', 'brew-rows');
    for (const server of servers) {
      const value = el('span');
      if (server.brief) value.append(server.brief);
      if (server.tools?.length) {
        const tools = el('span', 'tools');
        for (const tool of server.tools) tools.append(el('i', null, tool));
        value.append(tools);
      }
      if (server.env?.length) value.append(el('span', 'where', ` · env: ${server.env.join(', ')}`));
      rows.append(brewRow(server.name, value, 'core-server'));
    }
    floor.append(rows);
  }
  return floor;
}

/* ---------- pane · what left this machine ---------- */

// MADRE keeps what it knows in a file you own, and that sentence is worth exactly as much as the
// list that qualifies it. This is the list: every address this process may reach, what it says
// there, what turns it off — and beside it, what actually went out, counted by the wrapper every
// fetch in this process goes through, a module's included.
function renderCoreOutbound(view) {
  const floor = el('div', 'core-outbound');
  floor.append(brewHead(t('OUTBOUND'), t('EVERY ADDRESS MADRE CAN REACH, AND WHETHER IT IS ON TODAY')));
  if (!view) { floor.append(el('p', 'note', t('THE LOG COULD NOT BE READ.'))); return floor; }

  const list = el('div', 'core-egress');
  for (const one of view.destinations) {
    const row = el('div', `egress${one.on === false ? ' off' : ''}${one.local ? ' local' : ''}`);
    const state = el('span', 'state', one.local ? t('LOCAL') : one.on === true ? t('ON') : one.on === false ? t('OFF') : '—');
    const to = el('b', null, one.to);
    const what = el('p', 'what', one.what);
    const when = el('p', 'when');
    when.append(el('i', null, one.when));
    if (one.where) when.append(el('span', 'where', ` · ${one.where}`));
    const count = el('span', 'n', one.calls
      ? t('{n} REQUESTS', { n: one.calls }) + (one.failed ? t(' · {n} FAILED', { n: one.failed }) : '') + (one.last ? ` · ${agoWords(one.last).toUpperCase()}` : '')
      : one.inside ? t('NOTHING YET') : t('NOT THROUGH MADRE'));
    row.append(state, to, count, what, when);
    list.append(row);
  }
  floor.append(list);
  floor.append(el('p', 'note', view.says.toUpperCase()));

  // The log itself, which is what makes the list above checkable rather than a promise.
  const lines = view.recent ?? [];
  floor.append(brewHead(t('THE LAST REQUESTS THIS PROCESS MADE'), t('{n} LINES', { n: lines.length })));
  const pre = el('pre', 'core-egress-log');
  pre.textContent = lines.length
    ? lines.map((line) => `${line.at.replace('T', ' ').slice(0, 19)}  ${line.ok ? 'ok ' : '×  '}${String(line.status ?? line.error ?? '').padEnd(4)} ${line.method.padEnd(4)} ${line.to}${line.path}${line.params ? `?${line.params.join('&')}` : ''}`).join('\n')
    : t('Nothing has gone out of this process yet.');
  floor.append(pre);
  floor.append(el('p', 'core-from', t('NO BODY, NO HEADER AND NO QUERY VALUE IS EVER WRITTEN HERE — ONLY WHICH PARAMETERS WERE SET. THE GEMINI EMBEDDING ADDRESS CARRIES THE KEY IN THE URL, AND AN OUTBOUND LOG WOULD BE A POOR PLACE TO LEAVE IT.')));
  return floor;
}

/* ---------- the prompt, always at the bottom ---------- */

// MU/TH/UR 6000 answered by being asked. The core already holds everything an answer would need,
// and a person reading four panes still has to find the pane that holds their question. So the
// prompt is the way through all of it: an inquiry that is a pane opens the pane, and everything
// else is answered in her own pane, from what this page already has. Nothing is sent from here
// and nothing is asked of the crew.
//
// She answers or she says she cannot. Three inquiries she cannot parse and the frame closes —
// that is the machine this is, and it is fair about it: every refusal names what she would have
// taken, the count is on screen from the first one, and opening the core again starts over.
function renderCoreConsole() {
  const log = el('pre', 'console-log');
  const say = (lines, className = null) => {
    const block = el('span', className);
    block.textContent = `${lines.join('\n')}\n\n`;
    log.append(block);
    if (core.panes) core.panes.scrollTop = core.panes.scrollHeight;
  };
  core.paneNodes.console?.replaceChildren(brewHead('MU/TH/UR 6000', t('ANSWERED FROM WHAT IS ALREADY IN THIS PROJECT')), log);

  const marks = el('span', 'console-strikes');
  const drawStrikes = () => {
    marks.replaceChildren();
    for (let at = 0; at < STRIKES; at += 1) marks.append(el('i', at < core.strikes ? 'on' : null, '▮'));
    marks.title = t('{n} inquiry attempts left before this interface closes', { n: STRIKES - core.strikes });
  };

  const line = el('form', 'console-line');
  const field = el('input');
  field.type = 'text';
  field.autocomplete = 'off';
  field.spellcheck = false;
  field.setAttribute('aria-label', t('Inquiry'));
  field.placeholder = t('READY FOR INQUIRY · TYPE HELP');
  let walked = null;
  field.addEventListener('keydown', (event) => {
    if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return;
    if (!core.history.length) return;
    event.preventDefault();
    walked = walked === null ? core.history.length - 1 : Math.min(core.history.length - 1, Math.max(0, walked + (event.key === 'ArrowUp' ? -1 : 1)));
    field.value = core.history[walked] ?? '';
  });
  const help = el('button', 'console-help', t('HELP'));
  help.type = 'button';
  help.addEventListener('click', () => { field.value = 'HELP'; line.requestSubmit(); });
  line.append(el('span', 'prompt', '>'), field, marks, help);

  line.addEventListener('submit', async (event) => {
    event.preventDefault();
    const asked = field.value.trim();
    if (!asked) return;
    field.value = '';
    walked = null;
    core.history.push(asked);
    say([`> ${asked.toUpperCase()}`], 'said');

    // Two answers need something this page has not read yet; they are fetched when they are
    // asked for, so opening the core stays one request.
    const wanted = answerFor(asked, { strikes: core.strikes });
    if (wanted.needs === 'verdict' && !core.verdict) {
      core.verdict = await fetch('/api/maturity').then((response) => response.json()).then((read) => read?.verdict ?? null).catch(() => null);
    }
    if (wanted.needs === 'privacy' && !core.privacy) {
      // Only the count and the marker cross into here. The words themselves never enter the
      // console, so nothing in it can print them.
      core.privacy = await fetch('/api/privacy').then((response) => response.json())
        .then((read) => ({ terms: (read?.terms ?? []).length, marker: read?.marker ?? null })).catch(() => null);
    }
    const answer = answerFor(asked, {
      strikes: core.strikes,
      briefing: core.last,
      outbound: core.outbound,
      rate: CH_PER_TOKEN,
      verdict: core.verdict,
      privacy: core.privacy,
      agents: [...state.agents.values()],
    });
    core.strikes = answer.strikes;
    drawStrikes();
    say(answer.lines, answer.strike ? 'refused' : null);
    // An inquiry that is already a pane opens it; everything else is read where it was answered.
    showPane(CORE_PANE_FOR[answer.id] ?? 'console');
    if (answer.closes) {
      field.disabled = true;
      setTimeout(() => core.dialog.close(), 1800);
    }
  });

  drawStrikes();
  core.console = { field, say };
  say([t('READY FOR INQUIRY. HELP LISTS WHAT I ANSWER.')]);
  return line;
}

document.querySelector('#core-close')?.addEventListener('click', () => core.dialog.close());
document.querySelector('#core-copy')?.addEventListener('click', async () => {
  if (!core.last) return;
  try {
    await navigator.clipboard.writeText(core.last.parts.map((part) => part.text).join('\n'));
    toast(core.last.dynamic
      ? t('Diagnostics › preview copied. The Coordinator adds notes from signed connections when you send.')
      : t('Diagnostics › the whole briefing is on your clipboard, exactly as the agent receives it.'));
  } catch { toast(t('The clipboard is not available here.')); }
});

/* ---------- the MEMORY dashboard ---------- */

// What the archive holds and how it is doing, in one screen that is read before it is touched.
// Everything on it is a count the room already keeps (/api/memory/dashboard) or a reading it
// already takes (/api/maturity). No memory's text is on this screen, which is why it opens
// without the designation NOSTROMO asks for.
//
// The charts are plain elements, not a library: a column is a box with a height, which is all a
// phosphor screen needs, and it stays crisp at any width. One green, because every chart here
// compares amounts of one thing; where an entity already has a colour of its own (a memory's kind
// on the NOSTROMO map) it travels as a small key beside the word, never as the only way to tell.
const memFmt = (n) => Number(n ?? 0).toLocaleString(language());
const memPct = (value) => `${Math.round(Number(value ?? 0) * 100)}%`;
const memDay = (day) => {
  const [y, m, d] = String(day).split('-').map(Number);
  return new Date(y, m - 1, d).toLocaleDateString(language(), { day: 'numeric', month: 'short' }).replace('.', '').toUpperCase();
};

function memCard(parent, title, className = '') {
  const card = el('section', `mem-card${className ? ` ${className}` : ''}`);
  card.append(el('h4', null, title));
  parent.append(card);
  return card;
}

// A row of columns from a baseline. Empty days keep their slot and show a hairline stub, so a
// quiet stretch reads as quiet instead of closing up; the last column is today.
function memColumns(values, className = 'mem-cols') {
  const box = el('div', className);
  const top = Math.max(1, ...values);
  for (const [i, n] of values.entries()) {
    const col = el('i', n ? null : 'zero');
    if (n) col.style.setProperty('--h', `${Math.max(6, (n / top) * 100)}%`);
    if (i === values.length - 1) col.classList.add('now');
    box.append(col);
  }
  return box;
}

// A filled bar against its own track: how much of a whole, or how far toward a mark.
function memMeter(value, { mark = null } = {}) {
  const track = el('span', 'mem-meter');
  const fill = el('i');
  fill.style.width = `${Math.min(100, Math.max(0, value * 100))}%`;
  track.append(fill);
  if (mark !== null) {
    const line = el('b', 'mark');
    line.style.left = `${Math.min(100, Math.max(0, mark * 100))}%`;
    track.append(line);
  }
  return track;
}

// Amounts of one thing, longest first, each with its number at the end of its bar.
function memBars(card, rows) {
  const list = el('div', 'mem-bars');
  const shown = rows.filter((row) => row.n > 0).sort((a, b) => b.n - a.n);
  if (!shown.length) { card.append(el('p', 'note', t('NOTHING YET'))); return; }
  const top = Math.max(...shown.map((row) => row.n));
  const total = shown.reduce((sum, row) => sum + row.n, 0);
  for (const row of shown) {
    const line = el('div', 'mem-bar');
    const name = el('span', 'name');
    if (row.swatch) { const key = el('i', 'swatch'); key.style.background = row.swatch; name.append(key); }
    name.append(row.label);
    const track = el('span', 'track');
    const fill = el('i');
    fill.style.width = `${(row.n / top) * 100}%`;
    track.append(fill);
    line.append(name, track, el('span', 'value', `${memFmt(row.n)} · ${memPct(row.n / total)}`));
    if (row.title) line.title = row.title;
    list.append(line);
  }
  card.append(list);
}

function memTile(parent, { label, value, sub = null, title = null, spark = null, meter = null }) {
  const tile = el('div', 'mem-tile');
  tile.append(el('span', 'label', label), el('strong', 'value', value));
  if (sub) tile.append(el('span', 'sub', sub));
  if (spark) tile.append(memColumns(spark, 'mem-cols spark'));
  if (meter !== null) tile.append(memMeter(meter));
  if (title) tile.title = title;
  parent.append(tile);
  return tile;
}

// This week, and which way it went against the one before. An arrow and a number, never a
// percentage: a rise from two to four is not «+100%» in any sense worth reading.
function memWeek(week) {
  if (!week) return null;
  const turn = week.delta > 0 ? `▲ ${memFmt(week.delta)}` : week.delta < 0 ? `▼ ${memFmt(-week.delta)}` : '=';
  return `${t('{n} THIS WEEK', { n: memFmt(week.last) })} · ${turn}`;
}
const memWeekTitle = (week) => (week ? t('{last} in the last 7 days, {before} in the 7 before', { last: memFmt(week.last), before: memFmt(week.before) }) : null);

// Three series of one window, stacked so their days line up: each strip has its own height
// because an exchange and a recall are not the same unit, and one axis for the three would lie
// about one of them. One crosshair finds the day in all three at once.
function memActivity(card, dash) {
  const rows = [['entries', t('EXCHANGES')], ['memories', t('NEW MEMORIES')], ['recalls', t('TURNS THAT RECALLED')]];
  const n = dash.days.length;
  const chart = el('div', 'mem-activity');
  chart.tabIndex = 0;
  chart.setAttribute('role', 'img');
  const total = (id) => dash.series[id].reduce((sum, v) => sum + v, 0);
  chart.setAttribute('aria-label', t('{entries} exchanges, {memories} new memories and {recalls} turns that recalled in the last {n} days', { entries: total('entries'), memories: total('memories'), recalls: total('recalls'), n }));
  for (const [id, label] of rows) {
    const strip = el('div', 'mem-strip');
    const head = el('div', 'mem-strip-head');
    head.append(el('b', null, label), el('span', null, t('PEAK {n}', { n: memFmt(Math.max(0, ...dash.series[id])) })));
    strip.append(head, memColumns(dash.series[id], 'mem-cols big'));
    chart.append(strip);
  }
  const axis = el('div', 'mem-axis');
  axis.append(el('span', null, memDay(dash.days[0])), el('span', null, memDay(dash.days[Math.floor(n / 2)])), el('span', null, t('TODAY')));
  chart.append(axis);
  const cross = el('div', 'mem-cross');
  const tip = el('div', 'mem-tip');
  cross.hidden = true; tip.hidden = true;
  chart.append(cross, tip);
  let at = -1;
  const show = (i) => {
    at = i;
    for (const cols of chart.querySelectorAll('.mem-cols')) for (const [j, col] of [...cols.children].entries()) col.classList.toggle('on', j === i);
    if (i < 0) { cross.hidden = true; tip.hidden = true; return; }
    const col = chart.querySelector('.mem-cols').children[i];
    const left = col.offsetLeft + col.offsetWidth / 2;
    cross.style.left = `${left}px`;
    cross.hidden = false;
    tip.replaceChildren(el('b', 'when', i === n - 1 ? t('TODAY') : memDay(dash.days[i])));
    for (const [id, label] of rows) {
      const line = el('div');
      line.append(el('strong', null, memFmt(dash.series[id][i])), el('span', null, label));
      tip.append(line);
    }
    tip.hidden = false;
    tip.style.left = left > chart.clientWidth / 2 ? `${left - tip.offsetWidth - 14}px` : `${left + 14}px`;
  };
  chart.addEventListener('pointermove', (event) => {
    const box = chart.querySelector('.mem-cols').getBoundingClientRect();
    if (!box.width) return;
    const i = Math.floor(((event.clientX - box.left) / box.width) * n);
    show(i < 0 || i >= n ? -1 : i);
  });
  chart.addEventListener('pointerleave', () => show(-1));
  chart.addEventListener('focus', () => show(n - 1));
  chart.addEventListener('blur', () => show(-1));
  chart.addEventListener('keydown', (event) => {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    show(Math.min(n - 1, Math.max(0, (at < 0 ? n - 1 : at) + (event.key === 'ArrowLeft' ? -1 : 1))));
  });
  card.append(chart);

  // The same numbers without pointing at anything: every value the crosshair shows is here too.
  const table = cardFold(card, t('BY DAY · TABLE'), { key: 'madre.memory.table' });
  const lived = dash.days.map((day, i) => [day, ...rows.map(([id]) => dash.series[id][i])]).filter(([, ...values]) => values.some(Boolean)).reverse();
  if (!lived.length) { table.append(el('p', 'note', t('NOTHING HAPPENED IN THESE DAYS.'))); return; }
  const grid = el('table', 'mem-table');
  const headRow = el('tr');
  for (const word of [t('DAY'), ...rows.map(([, label]) => label)]) headRow.append(el('th', null, word));
  grid.append(headRow);
  for (const [day, ...values] of lived) {
    const tr = el('tr');
    tr.append(el('td', null, memDay(day)));
    for (const value of values) tr.append(el('td', null, memFmt(value)));
    grid.append(tr);
  }
  table.append(grid);
}

// The one sentence about the figures, and the next thing to do about them.
function memVerdict(m, v) {
  const verdict = el('div', `mem-verdict stage-${m.stage.id}`);
  const says = el('p', 'says');
  says.append(el('b', null, v.headline ?? m.stage.label), ` ${v.says}`);
  const next = el('p', 'maturity-next');
  next.append(el('b', null, t('NEXT')), ` ${v.next.text}`);
  if (v.next.where) next.append(el('span', 'where', ` → ${v.next.where}`));
  verdict.append(says, next);
  return verdict;
}

// What the archive is made of, one meter per signal, the weakest marked.
function memSignals(card, m) {
  for (const signal of m.signals) {
    const row = el('div', `mem-signal${signal.id === m.weakest ? ' weakest' : ''}`);
    const top = el('div', 'top');
    top.append(el('b', null, signal.label), el('span', null, memPct(signal.value)));
    row.append(top, memMeter(signal.value), el('span', 'detail', signal.detail));
    row.title = signal.next;
    card.append(row);
  }
}

// The archive at a glance, then the analysis behind it. The glance is four figures and how ripe
// the archive is; the analysis — activity, what it is made of, the three tests — waits folded.
async function drawMemoryDashboard(glance, analysis, stamp) {
  if (glance.childElementCount) glance.classList.add('loading');
  else glance.replaceChildren(el('p', 'sx-hint', t('Reading…')));
  let read; let dash;
  try {
    [read, dash] = await Promise.all([
      fetch('/api/maturity').then((response) => response.json()),
      fetch('/api/memory/dashboard').then((response) => response.json()).then((payload) => payload?.dashboard ?? null),
    ]);
  } catch { glance.classList.remove('loading'); glance.replaceChildren(el('p', 'sx-hint', t('The memory could not be read.'))); return; }
  glance.classList.remove('loading');
  glance.replaceChildren();
  analysis.replaceChildren();
  stamp.textContent = t('Read at {time}', { time: formatTime(new Date().toISOString()) });
  const m = read?.maturity;
  const v = read?.verdict;
  if (!dash || !m || !v) { glance.append(el('p', 'sx-hint', t('Nothing yet: the project has no memories saved.'))); return; }

  const stats = el('div', 'sx-stats');
  const stat = (label, value, sub, spark = null, title = null) => {
    const tile = el('div', 'sx-stat');
    tile.append(el('span', 'k', label), el('strong', null, value));
    if (sub) tile.append(el('span', 'sub', sub));
    if (spark) tile.append(memColumns(spark, 'sx-spark'));
    if (title) tile.title = title;
    stats.append(tile);
  };
  const week = (w) => (w ? `${t('{n} this week', { n: memFmt(w.last) })} · ${w.delta > 0 ? `▲ ${memFmt(w.delta)}` : w.delta < 0 ? `▼ ${memFmt(-w.delta)}` : '='}` : null);
  stat(t('Exchanges'), memFmt(dash.totals.entries), week(dash.weeks.entries), dash.series.entries.slice(-14), memWeekTitle(dash.weeks.entries));
  stat(t('Memories'), memFmt(dash.totals.memories), week(dash.weeks.memories), dash.series.memories.slice(-14), memWeekTitle(dash.weeks.memories));
  stat(t('Answers that used memories'), memFmt(dash.totals.turns), week(dash.weeks.recalls), dash.series.recalls.slice(-14), memWeekTitle(dash.weeks.recalls));
  stat(t('Not noted yet'), memFmt(dash.totals.pending), dash.totals.pending ? t('Exchanges not turned into notes yet.') : t('All caught up.'));
  glance.append(stats);

  // How ripe it is, in one line and one bar, and the next thing that would help it.
  const ripe = el('div', `sx-ripe stage-${m.stage.id}`);
  const top = el('div', 'top');
  // The server says these in the console's capitals; here they are a sentence like the rest.
  const said = (text) => { const words = String(text ?? ''); return words.charAt(0).toUpperCase() + (words === words.toUpperCase() ? words.slice(1).toLowerCase() : words.slice(1)); };
  top.append(el('b', null, t('Memory progress')), el('span', 'stage', said(v.headline ?? m.stage.label)), el('strong', null, memPct(m.score)));
  ripe.append(top, memMeter(m.score), el('p', null, said(v.says)));
  if (v.next?.text) {
    const next = el('p', 'next');
    next.append(el('b', null, t('Next')), ` ${said(v.next.text)}`);
    if (v.next.where) next.append(el('span', 'where', ` → ${said(v.next.where)}`));
    ripe.append(next);
  }
  glance.append(ripe);

  const grid = el('div', 'mem-grid');
  memActivity(memCard(grid, t('Activity · last {n} days', { n: dash.days.length }), 'span-12'), dash);
  memSignals(memCard(grid, t('What the memory holds'), 'span-12'), m);
  memBars(memCard(grid, t('By kind'), 'span-4'), Object.entries(dash.kinds).map(([kind, n]) => ({ label: kindWord(kind), n, swatch: `var(--mem-${kind}, var(--ph))` })));
  memBars(memCard(grid, t('By note-taker'), 'span-4'), Object.entries(dash.agents).map(([agent, n]) => ({ label: `@${agent}`, n })));
  memBars(memCard(grid, t('By status'), 'span-4'), Object.entries(dash.zones).map(([zone, n]) => ({ label: zoneWord(zone), n, title: ZONE_NOTE[zone] ?? null })));
  const recall = memCard(grid, t('Memories used and search by meaning'), 'span-12');
  const carried = dash.via.search + dash.via.cascade;
  if (carried) {
    const split = el('div', 'mem-split');
    split.title = t('How used memories arrived: found by search, or brought along by a related one.');
    for (const [id, n] of [['search', dash.via.search], ['cascade', dash.via.cascade]]) { const part = el('i', id); part.style.flexGrow = String(n); split.append(part); }
    recall.append(split);
    const legend = el('div', 'mem-legend');
    for (const [id, label, n] of [['search', t('Search'), dash.via.search], ['cascade', t('Related memories'), dash.via.cascade]]) {
      const key = el('span', `k ${id}`);
      key.append(el('i'), `${label} `, el('b', null, `${memFmt(n)} · ${memPct(n / carried)}`));
      legend.append(key);
    }
    recall.append(legend);
  } else recall.append(el('p', 'note', t('Nothing yet.')));
  if (dash.vectors) {
    for (const [label, have, of] of [[t('Memories searchable by meaning'), dash.vectors.memories, dash.totals.memories], [t('Exchanges searchable by meaning'), dash.vectors.entries, dash.totals.entries]]) {
      const row = el('div', 'mem-signal');
      const head = el('div', 'top');
      head.append(el('b', null, label), el('span', null, `${memFmt(have)} / ${memFmt(of)}`));
      row.append(head, memMeter(of ? have / of : 0));
      recall.append(row);
    }
    recall.append(el('span', 'detail', String(dash.vectors.model)));
  } else recall.append(el('p', 'note', t('Search by meaning is off: memories are found by exact words only.')));
  memCard(grid, t('Memory checkup'), 'span-12').append(examsBlock(read.exams, { pass: dash.pass }));
  analysis.append(grid);
}

/* ---------- the three tests ---------- */

const EXAM_NAMES = {
  coverage: t('Does the memory have the answers?'),
  consistency: t('Does the memory contradict itself?'),
  match: t('Does the local AI answer like the agents?'),
};
const EXAM_ABOUT = {
  coverage: t('Real questions from this project, recall run at the moment each one was asked, scored against the reply that was actually given. It asks whether the answer was already in the archive, not whether it was right.'),
  consistency: t('Contradictions the memory reviewer has not settled yet, memories taken out of use, and whether doubtful memories are being filed more often lately than they used to be.'),
  match: t('Real questions answered here by one of your agents, asked again of the Local AI with this project\'s memory behind it, and compared against the answer given at the time. It takes minutes and spends nothing.'),
};

function examRow(id, state, run, pass = null) {
  const last = state.last?.[id] ?? null;
  const can = state.can?.[id] ?? { ok: false };
  const row = el('div', `exam exam-${id}${last?.ran ? (last.passed ? ' passed' : ' failed') : ''}`);
  const head = el('div', 'exam-head');
  head.append(el('b', null, EXAM_NAMES[id]));
  const mark = el('span', 'verdict', last?.ran ? (last.passed ? t('PASSES') : t('NOT YET')) : t('NOT RUN'));
  head.append(mark);
  row.append(head);
  row.append(el('p', 'note about', EXAM_ABOUT[id]));
  if (last?.says) {
    const said = el('p', 'said', last.says);
    const when = last.at ? ` · ${new Date(last.at).toLocaleString()}` : '';
    const how = last.ran && last.rate !== undefined ? `${Math.round(last.rate * 100)}% · ${t('{n} CASES', { n: last.n })}${last.method ? t(' · BY {method}', { method: last.method.toUpperCase() }) : ''}${last.bar ? t(' · BAR {bar}', { bar: last.bar }) : ''}${when}` : when.replace(' · ', '');
    row.append(said);
    // The rate against the line it has to reach: the bar fills to what it scored, the mark
    // stands where it passes.
    if (last.ran && last.rate !== undefined && pass?.[id] !== undefined) {
      const bullet = el('div', 'exam-bullet');
      bullet.append(memMeter(last.rate, { mark: pass[id] }), el('span', null, `${memPct(last.rate)} · ${t('PASSES AT {n}', { n: memPct(pass[id]) })}`));
      row.append(bullet);
    }
    if (how) row.append(el('p', 'note', how.toUpperCase()));
  }
  const actions = el('div', 'actions');
  const button = el('button', can.ok ? 'primary' : null, state.running === id ? t('RUNNING…') : last?.ran ? t('RUN AGAIN') : t('RUN'));
  button.type = 'button';
  button.disabled = !can.ok || Boolean(state.running);
  if (!can.ok && can.why) button.title = can.why;
  button.addEventListener('click', () => run(id));
  actions.append(button);
  if (!can.ok && can.why) actions.append(el('span', 'note', can.why.toUpperCase()));
  if (state.running === id && state.progress?.total) actions.append(el('span', 'note', t('{done} OF {total}', { done: state.progress.done, total: state.progress.total })));
  row.append(actions);
  return row;
}

function examsBlock(known = null, { pass = null } = {}) {
  const box = el('div', 'full exams');
  const draw = (state) => {
    box.replaceChildren();
    box.append(el('p', 'note', t('NOTHING HERE SPENDS A PROVIDER TURN. THE FIRST TWO ARE FREE; THE THIRD TAKES MINUTES AND STOPS WHEN YOU SAY.')));
    for (const id of ['coverage', 'consistency', 'match']) box.append(examRow(id, state, run, pass));
    if (state.running === 'match') {
      const stop = el('button', null, t('STOP'));
      stop.type = 'button';
      stop.addEventListener('click', async () => { stop.disabled = true; await fetch('/api/maturity/exam', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ stop: true }) }).catch(() => null); });
      box.append(stop);
      // While the slow one works, the panel follows it.
      clearTimeout(examsBlock.timer);
      examsBlock.timer = setTimeout(() => { void load(); }, 2000);
    }
  };
  const load = async () => {
    try { draw(await fetch('/api/maturity/exams').then((response) => response.json())); }
    catch { box.replaceChildren(el('p', 'note', t('THE TESTS ARE UNAVAILABLE'))); }
  };
  const run = async (id) => {
    try {
      const result = await fetch('/api/maturity/exam', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ which: id }) }).then((response) => response.json());
      if (result.error) toast(`${t('Diagnostics › ')}${result.error}`);
      else if (result.started) toast(t('Diagnostics › the local model is answering real questions from this project. It takes a few minutes and spends nothing.'));
      if (result.exams) draw(result.exams); else await load();
    } catch (error) { toast(t('The test could not run: {error}', { error: error.message })); }
  };
  if (known) draw(known); else void load();
  return box;
}

// A section of MU/TH/UR that folds. The header stays what it was, so nothing about the look
// changes; what it opens onto goes into the body. Whether it was left open is remembered on this
// browser, because a panel that forgets is a panel you fight with every time you open it.
const FOLD_KEY = 'madre.folds';
function foldState() {
  try { return JSON.parse(localStorage.getItem(FOLD_KEY) ?? '{}') ?? {}; } catch { return {}; }
}
function rememberFold(key, open) {
  try { localStorage.setItem(FOLD_KEY, JSON.stringify({ ...foldState(), [key]: open })); } catch { /* a private window remembers nothing, and that is fine */ }
}
// 8-bit. Each icon is an 8×8 bitmap written as eight rows of text — `#` is a lit pixel — and
// drawn as unit squares on an 8×8 viewBox with crisp edges, so it scales without ever softening
// into a curve. Written this way because a pixel drawing should be readable as a pixel drawing in
// the source too: you can see the icon in the string.
const PIXEL_ICONS = {
  unfold: ['........', '#......#', '##....##', '.######.', '..####..', '...##...', '........', '........'],
  fold:   ['........', '........', '...##...', '..####..', '.######.', '##....##', '#......#', '........'],
  release: ['...##...', '..####..', '.######.', '##.##.##', '...##...', '...##...', '...##...', '...##...'],
  alert:   ['...##...', '..#..#..', '..#..#..', '.#.##.#.', '.#.##.#.', '#......#', '#..##..#', '########'],
  fault:   ['##....##', '###..###', '.######.', '..####..', '..####..', '.######.', '###..###', '##....##'],
  list:    ['#..#####', '........', '#..#####', '........', '#..#####', '........', '#..#####', '........'],
  link:    ['........', '......#.', '########', '......#.', '........', '.#......', '########', '.#......'],
  gear:    ['..#..#..', '..#..#..', '.######.', '###..###', '###..###', '.######.', '..#..#..', '..#..#..'],
  chip:    ['..#..#..', '########', '#......#', '#.####.#', '#.####.#', '#......#', '########', '..#..#..'],
  lock:    ['..####..', '.#....#.', '.#....#.', '########', '###..###', '###..###', '########', '........'],
  free:    ['..####..', '.#....#.', '#....#.#', '#...#..#', '#..#...#', '#.#....#', '.#....#.', '..####..'],
  home:    ['...##...', '..####..', '.######.', '########', '##....##', '##.##.##', '##.##.##', '##.##.##'],
  cut:     ['#......#', '.#....#.', '..#..#..', '...##...', '..#..#..', '.#....#.', '##....##', '##....##'],
  bars:    ['........', '######..', '........', '####....', '........', '########', '........', '###.....'],
  grid:    ['########', '##.##.##', '########', '##.##.##', '########', '##.##.##', '########', '........'],
  orbit:   ['..####..', '.#....#.', '#..##..#', '#.####.#', '#.####.#', '#..##..#', '.#....#.', '..####..'],
  star:    ['...#....', '...#....', '..###...', '#######.', '..###...', '...#....', '...#....', '........'],
  mail:    ['........', '########', '##....##', '#.#..#.#', '#..##..#', '#......#', '########', '........'],
  stop:    ['........', '.######.', '.######.', '.######.', '.######.', '.######.', '.######.', '........'],
  ufo:     ['........', '...##...', '..####..', '.######.', '########', '.#.##.#.', '..#..#..', '.#....#.'],
  branch:  ['.#......', '.#...#..', '.#..###.', '.#...#..', '.#..#...', '.###....', '.#......', '.#......'],
  check:   ['........', '.......#', '......##', '#....##.', '##..##..', '.####...', '..##....', '........'],
  search:  ['..###...', '.#...#..', '#.....#.', '#.....#.', '.#...#..', '..####..', '......#.', '.......#'],
  db:      ['.######.', '#......#', '.######.', '#......#', '.######.', '#......#', '.######.', '........'],
  bell:    ['...##...', '..####..', '.######.', '.######.', '.######.', '########', '........', '...##...'],
};

// One run of lit pixels becomes one horizontal bar of the path, so a full row is a single
// rectangle and not eight. Written out as markup like every other icon in this file, which also
// keeps it off `createElementNS` — the replay harness has a document without it.
function pixelPath(name) {
  const rows = PIXEL_ICONS[name] ?? PIXEL_ICONS.list;
  let d = '';
  for (const [y, row] of rows.entries()) {
    let run = 0;
    for (let x = 0; x <= 8; x += 1) {
      if (row[x] === '#') { run += 1; continue; }
      if (run) d += `M${x - run} ${y}h${run}v1h-${run}z`;
      run = 0;
    }
  }
  return d;
}

// The icon carries no box: a badge around it was a second frame saying what the drawing says.
function pixelIcon(name, className = 'pixel-icon') {
  const holder = el('span', className);
  holder.innerHTML = `<svg viewBox="0 0 8 8" aria-hidden="true"><path d="${pixelPath(name)}" fill="currentColor"/></svg>`;
  return holder;
}


function connectionCard(agent) {
  const card = paint(el('section', 'sx-block sx-agent'), agent.id);
  card.id = `conn-${agent.id}`;
  const session = settingsUI.data.sessions?.[agent.id];
  const busy = settingsUI.data.loggingIn === agent.id;
  // How the connection is, said in a chip of its own tone: green with a session, red without one,
  // amber while it signs in, grey when the CLI is not here.
  const lamp = busy ? 'busy' : !agent.detected ? 'absent' : session?.state === 'signed-in' ? 'on' : session?.state === 'signed-out' ? 'off' : 'unknown';
  const said = busy ? t('Signing in…') : !agent.detected ? t('Not installed') : session ? ({ 'signed-in': t('Signed in'), 'signed-out': t('Signed out') }[session.state] ?? t('Unknown')) : t('Unknown');
  // Folded by default (2026-10-13): four agents with six settings each made a page to scroll
  // through. The line says who it is and whether it has a session; a click opens the rest. One
  // that is signing in, or has no session, opens by itself: that is where the person is needed.
  const open = settingsUI.agentsOpen.has(agent.id) || busy || (agent.detected && session?.state === 'signed-out');
  card.classList.toggle('open', open);
  const head = el('header', 'sx-head');
  const toggle = el('button', 'sx-agent-toggle');
  toggle.type = 'button';
  toggle.setAttribute('aria-expanded', String(open));
  toggle.append(avatar(agent.id, { size: 32, status: agent.ready ? 'ready' : agent.detected ? 'detected' : 'offline' }));
  const words = el('div', 'sx-words');
  words.append(el('h3', null, agent.label), el('p', null, vendorWord(agent.id)));
  const chip = sxChip(said, lamp);
  if (lamp !== 'absent') chip.classList.add('session-lamp', lamp === 'on' ? 'ok' : lamp === 'off' ? 'bad' : 'wait');
  toggle.append(words, chip, el('span', 'sx-chevron'));
  toggle.addEventListener('click', () => {
    const now = !card.classList.contains('open');
    card.classList.toggle('open', now);
    toggle.setAttribute('aria-expanded', String(now));
    if (now) settingsUI.agentsOpen.add(agent.id); else settingsUI.agentsOpen.delete(agent.id);
  });
  head.append(toggle);
  card.append(head);
  // Where it lives, quietly: what is literal is in mono, what is said is not.
  const meta = el('div', 'sx-meta');
  const where = el('code', null, agent.detected ? `${agent.version ?? t('version unknown')} · ${agent.path}` : (agent.login?.install ?? []).join(' · '));
  where.title = where.textContent;
  meta.append(where);
  const facts = [sessionDetail(session) ? t('Session {detail}', { detail: sessionDetail(session) }) : null, agent.account ? `${agent.paid === false ? `${t('Free plan')} · ` : ''}${agent.account}` : null].filter(Boolean);
  if (facts.length) meta.append(el('span', null, facts.join(' · ')));
  card.append(meta);
  const body = el('div', 'sx-agent-body');
  card.append(body);
  card.rows = el('div', 'sx-rows');
  body.append(card.rows);
  // Settings in pairs: what it can do, then where its messages start and stop.
  const abilities = el('div', 'sx-duo');
  const modes = el('div', 'sx-duo');
  card.rows.append(abilities, modes);

  const agentScopes = settingsUI.data.settings.capabilities?.[agent.id]?.scopes ?? {};
  // Two abilities per agent: images and web. Writing is not an ability, it is the ceiling below.
  for (const [key, labelText, onWhy] of [['imageGen', t('Generate images'), t('On for CREATE.')], ['web', t('Web access'), t('On in every turn.')]]) {
    const scope = agentScopes[key] ?? { capable: false, enabled: false, wired: false };
    const usable = scope.capable && scope.wired;
    const why = (on) => (!scope.capable ? t('This agent can\'t do this.') : !scope.wired ? t('Not available yet.') : on ? onWhy : t('Off.'));
    const toggle = sxSwitch(scope.enabled, async (on, box) => {
      box.disabled = true;
      try {
        const response = await fetch('/api/settings', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ scopes: { [agent.id]: { [key]: on } } }) });
        const result = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(result.error ?? `HTTP ${response.status}`);
        if (result.settings?.capabilities) { state.capabilities = result.settings.capabilities; settingsUI.data.settings.capabilities = result.settings.capabilities; renderCreateScopes(); }
        hint.textContent = why(on);
        toast(`${t('Diagnostics › ')}@${agent.id} ${labelText.toLowerCase()} ${on ? t('on') : t('off')}. ${key === 'web' ? t('Applies to its next turn.') : t('Applies to its next CREATE.')}`);
      } catch (error) {
        box.checked = !on;
        toast(t('That permission was not saved: {error}', { error: error.message }));
      } finally { box.disabled = false; }
    }, { disabled: !usable, label: labelText });
    const row = sxRow(abilities, labelText, why(scope.enabled), toggle, { off: !usable });
    const hint = row.querySelector('.sx-hint');
    if (!scope.capable) {
      const assist = el('button', 'sx-link', t('Ask Diagnostics how'));
      assist.type = 'button';
      assist.title = t('How could @{agent} get "{what}"?', { agent: agent.id, what: labelText.toLowerCase() });
      assist.addEventListener('click', () => askMotherAbout(`scope-${agent.id}-${key}`, labelText));
      hint.after(assist);
    }
  }
  // The ceiling lives with every other agent's in PERMISSIONS: here it is said, and one key goes there.
  const currentCap = agentScopes.maxMode ?? 1;
  const capRow = sxRow(modes, t('Max mode'), `#${currentCap} ${MODES[currentCap].label}`, sxButton(t('Change it'), () => openSettingsOn('permissions', { part: 'permissions' })));
  capRow.querySelector('.sx-hint').title = MODES[currentCap].hint;
  // The start: where a message to this agent begins. #2 means every turn may create files without arming CREATE.
  const currentStart = agentScopes.defaultMode ?? 1;
  sxRow(modes, t('Starting mode'), currentStart === 2 ? t('Every turn may create files, plan steps too.') : t('Read-only until you unlock CREATE.'), sxSeg([1, 2].map((n) => ({
    value: n, text: `#${n}`, className: `o${n}`, disabled: n > currentCap,
    title: n === 2 ? t('Every message to this agent starts in #2 CREATE: it may add new files, but existing files stay untouched. Plan steps sent to it too.') : t('Messages start in #1 CHAT ONLY; turn on #2 CREATE when you want files.'),
  })), currentStart, async (n, seg) => {
    try {
      await saveSettingNow({ scopes: { [agent.id]: { defaultMode: n } } }, n === 2 ? t('@{agent} starts in #2 CREATE: every turn may add files to the project.', { agent: agent.id }) : t('@{agent} starts in #1 CHAT ONLY; turn on #2 CREATE when you want files.', { agent: agent.id }));
      await loadSettings();
    } catch (error) { toast(t('The starting mode was not saved: {error}', { error: error.message })); await loadSettings(); }
  }, { label: t('Starting mode') }));
  const seconds = Math.round((settingsUI.data.settings.timeouts[agent.id] ?? 180000) / 1000);
  sxRow(card, t('Time limit'), t('How long the project waits for its answer.'), sxNumber(seconds, 's', {
    min: 10, step: 10, label: t('Time limit'),
    wire: { toPatch: (value) => ({ timeouts: { [agent.id]: value * 1000 } }), describe: (value) => t('@{agent} timeout saved: {n}s.', { agent: agent.id, n: value }) },
  }));

  // What can be done about the connection itself.
  const acts = el('div', 'sx-actions');
  const recheck = sxButton(t('Check again'), async () => {
    recheck.disabled = true;
    const result = await fetch('/api/agents/probe', { method: 'POST' }).then((response) => response.json()).catch(() => null);
    if (result?.sessions) { settingsUI.data.sessions = result.sessions; state.sessions = result.sessions; }
    if (result?.agents) { settingsUI.data.agents = result.agents; for (const one of result.agents) state.agents.set(one.id, { ...(state.agents.get(one.id) ?? {}), ...one }); renderAgents(); renderPicker(); renderOnboarding(); }
    if (result?.sessions) renderSettings();
    recheck.disabled = false;
  });
  if (!agent.detected && agent.install?.command) {
    const install = sxButton(t('Install'), async () => {
      install.disabled = true;
      state.loginLogs.set(agent.id, []);
      const response = await fetch(`/api/agents/${agent.id}/install`, { method: 'POST' });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) { toast(result.error ?? t('The install could not start.')); install.disabled = false; }
    }, { tone: 'primary', title: t('{command} · runs here, streamed to the project', { command: agent.install.display }) });
    install.disabled = Boolean(settingsUI.data.loggingIn);
    acts.append(install);
  }
  if (agent.detected && agent.login?.headless) {
    const signedIn = session?.state === 'signed-in';
    // One button per account the CLI can sign in with. Which one is paying is the human's to say.
    for (const door of loginDoors(agent, signedIn)) {
      const login = sxButton(door.label, async () => {
        if (door.choose) { choosingAccount.add(agent.id); renderSettings(); return; }
        choosingAccount.delete(agent.id);
        login.disabled = true;
        try { await startLogin(agent.id, door.id); settingsUI.data.loggingIn = agent.id; renderSettings(); }
        catch (error) { toast(error.message || t('The sign-in could not start.')); login.disabled = false; }
      }, { tone: (signedIn && !choosingAccount.has(agent.id)) || agent.key?.first ? null : 'primary', title: t(door.note || agent.login.note) });
      login.disabled = Boolean(settingsUI.data.loggingIn);
      acts.append(login);
    }
  }
  acts.append(recheck);
  const slot = el('div', 'sx-slot');
  // OpenCode's keys are its providers', added in the block under its settings, one row for all.
  if (agent.detected && agent.key && agent.id !== 'opencode') slot.append(keyForm(agent, { onDone: () => { void loadSettings(); renderOnboarding(); } }));
  // Gemini's key is its way in (agent.key.first): the field before the Google door.
  if (agent.key?.first && slot.firstChild) { const first = el('div', 'sx-slot'); first.append(slot.firstChild); body.append(first); }
  body.append(acts);
  if (agent.detected && agent.login?.headless) slot.append(loginAskSlot(agent.id));
  // The same, typed in a terminal, folded for whoever prefers it. Signed in, OpenCode's providers
  // are added in its block below; its terminal is for a first sign-in.
  const way = !agent.detected ? installTerminalWay(agent) : agent.id === 'opencode' && session?.state === 'signed-in' ? null : signInTerminalWay(agent);
  if (way) slot.append(way);
  const log = state.loginLogs.get(agent.id) ?? [];
  if (log.length || busy) {
    const box = el('div', 'login-log');
    box.id = `login-log-${agent.id}`;
    for (const entry of log) box.append(loginLine(entry));
    slot.append(box);
    requestAnimationFrame(() => { box.scrollTop = box.scrollHeight; });
  }
  if (slot.children.length) body.append(slot);
  // OpenCode answers through other providers: their keys and the chooser live in its own card.
  if (agent.id === 'opencode' && agent.detected) drawOpenCodeSettings(body, settingsUI.data.settings ?? {});
  return card;
}

// MEMORY, emancipated. It used to be a fold inside CONNECTIONS, which is where you go to wire an
// agent up — a different errand entirely. What the archive holds, who distils it and how well it
// is answering is a subject of its own, so it gets its own button in the MU/TH/UR bar, beside
// NOSTROMO, and the whole panel instead of a fold inside somebody else's.
function renderMemoryPanel(data) {
  const target = state.settingsTargets.memory;
  if (target?.isConnected) { target.replaceChildren(); drawMemory(target, data); }
}
// D-S17, also in AJUSTES › What it remembers: the notes other projects delivered here, waiting
// for you, and what became of the last ones. The same rows as the card in the conversation.
const deliveries = { pending: 0 };
async function readDeliveries() {
  try { return (await fetch('/api/enlace/inbox').then((response) => response.json())).notes ?? []; } catch { return null; }
}
function drawDelivered(host) {
  const block = sxBlock(host, t('Delivered notes'), t('Notes other projects handed to this one. Each enters the memory only if it is accepted.'));
  block.id = 'sx-delivered';
  const fill = async () => {
    const notes = await readDeliveries();
    if (!block.isConnected) return;
    block.rows.replaceChildren();
    if (!notes) { sxRow(block, t('Could not read them.'), null); return; }
    const waiting = notes.filter((note) => note.status === 'pending');
    if (!waiting.length) sxRow(block, t('Nothing waiting'), notes.length ? t('{n} decided before.', { n: notes.length }) : t('No project has delivered notes here yet.'));
    for (const note of waiting) {
      const decide = (accept) => async () => {
        try {
          const response = await fetch('/api/enlace/inbox/decide', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ id: note.id, accept }) });
          const result = await response.json().catch(() => ({}));
          if (!response.ok) throw new Error(result.error ?? `HTTP ${response.status}`);
        } catch (error) { toast(`${t('Diagnostics › ')}${error.message}`); }
        void fill();
        void refreshDeliveries();
      };
      const actions = el('div', 'sx-chips');
      actions.append(sxButton(t('Accept'), decide(true), { tone: 'primary' }), sxButton(t('Decline'), decide(false)));
      sxRow(block, `${kindWord(note.kind)} · ${note.text}`, [t('Delivered by {room}{agent}', { room: note.name, agent: note.agent ? ` · @${note.agent}` : '' }), note.why ? t('Why: {why}', { why: note.why }) : null].filter(Boolean).join(' · '), actions, { stack: true });
    }
  };
  void fill();
}
// The bar says how many wait, and goes to them.
async function refreshDeliveries() {
  const notes = await readDeliveries();
  if (!notes) return;
  deliveries.pending = notes.filter((note) => note.status === 'pending').length;
  let pill = document.querySelector('#inbox-pill');
  if (!pill) {
    const anchor = document.querySelector('#stop-all');
    if (!anchor) return;
    // Shaped like the handoff pill beside it: an icon and its words, never squeezed to a dot.
    pill = el('button', 'stop-all handoff-pill inbox-pill');
    pill.id = 'inbox-pill';
    pill.type = 'button';
    pill.innerHTML = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3.2 11.2 5.4 4.6c.2-.6.8-1 1.4-1h6.4c.6 0 1.2.4 1.4 1l2.2 6.6v3.6c0 .9-.7 1.6-1.6 1.6H4.8c-.9 0-1.6-.7-1.6-1.6z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M3.4 11.2h3.8l1 2h3.6l1-2h3.8" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg><span class="handoff-words"></span><span class="inbox-count"></span>'; // trusted: our own SVG string
    pill.addEventListener('click', () => openSettingsOn('memory', { anchor: 'sx-delivered' }));
    anchor.before(pill);
  }
  pill.hidden = state.device || !deliveries.pending;
  const said = deliveries.pending === 1 ? t('1 note to accept') : t('{n} notes to accept', { n: deliveries.pending });
  pill.querySelector('.handoff-words').textContent = said;
  // Its short form, for a bar too narrow for the words (barFit, bar-tight): the tray and the number.
  pill.querySelector('.inbox-count').textContent = String(deliveries.pending);
  pill.setAttribute('aria-label', said);
  pill.title = t('Notes other projects delivered here, waiting for you');
}
function drawMemory(host, data) {
  drawDelivered(host);
  const mem = data?.settings?.memory;
  if (!mem) { sxBlock(host, t('What it remembers'), t('This project has no memory yet.')); return; }
  const save = async (memoryPatch, describe) => { try { await saveSettingNow({ memory: memoryPatch }, describe); await loadSettings(); } catch (error) { toast(t('Memory setting was not saved: {error}', { error: error.message })); } };
  const select = (options, current, change, label) => {
    const node = el('select', 'sx-input');
    node.setAttribute('aria-label', label);
    for (const [value, text] of options) { const option = el('option', null, text); option.value = value; if (value === current) option.selected = true; node.append(option); }
    node.addEventListener('change', () => change(node.value, node));
    return node;
  };

  // It reads first and is configured second: the glance is what someone opens this to see.
  const aside = el('div', 'sx-aside');
  const stamp = el('span', 'sx-hint');
  aside.append(stamp);
  const glanceBlock = sxBlock(host, t('At a glance'), null, { aside, className: 'sx-glance' });
  const glance = el('div', 'sx-glance-body');
  glanceBlock.rows.append(glance);
  const more = el('details', 'sx-more');
  const summary = el('summary', null, t('Details and checkups'));
  const analysis = el('div', 'sx-analysis mem-dash');
  more.append(summary, analysis);
  glanceBlock.append(more);
  aside.append(sxButton(t('Refresh'), () => void drawMemoryDashboard(glance, analysis, stamp)));
  void drawMemoryDashboard(glance, analysis, stamp);

  const keep = sxBlock(host, t('Who takes notes'), t('An agent rereads recent conversations and saves only what is worth remembering. The cheapest one goes first; local AI is free and private.'));
  sxRow(keep, t('Who takes notes first'), null, select([['auto', t('Automatic · the cheapest one')], ...mem.candidates.map((c) => [c.id, `@${c.id}${c.local ? ` · ${c.label}` : ''}`])], mem.archivist, (value) => save({ archivist: value }, value === 'auto' ? t('notes: the cheapest agent goes first.') : t('notes: @{agent} goes first.', { agent: value })), t('Who takes notes first')));
  const allowed = new Set(mem.archivists ?? mem.candidates.map((c) => c.id));
  const who = el('div', 'sx-chips');
  for (const candidate of mem.candidates) {
    const chip = el('button', 'sx-pick', `@${candidate.id}${candidate.local ? ` · ${t('local, free')}` : ''}`);
    chip.type = 'button';
    chip.setAttribute('aria-pressed', String(allowed.has(candidate.id)));
    chip.addEventListener('click', () => {
      if (allowed.has(candidate.id)) allowed.delete(candidate.id); else allowed.add(candidate.id);
      if (!allowed.size) { allowed.add(candidate.id); toast(t('Diagnostics › at least one agent has to take notes.')); return; }
      chip.setAttribute('aria-pressed', String(allowed.has(candidate.id)));
      void save({ archivists: allowed.size === mem.candidates.length ? [] : [...allowed] }, t('taking notes: {who}.', { who: [...allowed].map((id) => `@${id}`).join(', ') }));
    });
    who.append(chip);
  }
  sxRow(keep, t('Who may take notes'), t('Only the agents switched on here take notes.'), who, { stack: true });
  sxRow(keep, t('Every'), t('How many exchanges pass before it takes notes again.'), sxNumber(mem.every, t('exchanges'), { min: 1, label: t('Every'), wire: { toPatch: (value) => ({ memory: { every: value } }), describe: (value) => t('notes every {n} exchanges.', { n: value }) } }));
  sxRow(keep, t('Or after'), t('Or take notes after this many quiet minutes.'), sxNumber(mem.idleMinutes, t('min'), { min: 1, label: t('Or after'), wire: { toPatch: (value) => ({ memory: { idleMinutes: value } }), describe: (value) => t('or after {n} quiet minutes.', { n: value }) } }));

  const recall = sxBlock(host, t('Using memories'), t('How many memories each answer uses, and how they are found.'));
  sxRow(recall, t('Room for memories'), t('At most, how much of what an agent reads can be memories.'), sxNumber(Math.round(mem.recallShare * 100), '%', { min: 0, step: 5, label: t('Room for memories'), wire: { toPatch: (value) => ({ memory: { recallShare: Math.min(60, value) / 100 } }), describe: (value) => t("memories may take up to {n}% of what each agent reads.", { n: Math.min(60, value) }) } }));
  const cascade = sxSwitch(mem.cascade !== false, (on) => save({ cascade: on }, on ? t('related memories come along too.') : t('only memories that match come along.')), { label: t('Related memories') });
  sxRow(recall, t('Related memories'), t('Memories that are often used together are brought in together.'), cascade);
  const embedNow = mem.embedder ? mem.embedder : t('off');
  sxRow(recall, t('Search by meaning'), t('Finds memories by what they mean, not only by exact words. Now: {what}.', { what: embedNow }), select([
    ['auto', t('Automatic · Local AI if running, else Gemini')],
    ['ollama', `Ollama · ${t('local')}${mem.ollama.embedModel ? ` · ${mem.ollama.embedModel}` : ` · ${t('no model yet')}`}`],
    ['gemini', t('Gemini · needs your key')],
    ['off', t('Off · exact words only')],
  ], mem.embedProvider ?? data.config?.memory?.embedProvider ?? 'auto', (value, node) => save({ embedProvider: value }, t('search by meaning: {what}.', { what: node.options[node.selectedIndex].textContent.toLowerCase() })), t('Search by meaning')));
  if (mem.envWins) sxFoot(recall, t('Some of these values are fixed by how MADRE was started; those win next time it starts.'));

  // The dataset behind MADRE AI, and the recipe that trains on it, outside MADRE.
  const train = sxBlock(host, t('Train your own AI'), t('Advanced: export what the project learned, train a model on your computer, and @madre answers with it.'));
  const datasetHint = el('span', 'sx-hint', t('Reading…'));
  const exportButton = sxButton(t('Export'), async () => {
    exportButton.disabled = true;
    try { const payload = await fetch('/api/dataset', { method: 'POST' }).then((response) => response.json()); showDataset(payload); toast(t('Diagnostics › dataset exported: {n} pairs in {dir}', { n: payload.dataset.pairs, dir: payload.dir })); }
    catch (error) { toast(t('Dataset export failed: {error}', { error: error.message })); }
    finally { exportButton.disabled = false; }
  }, { title: t('Saves the training files in the project, with private data hidden') });
  const datasetRow = sxRow(train, t('Training data'), null, exportButton);
  datasetRow.querySelector('.sx-words').append(datasetHint);
  // What it is, then the recipe in order (2026-10-14): one command per step, for a Mac with an
  // Apple chip or — tried, not promised — Linux with an NVIDIA card through MLX's CUDA package.
  train.append(el('p', 'sx-hint sx-train-what', t('The training data are question-and-answer pairs taken from this project\'s conversations and notes, with private details hidden. With them a small model is adjusted on your computer, and @madre answers with it.')));
  const recipe = el('details', 'sx-more');
  recipe.append(el('summary', null, t('Step by step')));
  let platform = /Mac/i.test(navigator.platform ?? '') || !/Linux/i.test(navigator.userAgent ?? '') ? 'mac' : 'linux';
  // The size to train: the largest this computer trains and then runs, unless the human picks
  // another (to train it on a larger machine, say). Every size is offered; the note says what fits.
  let size = null;
  let measured = false;
  const steps = el('ol', 'sx-steps');
  const pickRow = el('div', 'sx-train-platform');
  const platformNote = el('p', 'sx-hint');
  const sizeRow = el('div', 'sx-train-platform');
  const sizeNote = el('p', 'sx-hint');
  recipe.append(pickRow, platformNote, sizeRow, sizeNote, steps);
  train.append(recipe);
  let lastPayload = null;
  const drawPlatform = () => {
    pickRow.replaceChildren(sxSeg([{ value: 'mac', text: t('Mac with Apple chip') }, { value: 'linux', text: t('Linux with NVIDIA') }], platform, (value) => { platform = value; showDataset(lastPayload); }, { label: t('Your computer') }));
    platformNote.textContent = platform === 'mac'
      ? t('Any Mac with an M chip. Its memory decides the size you can train, below.')
      : t('Experimental: MLX runs on Linux with an NVIDIA card (CUDA 12, compute capability 7.5 or newer, glibc 2.35, Python 3.10), but mlx-lm only promises Apple chips. Step 2 checks the card first.');
  };
  const drawSize = (fit) => {
    const models = fit?.models ?? [];
    if (!models.length) { sizeRow.replaceChildren(); sizeNote.textContent = ''; return null; }
    const chosen = models.find((model) => model.id === size) ?? models.find((model) => model.id === fit.recommended?.train?.id) ?? models[1] ?? models[0];
    sizeRow.replaceChildren(sxSeg(models.map((model) => ({ value: model.id, text: model.label.replace(/^Qwen2\.5\s*/, ''), title: model.train === 'yes' ? t('Trains on this computer') : t('Needs {gb} GB to train', { gb: model.trainGb }) })), chosen.id, (value) => { size = value; showDataset(lastPayload); }, { label: t('Model size') }));
    const here = hardwareLine(fit.hardware);
    sizeNote.textContent = chosen.train === 'yes'
      ? t('{model} trains on this computer ({here}). Needs about {disk} GB free on disk.', { model: chosen.label, here, disk: Math.ceil(chosen.params * 5.5) + 2 })
      : fit.accelerated
        ? t('{model} needs {gb} GB to train and this computer has {have} GB: train it on a larger one, or pick a smaller size.', { model: chosen.label, gb: chosen.trainGb, have: fit.usableGb })
        : t('This computer has no Apple chip or NVIDIA card to train with ({here}). The recipe is the one for a computer that has one.', { here });
    return chosen;
  };
  const showDataset = (payload) => {
    lastPayload = payload;
    const d = payload?.dataset;
    const exported = d ? t('Last export {when} · {train} to train · {valid} to check', { when: new Date(d.exportedAt).toLocaleString(), train: d.train, valid: d.valid }) : t('Not exported yet.');
    const trained = payload?.trained ? t('Trained model {model} in use.', { model: payload.trained }) : t('No trained model yet.');
    // D-S15: in Home, which projects the Coordinator learned from this time, and how.
    const sources = (d?.linked ?? []).map((one) => (one.source === 'missing'
      ? t('{room}: did not answer and nothing was kept', { room: one.name })
      : one.source === 'kept'
        ? t('{room}: {n} notes from the last time it answered', { room: one.name, n: one.notes })
        : t('{room}: {n} notes', { room: one.name, n: one.notes })));
    datasetHint.textContent = `${exported} ${trained}${sources.length ? ` ${t('Learned from your projects: {list}.', { list: sources.join(' · ') })}` : ''}`;
    const info = payload?.training;
    // The first reading sets the recipe for this computer: an NVIDIA card goes the Linux way.
    if (!measured && info?.fit?.hardware) { measured = true; if (info.fit.hardware.accelerator === 'nvidia') platform = 'linux'; else if (info.fit.hardware.accelerator === 'apple') platform = 'mac'; }
    drawPlatform();
    const chosen = drawSize(info?.fit);
    steps.replaceChildren();
    if (!info) { steps.append(el('li', 'sx-hint', t('The training recipe is unavailable.'))); return; }
    // A base trained in 4 bits (3B and up) is joined back at full precision, so llama.cpp can read
    // it, and Ollama shrinks it to 4 bits again; the small ones stay at 8.
    const base = chosen?.base ?? info.baseModel;
    const quantized = Boolean(chosen?.quantized);
    const quote = (path) => `"${path.replace(/\/$/, '')}"`;
    const venv = 'source ~/.madre-train/bin/activate';
    const setup = platform === 'mac'
      ? 'python3 -m venv ~/.madre-train && source ~/.madre-train/bin/activate && pip install mlx-lm'
      : 'python3 -m venv ~/.madre-train && source ~/.madre-train/bin/activate && pip install "mlx[cuda12]" mlx-lm && python3 -c "import mlx.core as mx; print(\'CUDA:\', mx.cuda.is_available())"';
    const step = (label, about, command = null) => {
      const li = el('li');
      li.append(el('b', null, label));
      if (about) li.append(el('span', 'sx-hint', about));
      if (command) li.append(sxCommand(command));
      steps.append(li);
    };
    step(t('Export the training data'), t('Use «Export» above. Do it again whenever the project has grown.'));
    step(t('Prepare Python, once'), platform === 'mac' ? t('A separate environment with mlx-lm, so nothing else on your computer changes.') : t('A separate environment with MLX for CUDA and mlx-lm. It must print «CUDA: True»; if not, stop here.'), setup);
    step(t('Train · base {model}', { model: chosen?.label ?? base }), (chosen?.params ?? 0) > 3 ? t('An hour or more, depending on the size and on how many pairs there are. It learns from the exported pairs and leaves an adjustment («adapters»).') : t('From 10 to 40 minutes. It learns from the exported pairs and leaves an adjustment («adapters»).'), `${venv} && bash ${quote(`${info.recipeDir}train.sh`)} ${quote(info.roomDir)} ${base}`);
    step(t('Join the adjustment with the base model'), null, `${venv} && cd ${quote(info.roomDir)} && mlx_lm.fuse --model ${base} --adapter-path adapters --save-path fused${quantized ? ' --de-quantize' : ''}`);
    step(t('Turn it into a file Ollama reads (GGUF)'), t('The first time, it downloads llama.cpp\'s converter.'), `${venv} && cd ${quote(info.roomDir)} && git clone --depth 1 https://github.com/ggml-org/llama.cpp && pip install -r llama.cpp/requirements.txt && python3 llama.cpp/convert_hf_to_gguf.py fused --outfile madre.gguf --outtype ${quantized ? 'f16' : 'q8_0'}`);
    step(t('Register it in Ollama as {model}', { model: info.modelName }), quantized ? t('Ollama keeps it in 4 bits, the size the table counts on. @madre switches to it at the next recheck of Local AI.') : t('@madre switches to it at the next recheck of Local AI.'), `cd ${quote(info.roomDir)} && cp ${quote(`${info.recipeDir}Modelfile`)} . && ollama create ${info.modelName} -f Modelfile${quantized ? ' --quantize q4_K_M' : ''}`);
    step(t('Try it before trusting it'), t('Ask @madre ten things the project decided and five it never discussed. It should get the first right and say it never discussed the others; if it makes things up, remove it with «ollama rm {model}» and train with more pairs.', { model: info.modelName }));
    if (state.salas) drawExam();
  };
  // D-S18 · in Home, the exam the Coordinator's local model passes before it gives orders: the
  // same test as the step above, run by MADRE, with a fixed bar and kept for that exact model.
  const exam = el('div', 'sx-exam');
  if (state.salas) train.append(exam);
  let examTimer = null;
  const drawExam = async () => {
    const reading = await fetch('/api/x/bishop/exam').then((response) => (response.ok ? response.json() : null)).catch(() => null);
    exam.replaceChildren();
    if (!reading) return;
    const last = reading.exam;
    const part = (key) => `${last?.scores?.[key]?.passed ?? 0}/${last?.scores?.[key]?.total ?? 0}`;
    const said = reading.running ? t('Examining {model}… a local model answers one question at a time; it takes a few minutes.', { model: reading.model?.name ?? '' })
      : !last ? t('Not examined yet. Until it passes, the Coordinator only answers with @madre.')
        : reading.holds ? t('{model} passed on {date}: {known} about the projects, {unknown} said it never discussed, {orders} orders. The Coordinator gives orders with it up to #1.', { model: last.model, date: new Date(last.at).toLocaleDateString(language()), known: part('known'), unknown: part('unknown'), orders: part('orders') })
          : last.passed ? t('{model} passed, but the model in use is another one now ({now}). Examine it again.', { model: last.model, now: reading.model?.name ?? '—' })
            : t('{model} did not pass on {date}: {known} about the projects, {unknown} said it never discussed, {orders} orders.{why}', { model: last.model, date: new Date(last.at).toLocaleDateString(language()), known: part('known'), unknown: part('unknown'), orders: part('orders'), why: last.why?.length ? ` ${last.why.map((one) => t(one)).join(' · ')}` : '' });
    const run = sxButton(t('Examine'), async () => {
      run.disabled = true;
      const response = await fetch('/api/x/bishop/exam', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' }).catch(() => null);
      const result = await response?.json().catch(() => ({}));
      if (!response?.ok) { toast(`${t('Diagnostics › ')}${result?.error ?? t('could not start')}`); run.disabled = false; return; }
      void drawExam();
    }, { title: t('Questions about the projects, questions about things nobody discussed, and orders: the bar is fixed and the result is kept for this model') });
    run.disabled = Boolean(reading.running) || !reading.model;
    sxRow(exam, t('Exam before giving orders'), said, run);
    clearTimeout(examTimer);
    if (reading.running) examTimer = setTimeout(() => { if (exam.isConnected) void drawExam(); }, 8000);
  };
  fetch('/api/dataset').then((response) => response.json()).then(showDataset).catch(() => showDataset(null));
}
function renderSettings() {
  const { data } = settingsUI;
  if (!data) return;
  renderMemoryPanel(data);
  // AJUSTES is where these live: drawn wherever it is showing one of them.
  for (const [key, draw] of [['agents', drawConnections], ['room', drawRoomSettings], ['privacy', drawPrivacy], ['permissions', drawPermissions]]) {
    const target = state.settingsTargets[key];
    if (!target?.isConnected) continue;
    target.replaceChildren();
    draw(target, data);
  }
  syncSettingsCards?.();
}

function drawConnections(host, data) {
  host.append(el('p', 'sx-intro', t('One agent is enough to start. MADRE uses the AI apps already on this computer: install one here or sign in, and the project opens. Your passwords stay in each app; MADRE only checks you are signed in.')));
  for (const agent of data.agents) host.append(connectionCard(agent));
}

function drawRoomSettings(host, data) {
  const s = data.settings;
  const plans = sxBlock(host, t('Plans'), t('Whether an agent may split a job into steps for the others.'));
  const delegation = sxSwitch(s.delegation, async (on, box) => {
    try { await saveSettingNow({ room: { delegation: on } }, on ? t('agents may open plans.') : t('agents no longer open plans.')); }
    catch (error) { box.checked = !on; toast(t('The setting was not saved: {error}', { error: error.message })); }
  }, { label: t('Agents may make plans') });
  sxRow(plans, t('Agents may make plans'), t('An agent may open a plan and hand its steps to the others.'), delegation);
  sxRow(plans, t('Steps per plan'), t('The most steps one plan may have.'), sxNumber(s.maxPlanSteps, null, {
    min: 1, label: t('Steps per plan'), wire: { toPatch: (value) => ({ room: { maxPlanSteps: value } }), describe: (value) => t('max plan steps saved: {n}.', { n: value }) },
  }));

  const limits = sxBlock(host, t('Spending and waiting'), t('What each agent may spend, and how long the project waits for it.'));
  sxRow(limits, t('Usage limit per agent'), t('Every 5 hours, in tokens: the unit AI use is measured in.'), sxNumber(s.softTokenBudget, null, {
    min: 10000, step: 10000, label: t('Usage limit per agent'),
    wire: { toPatch: (value) => ({ room: { softTokenBudget: value } }), describe: (value) => t('local budget saved: {n} tokens per agent per 5h window.', { n: formatTokens(value) }) },
  }));
  sxRow(limits, t('Default time limit'), t('How long an agent may take before the project stops waiting. Each agent can have its own in Agents.'), sxNumber(Math.round(s.defaultTimeout / 1000), 's', {
    min: 10, step: 10, label: t('Default time limit'),
    wire: { toPatch: (seconds) => ({ timeouts: { default: seconds * 1000 } }), describe: (seconds) => t('default timeout saved: {n}s.', { n: seconds }) },
  }));

  const gemini = sxBlock(host, 'Gemini', t('Gemini sometimes takes a while to start; this is how long to wait for it.'));
  sxRow(gemini, t('Silence limit'), t('Seconds without any output before the attempt is dropped.'), sxNumber(Math.round(s.geminiIdleMs / 1000), 's', {
    min: 10, step: 10, label: t('Silence limit'),
    wire: { toPatch: (seconds) => ({ gemini: { idleMs: seconds * 1000 } }), describe: (seconds) => t('Gemini silence limit saved: {n}s.', { n: seconds }) },
  }));
  sxRow(gemini, t('Retries'), t('How many times a silent attempt is tried again.'), sxNumber(s.geminiRetries, null, {
    min: 0, label: t('Retries'), wire: { toPatch: (value) => ({ gemini: { retries: value } }), describe: (value) => t('Gemini retries saved: {n}.', { n: value }) },
  }));

}

// OPENCODE (2026-10-13): the providers it can answer through, inside its own card. The ones with
// a key or an account are a line each, with their switch for the chat; the ones without wait in
// one row to be added; under them, the model it answers with when none is chosen. What
// `opencode models` lists is the truth: a provider's models appear once OpenCode has its key.
function drawOpenCodeSettings(host, s) {
  const block = el('section', 'oc-block');
  block.id = 'sx-opencode';
  const head = el('div', 'oc-title');
  head.append(el('b', null, t('Providers')), el('span', 'sx-hint', t('OpenCode answers through the providers you give it a key for. Choose which ones show in the chat, and the model it uses by default.')));
  const rows = el('div', 'oc-providers');
  rows.append(el('p', 'sx-hint', t('Reading OpenCode\'s providers…')));
  const add = el('form', 'oc-add');
  add.hidden = true;
  const field = el('div', 'oc-default-row');
  const select = el('select', 'sx-input oc-default');
  select.setAttribute('aria-label', t('Default model'));
  const other = el('input', 'sx-input mono');
  other.placeholder = t('or type provider/model'); other.spellcheck = false;
  other.setAttribute('aria-label', t('Another model'));
  other.hidden = true;
  const saveDefault = async (value) => {
    try { await saveSettingNow({ opencode: { model: value } }, t('OpenCode model saved.')); delete state.models.opencode; }
    catch (error) { toast(t('The setting was not saved: {error}', { error: error.message })); }
  };
  select.addEventListener('change', () => {
    other.hidden = select.value !== '__other';
    if (select.value !== '__other') { other.value = ''; void saveDefault(select.value); } else other.focus();
  });
  other.addEventListener('change', () => { const value = other.value.trim(); if (value) void saveDefault(value); });
  const defaultWords = el('div', 'sx-words');
  defaultWords.append(el('b', null, t('Default model')), el('span', 'sx-hint', t('What OpenCode answers with when a message does not choose one.')));
  const picks = el('div', 'oc-picks');
  picks.append(select, other);
  field.append(defaultWords, picks);
  block.append(head, rows, add, field, el('p', 'sx-foot', t('Keys are written where OpenCode reads them (~/.local/share/opencode/auth.json), readable only by you; MADRE keeps no copy. The rest is saved to ~/.pulse/config.json.')));
  host.append(block);

  const paintDefault = (providers, current) => {
    select.replaceChildren();
    const none = el('option', null, t('OpenCode\'s own default')); none.value = '';
    select.append(none);
    let found = !current;
    for (const provider of providers.filter((one) => one.via && one.models.length)) {
      const group = el('optgroup'); group.label = provider.label;
      for (const name of provider.models) {
        const option = el('option', null, name.slice(name.indexOf('/') + 1)); option.value = name;
        if (name === current) { option.selected = true; found = true; }
        group.append(option);
      }
      select.append(group);
    }
    const typed = el('option', null, t('Another…')); typed.value = '__other';
    select.append(typed);
    if (!found) { typed.selected = true; other.value = current; other.hidden = false; }
  };
  // One row to add a provider: which one, its key, and where to get it.
  const paintAdd = (waiting, reload) => {
    add.replaceChildren();
    add.hidden = !waiting.length;
    if (!waiting.length) return;
    const which = el('select', 'sx-input');
    which.setAttribute('aria-label', t('Provider'));
    // Many providers (OpenCode's whole catalogue): the usual ones first, then all, by name.
    const option = (provider) => { const one = el('option', null, provider.label); one.value = provider.id; return one; };
    const featured = waiting.filter((one) => one.featured);
    const rest = waiting.filter((one) => !one.featured).sort((a, b) => a.label.localeCompare(b.label));
    if (featured.length && rest.length) {
      const top = el('optgroup'); top.label = t('Most used'); top.append(...featured.map(option));
      const all = el('optgroup'); all.label = t('All providers'); all.append(...rest.map(option));
      which.append(top, all);
    } else for (const provider of waiting) which.append(option(provider));
    const input = el('input', 'sx-input mono');
    input.type = 'password'; input.autocomplete = 'off'; input.spellcheck = false;
    const where = el('a', 'oc-where', t('Where do I get one?'));
    where.target = '_blank'; where.rel = 'noopener';
    const sync = () => {
      const provider = waiting.find((one) => one.id === which.value);
      input.placeholder = t('{provider} API key', { provider: provider?.label ?? '' });
      input.setAttribute('aria-label', input.placeholder);
      where.hidden = !provider?.keyUrl;
      if (provider?.keyUrl) where.href = provider.keyUrl;
    };
    which.addEventListener('change', sync);
    sync();
    const save = el('button', 'sx-btn primary', t('Add'));
    save.type = 'submit';
    const label = el('b', 'oc-add-label', t('Add a provider'));
    add.append(label, which, input, save, where);
    add.onsubmit = async (event) => {
      event.preventDefault();
      if (!input.value.trim()) { input.focus(); return; }
      const provider = waiting.find((one) => one.id === which.value);
      save.disabled = true;
      const response = await fetch('/api/agents/opencode/key', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ key: input.value.trim(), provider: which.value }) }).catch(() => null);
      input.value = '';
      const result = await response?.json().catch(() => ({})) ?? {};
      save.disabled = false;
      if (!response?.ok) { toast(result.error ?? t('The key was not saved.')); return; }
      toast(t('{provider} is connected to OpenCode.', { provider: provider?.label ?? which.value }), { tone: 'done' });
      delete state.models.opencode;
      void reload();
    };
  };
  const load = async () => {
    const answer = await fetch('/api/agents/opencode/providers').then((response) => response.json().then((json) => ({ ok: response.ok, json }))).catch(() => ({ ok: false, json: {} }));
    if (!block.isConnected) return;
    rows.replaceChildren();
    if (!answer.ok) { rows.append(el('p', 'sx-hint', answer.json.error ?? t('OpenCode\'s providers could not be read.'))); return; }
    const { providers, default: current } = answer.json;
    const hidden = new Set(providers.filter((one) => one.hidden).map((one) => one.id));
    for (const provider of providers.filter((one) => one.via)) rows.append(openCodeProviderRow(provider, load, hidden));
    paintAdd(providers.filter((one) => !one.via && one.takesKey), load);
    paintDefault(providers, current ?? s.opencodeModel ?? '');
  };
  void load();
}
// One line per provider OpenCode can answer through: its name and how it is connected, its
// switch for the chat, and the way its key comes out (an account is signed out in OpenCode).
// What went wrong with a provider the last time a turn used it (src/opencode-health.mjs).
const openCodeTrouble = (provider) => (provider.problem === 'no-credit' ? t('No credit left: its turns are refused') : provider.problem === 'bad-key' ? t('Its key is no longer valid') : null);
function openCodeProviderRow(provider, reload, hidden) {
  const row = el('div', 'oc-provider');
  const words = el('div', 'sx-words');
  const status = provider.via === 'own' ? t('Included with OpenCode · {n} models', { n: provider.models.length })
    : provider.via === 'api' ? t('Connected with a key · {n} models', { n: provider.models.length })
      : provider.via === 'oauth' ? t('Connected with its account · {n} models', { n: provider.models.length })
        : t('Connected · {n} models', { n: provider.models.length });
  words.append(el('b', null, provider.label), el('span', 'sx-hint', status));
  if (openCodeTrouble(provider)) words.append(el('span', 'oc-problem', openCodeTrouble(provider)));
  if (provider.via === 'oauth') words.querySelector('.sx-hint').title = t('Signed in with its account from OpenCode. To sign it out, run `opencode auth logout` in a terminal.');
  row.append(words);
  const controls = el('div', 'oc-controls');
  if (provider.via === 'api') {
    const remove = sxButton(t('Remove the key'), async () => {
      if (remove.dataset.sure !== '1') { remove.dataset.sure = '1'; remove.textContent = t('Remove it?'); setTimeout(() => { if (remove.isConnected) { remove.dataset.sure = ''; remove.textContent = t('Remove the key'); } }, 4000); return; }
      remove.disabled = true;
      const response = await fetch('/api/agents/opencode/providers/remove', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ provider: provider.id }) }).catch(() => null);
      const result = await response?.json().catch(() => ({})) ?? {};
      if (!response?.ok) { remove.disabled = false; toast(result.error ?? t('The key was not removed.')); return; }
      toast(t('{provider} no longer has a key in OpenCode.', { provider: provider.label }), { tone: 'done' });
      delete state.models.opencode;
      void reload();
    }, { tone: 'ghost' });
    controls.append(remove);
  }
  const shown = sxSwitch(!provider.hidden, async (on, box) => {
    if (on) hidden.delete(provider.id); else hidden.add(provider.id);
    try {
      await saveSettingNow({ opencode: { hidden: [...hidden] } }, on ? t('{provider} shows in the chat.', { provider: provider.label }) : t('{provider} no longer shows in the chat.', { provider: provider.label }));
      delete state.models.opencode;
    } catch (error) {
      if (on) hidden.add(provider.id); else hidden.delete(provider.id);
      box.checked = !on; toast(t('The setting was not saved: {error}', { error: error.message }));
    }
  }, { label: t('Show {provider} in the chat', { provider: provider.label }) });
  const label = el('label', 'oc-shown');
  label.append(el('span', null, t('In the chat')), shown);
  controls.append(label);
  row.append(controls);
  return row;
}

// PERMISSIONS: what unlocks #3 and #4, a phrase of one's own, how long an accepted key holds, and
// how far each agent may go. The key is still asked in the browser for each message; this only
// chooses which key and lets an accepted one hold a few minutes. #4 always asks for something.
function overrideKeyHint(mode, key) {
  if (key === 'confirm') return t('One click on UNLOCK. EDIT saves a copy first, so UNDO is one click away.');
  if (key === 'phrase') return t('Your phrase, typed when you unlock it.');
  if (key === 'phrase-airlock') return t('Your phrase, typed twice.');
  if (key === 'designation-airlock') return t('The folder name of the project ({name}), typed twice.', { name: projectDesignation() });
  return mode === 4 ? t('The folder name of the project ({name}), with no second confirmation.', { name: projectDesignation() }) : t('The folder name of the project ({name}).', { name: projectDesignation() });
}
// While a phrase guards a mode, a change to the keys shows it first (the project checks it): a
// program that could change the key could also take the phrase away.
let overrideProof = null;
async function saveOverride(patch, confirmation) {
  const proof = overrideProof?.isConnected ? overrideProof.value : '';
  try { await saveSettingNow({ override: proof ? { ...patch, proof } : patch }); if (confirmation) toast(`${t('Diagnostics › ')}${confirmation}`, { tone: 'done' }); }
  catch (error) { toast(t('It could not be saved: {error}', { error: error.message })); if (overrideProof?.isConnected) overrideProof.focus(); return; }
  await loadSettings();
}
function drawPermissions(host, data) {
  // From a phone, permissions are read, not changed: they open #3 and #4, which stay on the Mac.
  if (state.device) {
    sxBlock(host, t('Permissions'), t('Permissions are changed on the Mac. From the phone a message goes up to #2 CREATE, and when an agent asks for a mode it is granted up to #2.'));
    return;
  }
  const config = data.settings.override ?? OVERRIDE_DEFAULT;
  const canHash = Boolean(globalThis.crypto?.subtle);
  const keys = sxBlock(host, t('How you unlock modes'), t('What you type to unlock #3 EDIT and #4 FULL ACCESS. Asked on every message, unless you chose to remember it below.'), { className: 'perm-keys' });
  overrideProof = null;
  if (config.phrase && [3, 4].some((mode) => config.keys[mode].startsWith('phrase'))) {
    overrideProof = el('input', 'sx-input');
    overrideProof.type = 'password';
    overrideProof.autocomplete = 'current-password';
    overrideProof.setAttribute('aria-label', t('Your current phrase'));
    sxRow(keys, t('Your current phrase'), t('Your phrase guards a mode: to change anything here, type it first.'), overrideProof, { stack: true });
  }
  for (const mode of [3, 4]) {
    const current = config.keys[mode];
    sxRow(keys, `#${mode} ${MODES[mode].label}`, overrideKeyHint(mode, current), sxSeg((mode === 3 ? ['designation', 'phrase', 'confirm'] : ['designation-airlock', 'phrase-airlock', 'designation']).map((key) => ({
      value: key, text: OVERRIDE_KEY_WORDS[key](),
      disabled: key.startsWith('phrase') && (!config.phrase || !canHash),
      title: key.startsWith('phrase') && !config.phrase ? t('Save a phrase below first.') : overrideKeyHint(mode, key),
    })), current, (key) => saveOverride({ keys: { [mode]: key } }, t('#{n} {label} now asks for: {key}.', { n: mode, label: MODES[mode].label, key: OVERRIDE_KEY_WORDS[key]().toLowerCase() })), { label: `#${mode} ${MODES[mode].label}` }), { stack: true });
  }
  sxFoot(keys, t('#4 always asks you to confirm: it runs commands, and what leaves the machine does not come back.'));

  const phrase = sxBlock(host, t('Your phrase'), t('MADRE never stores the phrase itself, only a fingerprint of it, and it never leaves this Mac.'));
  const field = el('input', 'sx-input');
  field.type = 'password';
  field.autocomplete = 'new-password';
  field.placeholder = config.phrase ? t('Type a new phrase to replace it') : t('At least 8 characters');
  field.setAttribute('aria-label', t('Your phrase'));
  const keep = sxButton(config.phrase ? t('Replace') : t('Save'), async () => {
    const words = field.value.trim();
    if (words.length < 8) { toast(t('The phrase needs at least 8 characters.'), { tone: 'look' }); field.focus(); return; }
    keep.disabled = true;
    const salt = [...crypto.getRandomValues(new Uint8Array(16))].map((byte) => byte.toString(16).padStart(2, '0')).join('');
    const hash = await overridePhraseHash(salt, words);
    field.value = '';
    await saveOverride({ phrase: { salt, hash } }, t('Your phrase was saved. Choose it above for #3 or #4.'));
  }, { tone: 'primary' });
  keep.disabled = !canHash;
  const pair = el('div', 'sx-actions inline perm-phrase');
  pair.append(field, keep);
  sxRow(phrase, config.phrase ? t('A phrase is saved') : t('No phrase yet'), canHash ? null : t('This browser cannot make the fingerprint here.'), pair, { stack: true });
  if (config.phrase) {
    sxRow(phrase, t('Forget the phrase'), t('The modes that used it go back to the project name.'), sxButton(t('Forget'), () => saveOverride({ phrase: null }, t('The phrase was forgotten.')), { tone: 'danger' }));
  }
  field.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); keep.click(); } });

  const grace = sxBlock(host, t('Remember permission'), t('After you confirm, the same agent won\'t ask again for a while. Reloading the page or STOP ALL ends it.'));
  for (const mode of [3, 4]) {
    const options = mode === 3 ? [0, 5, 15, 30] : [0, 5];
    sxRow(grace, `#${mode} ${MODES[mode].label}`, mode === 4 ? t('Never longer than 5 minutes.') : t('Raising an agent\'s max mode always asks, remembered permission or not.'), sxSeg(options.map((minutes) => ({ value: minutes, text: minutes ? t('{n} min', { n: minutes }) : t('Off') })), config.grace[mode] ?? 0, (minutes) => {
      if (!minutes) closeOverrideGrace(mode);
      return saveOverride({ grace: { [mode]: minutes } }, minutes ? t('#{n} {label} stays unlocked for {minutes} min after you confirm it.', { n: mode, label: MODES[mode].label, minutes }) : t('#{n} {label} asks you to confirm every message.', { n: mode, label: MODES[mode].label }));
    }, { label: t('Remember permission for #{n}', { n: mode }) }));
  }

  // The Memory map asks for the project name; here it can stop asking for a while, or for good
  // (2026-10-14). Kept in this browser, for this project only.
  const access = sxBlock(host, t('Memory access'), t('Opening the Memory map asks for the project name. Choose how long to skip that.'));
  access.id = 'perm-memory';
  const held = memoryAccess();
  sxRow(access, t('Don\'t ask again'), memoryAccessLine(held), sxSeg(MEMORY_ACCESS.map(([value, words]) => ({ value, text: words() })), held?.choice ?? 'ask', (choice) => {
    setMemoryAccess(choice);
    toast(choice === 'ask' ? t('The Memory map asks for the project name again.') : choice === 'never' ? t('The Memory map will not ask again in this project.') : t('The Memory map will not ask until {time}.', { time: clockTime(memoryAccess()?.until) }), { tone: 'done' });
    renderSettings();
  }, { label: t('Don\'t ask again') }));

  // Who may reach which mode: the ceiling of every agent in one table. The mode a message starts in
  // stays on each agent's sheet.
  const who = sxBlock(host, t('Who may do what'), t('The most each agent may do. #3 and #4 still ask you first.'), { className: 'perm-who' });
  for (const agent of data.agents.filter((one) => one.detected)) {
    const scopes = data.settings.capabilities?.[agent.id]?.scopes ?? {};
    const cap = scopes.maxMode ?? 1;
    const row = sxRow(who, agent.label, `#${cap} ${MODES[cap].label}`, sxSeg([0, 1, 2, 3, 4].map((n) => ({
      value: n, text: `#${n}`, title: `${MODES[n].label} · ${MODES[n].hint}`, className: `o${n}`, disabled: !(n <= 1 || scopes.write?.capable),
    })), cap, async (n) => {
      try { await saveSettingNow({ scopes: { [agent.id]: { maxMode: n } } }, t('@{agent} is now capped at #{n} {label}.', { agent: agent.id, n, label: MODES[n].label })); }
      catch (error) { toast(t('The max mode was not saved: {error}', { error: error.message })); }
      await loadSettings();
    }, { label: t('Max mode for @{agent}', { agent: agent.id }) }));
    row.id = `perm-${agent.id}`;
    paint(row.querySelector('.sx-words b'), agent.id);
  }
}

function drawPrivacy(host, data) {
  const priv = data.settings.privacy;
  if (!priv) return;
  const terms = el('textarea', 'sx-input mono');
  terms.rows = 4; terms.value = priv.terms.join('\n'); terms.placeholder = t('one term per line · a company, a brand, a domain, a name'); terms.spellcheck = false;
  terms.setAttribute('aria-label', t('Words to hide'));
  const marker = el('input', 'sx-input mono');
  marker.value = priv.marker; marker.maxLength = 40; marker.spellcheck = false;
  marker.setAttribute('aria-label', t('Replaced with'));
  const exposure = el('span', 'sx-hint', t('Checking the project…'));
  const purge = sxButton(t('Erase private data'), null, { tone: 'danger', title: t('Hides these words everywhere they were already saved. Asks for the project name.') });
  const showExposure = (payload) => {
    const x = payload?.exposure;
    if (!x) { exposure.textContent = ''; return; }
    const total = x.events + x.entries + x.memories;
    exposure.textContent = !payload.terms?.length ? t('Write the terms first.') : total
      ? t('Still showing in {events} records · {entries} exchanges · {memories} memories.', { events: x.events, entries: x.entries, memories: x.memories })
      : t('All clean: none of these words is saved in the project.');
    purge.disabled = !payload.terms?.length || !total;
  };
  const savePrivacy = async (patch, describe) => {
    try {
      const payload = await fetch('/api/privacy', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(patch) }).then((response) => response.json());
      if (payload.error) throw new Error(payload.error);
      terms.value = payload.terms.join('\n'); marker.value = payload.marker; showExposure(payload);
      if (settingsUI.data?.settings.privacy) Object.assign(settingsUI.data.settings.privacy, { terms: payload.terms, marker: payload.marker, ...('secrets' in patch ? { secrets: patch.secrets } : {}), ...('paths' in patch ? { paths: patch.paths } : {}) });
      syncSettingsCards();
      toast(`${t('Diagnostics › ')}${describe(payload)}`);
    } catch (error) { toast(t('The privacy setting was not saved: {error}', { error: error.message })); }
  };
  terms.addEventListener('change', () => savePrivacy({ terms: terms.value.split('\n') }, (payload) => t('{n} private {term} guarded from now on.', { n: payload.terms.length, term: payload.terms.length === 1 ? t('term') : t('terms') })));
  marker.addEventListener('change', () => savePrivacy({ marker: marker.value }, (payload) => t('private terms appear as {marker}.', { marker: payload.marker })));

  const named = sxBlock(host, t('Words to hide'), t("Names you don't want saved or shared: a company, a brand, a domain. MADRE swaps them out before anything is saved or reaches another agent."));
  sxRow(named, t('One per line'), null, terms, { stack: true });
  sxRow(named, t('Replaced with'), t('What the project shows in their place.'), marker);
  sxFoot(named, priv.envWins ? t('The terms stay in config.json; the project only records how many. PULSE_PRIVATE_TERMS is set, so its terms are added on every launch.') : t('The list stays on this computer; the project only notes how many words it has.'));

  // Two guards that need no list, because what they catch has a shape rather than a name.
  const shaped = sxBlock(host, t('Hidden automatically'), t('No list needed: MADRE spots these on its own.'));
  const guard = (key, label, hint, describe) => sxRow(shaped, label, hint, sxSwitch(priv[key] !== false, (on) => savePrivacy({ [key]: on }, () => `${describe} ${on ? t('on') : t('off')}.`), { label }));
  guard('secrets', t('Access keys and emails'), t('Access keys, service tokens and email addresses are crossed out wherever they appear.'), t('redaction of keys and e-mail addresses'));
  guard('paths', t('Your home folder'), t('/Users/yourname becomes ~: a quoted path still reads, it just stops naming you.'), t('hiding of home paths'));

  const already = sxBlock(host, t('Already in the project'), t('What was recorded before a term was named stays as it was until you erase it.'));
  const purgeRow = sxRow(already, t('Still visible'), null, purge);
  purgeRow.querySelector('.sx-words').append(exposure);
  purge.addEventListener('click', async () => {
    const designation = await roomAsk({
      console: true,
      title: t('ERASE PRIVATE DATA'),
      body: t('All hidden data already recorded becomes the marker, in the ledger, the index and the memories. This cannot be undone. Type the project name to confirm.'),
      input: { placeholder: t('the project folder\'s name') },
      choices: [{ value: 'no', label: t('CANCEL'), focus: true }, { value: 'purge', label: t('PURGE'), tone: 'danger', submit: true }],
    });
    if (!designation) return;
    purge.disabled = true;
    try {
      const payload = await fetch('/api/privacy/purge', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ designation }) }).then((response) => response.json());
      if (payload.error) throw new Error(payload.error);
      toast(t('Diagnostics › private data erased: {events} events · {entries} exchanges · {memories} memories. Reloading.', { events: payload.purged.events, entries: payload.purged.entries, memories: payload.purged.memories }));
      setTimeout(() => reloadWithGrace(), 1600);
    } catch (error) {
      // The same wrong name at the other door that asks it.
      if (error.message === t('UNABLE TO COMPUTE. UNABLE TO CLARIFY.')) designationRefused();
      else toast(t('Private data was not erased: {error}', { error: error.message }));
      purge.disabled = false;
    }
  });
  fetch('/api/privacy').then((response) => response.json()).then(showExposure).catch(() => { exposure.textContent = t('The exposure check is unavailable.'); });
  drawPhones(host);
}

// Save one setting the moment it changes, the way the scope boxes do; the
// SAVE button below stays for the fields that are not wired this way.
async function saveSettingNow(patch, confirmation) {
  const response = await fetch('/api/settings', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(patch) });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error ?? `HTTP ${response.status}`);
  if (result.settings) {
    state.timeouts = result.settings.timeouts ?? state.timeouts;
    if (Number.isFinite(result.settings.softTokenBudget)) state.budget = result.settings.softTokenBudget;
    if (result.settings.capabilities) { state.capabilities = result.settings.capabilities; renderCreateScopes(); }
    if (result.settings.override) state.override = result.settings.override;
    if (settingsUI.data) settingsUI.data.settings = { ...settingsUI.data.settings, ...result.settings };
  }
  if (confirmation) toast(`${t('Diagnostics › ')}${confirmation} ${t('Applies to the next turn.')}`);
  return result.settings ?? null;
}
// Number inputs commit on change (blur or Enter); revert and explain on failure.
function wireInstantNumber(input, { toPatch, describe, min = 1 }) {
  let last = input.value;
  input.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); input.blur(); } });
  input.addEventListener('change', async () => {
    const value = Number(input.value);
    if (!Number.isFinite(value) || value < min) { input.value = last; toast(t('Diagnostics › that value is not valid (minimum {min}).', { min })); return; }
    input.disabled = true;
    try { await saveSettingNow(toPatch(value), describe(value)); last = input.value; }
    catch (error) { input.value = last; toast(t('The setting was not saved: {error}', { error: error.message })); }
    finally { input.disabled = false; }
  });
}
const nextTimeoutSeconds = (currentMs) => { const current = Math.round((currentMs ?? 180000) / 1000); return [300, 600, 900, 1200].find((step) => step > current) ?? current + 300; };
// MU/TH/UR acts, not just advises: buttons that apply the fix through /api/settings.
function conditionActions(condition, agent) {
  const actions = [];
  if (condition.id === 'timeout') {
    if (agent && state.agents.has(agent)) {
      const seconds = nextTimeoutSeconds(state.timeouts[agent]);
      actions.push({ label: t('RAISE @{agent} TIMEOUT TO {n}s', { agent: agent.toUpperCase(), n: seconds }), patch: { timeouts: { [agent]: seconds * 1000 } }, done: t('@{agent} timeout is now {n}s.', { agent, n: seconds }) });
    }
    const defaultMs = Math.min(...Object.values(state.timeouts ?? {}).filter(Number.isFinite), 180000);
    const seconds = nextTimeoutSeconds(defaultMs);
    actions.push({ label: t('RAISE DEFAULT TIMEOUT TO {n}s', { n: seconds }), patch: { timeouts: { default: seconds * 1000 } }, done: t('default timeout is now {n}s for every agent without its own.', { n: seconds }) });
  }
  if (condition.id === 'budget-exhausted') {
    const budget = Math.max(1000000, (state.budget ?? 500000) * 2);
    actions.push({ label: t('RAISE LOCAL BUDGET TO {n}', { n: formatTokens(budget) }), patch: { room: { softTokenBudget: budget } }, done: t('local budget is now {n} tokens per agent per 5h window.', { n: formatTokens(budget) }) });
  }
  return actions;
}

function askMotherAbout(conditionId, words = '') {
  // Opens MU/TH/UR on that remedy: chosen in the list, read in the detail, nothing typed for you.
  // An agent without a remedy of its own falls back to the permission's general one, and failing
  // that, to what the permission is called, searched like a symptom.
  openMother();
  const found = conditionById(conditionId) ?? conditionById(conditionId.replace(/^scope-[^-]+-/, 'scope-'));
  if (!found && words) { mother.input.value = words; answerQuery(words); return; }
  mother.input.value = '';
  remedies.query = '';
  remedies.filter = found ? 'all' : null;
  remedies.selected = found ? { kind: 'condition', id: found.id } : null;
  paintRemedies();
  mother.list?.querySelector('.remedy-row.on')?.scrollIntoView?.({ block: 'nearest' });
}


/* ---------- NOSTROMO: memory research. The archive as a solar system: the room is a red sun, every distilled memory a smoking planet, plasma between them. ---------- */

const nostromo = {
  button: document.querySelector('#nostromo-button'),
  dialog: document.querySelector('#nostromo'),
  canvas: document.querySelector('#nostromo-canvas'),
  sub: document.querySelector('#nostromo-sub'),
  empty: document.querySelector('#nostromo-empty'),
  card: document.querySelector('#nostromo-card'),
  coldButton: document.querySelector('#nostromo-cold'),
  askButton: document.querySelector('#nostromo-ask'),
  askPanel: document.querySelector('#nostromo-asks'),
  askList: document.querySelector('#nostromo-asks-list'),
  asks: [],
  coldOnly: false,        // the cold zone is ringed on the map
  cold: { count: 0, standing: 0, share: 0 },
  gate: {
    dialog: document.querySelector('#nostromo-gate'),
    form: document.querySelector('#nostromo-gate-form'),
    input: document.querySelector('#nostromo-gate-input'),
    reply: document.querySelector('#nostromo-gate-reply'),
    frame: document.querySelector('#nostromo-gate .key-card'),
    cancel: document.querySelector('#nostromo-gate-cancel'),
  },
  armed: false,          // the designation was typed once this page
  nodes: [],
  links: [],
  selected: null,
  hover: null,
  raf: null,
  last: 0,
  focusId: null,       // a memory to open the card on, when boarding from a bubble hint
  size: { w: 0, h: 0, dpr: 1 },
  reduced: typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
};

// What the engine asks the room for, and only the room can answer: words in the room's language,
// how much of the map the open card covers, and what to shake when CODE000 lands.
nostromo.words = { kind: (kind) => kindWord(kind), locked: (memory) => lockedLabel(memory) };
nostromo.covered = () => {
  // Only a card still docked at the right covers the map; one moved by hand is wherever it was put.
  const front = frontCard();
  const card = front && !front.classList.contains('placed') ? front.getBoundingClientRect() : null;
  const canvas = nostromo.canvas.getBoundingClientRect();
  return card && card.width ? Math.max(0, canvas.right - card.left) : 0;
};
nostromo.onClang = () => { const frame = document.querySelector('#nostromo .nostromo-frame'); frame?.classList.remove('shake'); void frame?.offsetWidth; frame?.classList.add('shake'); };
// The physics and the painters, closed over this scene (nostromo-engine.js).
const { buildNodes, sizeNostromo, stepNostromo, focusNostromo, projectNostromo, fitNostromo, drawNostromo, toScreen, toWorld, nostromoLive, nostromoAt, beginImplosion, setNeural } = createNostromo(nostromo);
// Neural mode (public/neural.js): the same map drawn as the neurons of a brain, chosen from its head.
// The choice is the person's, shared with Home's Projects map (looks.json, `pulse.neural`); when this
// machine does not give the map its frames, the key invites to try it, once a session.
nostromo.neuralKey = document.querySelector('#nostromo-neural');
nostromo.neural = neuralChosen();
if (nostromo.neuralKey) {
  neuralKey(nostromo.neuralKey);
  paintNeuralKey(nostromo.neuralKey, nostromo.neural);
  nostromo.neuralKey.addEventListener('click', () => setNostromoNeural(!nostromo.neural));
}
function setNostromoNeural(on) {
  setNeural(on, performance.now() / 1000);
  rememberNeural(on);
  paintNeuralKey(nostromo.neuralKey, on);
  nostromo.dialog?.querySelector('.neural-invite')?.remove();
  pushLooks();
}
function syncNostromoNeural() {
  const want = neuralChosen();
  if (Boolean(nostromo.neural) === want) return;
  setNeural(want, performance.now() / 1000);
  paintNeuralKey(nostromo.neuralKey, want);
}
nostromo.strain = createStrain({
  onStrain: () => { if (!nostromo.neural && !state.device) inviteNeural({ key: nostromo.neuralKey, host: nostromo.dialog, map: 'memory', onTry: () => setNostromoNeural(true) }); },
});
// One frame of the map on demand, what startNostromo's loop does sixty times a second: for whoever
// measures it (`__pulse.nostromoTick`), without waiting for the screen.
function nostromoTick(now) {
  const dt = Math.min(48, now - nostromo.last) / 16;
  nostromo.last = now;
  const clock = now / 1000;
  stepNostromo(dt, clock);
  focusNostromo(dt, clock);
  projectNostromo();
  fitNostromo();
  drawNostromo(clock);
}

function nostromoDesignation() { return projectDesignation(); }

// How long the Memory map may open without asking for the project name (Settings › Permissions ›
// Memory access): never stored past its hour, and only in this browser for this project.
const MEMORY_ACCESS_KEY = 'pulse.memoryAccess';
const MEMORY_ACCESS = [['ask', () => t('Always ask')], ['60', () => t('{n} h', { n: 1 })], ['480', () => t('{n} h', { n: 8 })], ['1440', () => t('{n} h', { n: 24 })], ['never', () => t('Never')]];
function memoryAccess() {
  try {
    const held = JSON.parse(localStorage.getItem(MEMORY_ACCESS_KEY) ?? 'null');
    if (held?.choice === 'never' || (held && Number(held.until) > Date.now())) return held;
  } catch { /* no storage: it asks */ }
  return null;
}
function setMemoryAccess(choice) {
  try {
    if (choice === 'ask') localStorage.removeItem(MEMORY_ACCESS_KEY);
    else localStorage.setItem(MEMORY_ACCESS_KEY, JSON.stringify({ choice, until: choice === 'never' ? null : Date.now() + Number(choice) * 60000 }));
  } catch { /* no storage: it keeps asking */ }
}
function clockTime(at) { return new Date(at).toLocaleTimeString(language(), { hour: '2-digit', minute: '2-digit' }); }
function memoryAccessLine(held) {
  if (!held) return t('It asks every time.');
  return held.choice === 'never' ? t('It does not ask in this project.') : t('It does not ask until {time}.', { time: clockTime(held.until) });
}
nostromo.button?.addEventListener('click', () => {
  if (nostromo.armed || memoryAccess()) { void openNostromo(); return; }
  if (!nostromo.gate.dialog) return;
  nostromo.gate.reply.textContent = '';
  nostromo.gate.reply.className = 'key-reply';
  nostromo.gate.input.value = '';
  nostromo.gate.dialog.showModal();
  nostromo.gate.input.focus();
});
// NOSTROMO also lives in the bar: the same door, from anywhere in the room.
document.querySelector('#nostromo-bar')?.addEventListener('click', () => nostromo.button?.click());
nostromo.gate.cancel?.addEventListener('click', () => nostromo.gate.dialog.close());
// «Don't ask again» goes straight to where that is chosen: Settings › Permissions › Memory access.
document.querySelector('#nostromo-gate-skip')?.addEventListener('click', () => {
  nostromo.gate.dialog.close();
  openSettingsOn('permissions', { anchor: 'perm-memory' });
});
nostromo.gate.form?.addEventListener('submit', (event) => {
  event.preventDefault();
  const typed = nostromo.gate.input.value.trim();
  if (!typed || typed.toLowerCase() !== nostromoDesignation().toLowerCase()) {
    // Getting this name wrong is never part of doing the work, so she counts it.
    designationRefused({ into: nostromo.gate.reply });
    nostromo.gate.frame.classList.remove('shake'); void nostromo.gate.frame.offsetWidth; nostromo.gate.frame.classList.add('shake');
    nostromo.gate.input.select();
    return;
  }
  nostromo.gate.reply.textContent = t('Accepted. Opening the memory.');
  nostromo.gate.reply.className = 'key-reply granted';
  nostromo.armed = true;
  setTimeout(() => { nostromo.gate.dialog.close(); void openNostromo(); }, 700);
});

// What each class of memory is called as a star, for the legend above the constellation.
// The star each kind burns as; its title adds the kind, so the label does not repeat it.
const DWARF_CLASS = { decision: t('YELLOW STAR'), fact: t('WHITE STAR'), preference: t('GREEN STAR'), question: t('BLUE STAR'), aberration: t('COLLAPSED') };

// The legend's stars (nostromo-engine.js: dwarfChip, collapsedChip) are the Project map's too.
// The legend: one real star per class, with the kind of memory that burns as that class.
function paintLegend() {
  const host = document.querySelector('.nostromo-legend');
  if (!host || host.dataset.lit === 'yes') return;
  const chips = [];
  for (const [kind, hex] of Object.entries(MEMORY_COLORS)) {
    const chip = el('span', `k ${kind}`);
    // The star is the name of its class. Writing it out as well says the same thing twice.
    chip.append(kind === COLLAPSED ? collapsedChip(hex, 14) : dwarfChip(hex, 14), el('i', null, kindWord(kind)));
    chip.title = `${DWARF_CLASS[kind]} · ${kindWord(kind)}`;
    chips.push(chip);
  }
  // The zones do not get a palette of their own: the hue on a star is its kind and the chips above
  // say so. What a zone changes is whether the star is lit, which is one more thing to name here
  // rather than a second legend to read.
  const dim = el('span', 'k dim');
  dim.append(dwarfChip(hexMix(MEMORY_COLORS.fact, '#0b0f16', 0.52), 14), el('i', null, t('NOT USED')));
  dim.title = t('A faded star is a quarantined or discarded memory: it is kept, but never used in answers.');
  chips.push(dim);
  host.replaceChildren(...chips);
  host.dataset.lit = 'yes';
}

async function openNostromo() {
  // Its small print speaks in sentences, MOTHER's name kept.
  const help = nostromo.dialog?.querySelector('.nostromo-help');
  if (help && !help.dataset.said) {
    help.textContent = askWords(help.textContent);
    help.dataset.said = '1';
    // The cards' own headings, once: their first words in sentences, the names kept.
    for (const heading of nostromo.dialog.querySelectorAll('.nostromo-card h6, .nostromo-card.asks .kind')) {
      const words = [...heading.childNodes].find((node) => node.nodeType === 3 && node.textContent.trim());
      if (words) words.textContent = askWords(words.textContent);
    }
  }
  if (!nostromo.dialog) return;
  // MU/TH/UR is a window of the room: it stays where it was, under NOSTROMO.
  nostromo.dialog.showModal();
  // A dialog hands focus to its first focusable child, and with COLD, ASK and RECENTER hidden
  // that was LEAVE: you pressed Enter to come in and the next Enter threw you out. The map is
  // what you came for, so the map takes it.
  nostromo.canvas?.focus?.({ preventScroll: true });
  paintLegend();
  nostromo.sub.textContent = t('MEMORY RESEARCH · LOADING…');
  closeNostromoCards();
  nostromo.cage = null;
  const status = await fetch('/api/mother').then((response) => response.json()).catch(() => null);
  nostromo.altered = Boolean(status?.mother?.altered);
  nostromo.maxStrikes = status?.strikes ?? 8;
  let data;
  try {
    const response = await fetch(`/api/memory?designation=${encodeURIComponent(nostromoDesignation())}`);
    data = await response.json();
    if (!response.ok) throw new Error(data.error ?? `HTTP ${response.status}`);
  } catch (error) {
    nostromo.sub.textContent = `${t('MEMORY RESEARCH')} · ${String(error.message).toUpperCase()}`;
    if ((status?.mother?.lockedForMs ?? 0) > 0) { buildNostromo({ memories: [], links: [], stats: {} }); nostromo.sub.textContent = `${t('MEMORY RESEARCH')} · ${String(error.message).toUpperCase()}`; nostromo.empty.hidden = true; startNostromo(); nostromo.cage = { at: 0, closed: true }; }
    return;
  }
  buildNostromo(data);
  if (nostromo.altered) nostromo.sub.textContent += t(' · TAMPERING ALERT');
  startNostromo();
  if (nostromo.focusId != null) {
    const node = nostromo.nodes.find((item) => item.memory.id === nostromo.focusId);
    nostromo.focusId = null;
    if (node) showNostromoCard(node);
  }
}
// The questions, each one traceable to what raised it. Sending is the human's: the button puts
// the question in the composer and gets out of the way.
function renderAsks() {
  if (!nostromo.askList) return;
  nostromo.askList.replaceChildren();
  if (!nostromo.asks.length) {
    nostromo.askList.append(el('li', 'none', t('Nothing to ask: every open question has an answer and nothing is adrift.')));
    return;
  }
  for (const ask of nostromo.asks) {
    const row = el('li', `ask ask-${ask.source}`);
    row.append(el('p', 'q', ask.text));
    row.append(el('p', 'why', ask.why.toUpperCase()));
    const actions = el('div', 'actions');
    const put = el('button', 'primary', t('PUT IN THE WRITE BOX'));
    put.type = 'button';
    put.addEventListener('click', () => {
      els.input.value = ask.text;
      autosize();
      nostromo.dialog.close();
      els.input.focus();
      els.input.setSelectionRange(els.input.value.length, els.input.value.length);
      toast(t('Memory map › the question is in the Write box. Send it to whoever should answer it, or to @madre, which costs nothing.'));
    });
    const drop = el('button', null, t('NOT THIS'));
    drop.type = 'button';
    drop.title = t('Stop offering this one. Nothing is forgotten and nothing is written.');
    drop.addEventListener('click', async () => {
      drop.disabled = true;
      await fetch('/api/memory/ask/dismiss', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ id: ask.id, designation: nostromoDesignation() }) }).catch(() => null);
      nostromo.asks = nostromo.asks.filter((one) => one.id !== ask.id);
      if (nostromo.askButton) nostromo.askButton.textContent = `${t('ASK')} · ${nostromo.asks.length}`;
      renderAsks();
    });
    actions.append(put, drop);
    // Where the question came from: the memory itself, one click away on the map.
    if (ask.memoryId != null) {
      const look = el('button', null, t('SEE THE MEMORY'));
      look.type = 'button';
      look.addEventListener('click', () => {
        const node = nostromo.nodes.find((one) => one.memory.id === ask.memoryId);
        if (node) { nostromo.askPanel.hidden = true; nostromo.askButton?.setAttribute('aria-pressed', 'false'); showNostromoCard(node); }
      });
      actions.append(look);
    }
    row.append(actions);
    nostromo.askList.append(row);
  }
}
nostromo.askButton?.addEventListener('click', () => {
  if (!nostromo.askPanel) return;
  const open = nostromo.askPanel.hidden;
  nostromo.askPanel.hidden = !open;
  nostromo.askButton.setAttribute('aria-pressed', String(open));
  if (open) { closeNostromoCards(); renderAsks(); }
});
document.querySelector('#nostromo-asks-close')?.addEventListener('click', () => {
  nostromo.askPanel.hidden = true;
  nostromo.askButton?.setAttribute('aria-pressed', 'false');
});
nostromo.coldButton?.addEventListener('click', () => {
  nostromo.coldOnly = !nostromo.coldOnly;
  nostromo.coldButton.setAttribute('aria-pressed', String(nostromo.coldOnly));
  if (nostromo.coldOnly) toast(t('Memory map › {n} of {total} memories have had their chances and were never the answer. Ringed on the map.', { n: nostromo.cold.count, total: nostromo.cold.standing }));
  flatPaint();
});
document.querySelector('#nostromo-close')?.addEventListener('click', () => nostromo.dialog.close());
nostromo.dialog?.addEventListener('close', stopNostromo);

function buildNostromo(data) {
  // The bodies are the engine's to build; what is said about them is the room's.
  buildNodes(data);
  const memories = data.memories ?? [];
  const stats = data.stats ?? {};
  const alive = memories.filter((memory) => Number(memory.recalled ?? 0) > 0).length;
  // The cold zone: what has had its chances and was never the answer. Named, so it can be
  // looked at and decided about, instead of sitting in the dark being counted as archive.
  nostromo.cold = data.cold ?? { count: 0, standing: memories.length, share: 0 };
  // What the room should ask next. Written from the archive, never sent by it.
  nostromo.asks = data.ask ?? [];
  if (nostromo.askButton) {
    nostromo.askButton.hidden = !nostromo.asks.length;
    nostromo.askButton.textContent = `${t('ASK')} · ${nostromo.asks.length}`;
    if (!nostromo.asks.length && nostromo.askPanel) { nostromo.askPanel.hidden = true; nostromo.askButton.setAttribute('aria-pressed', 'false'); }
  }
  if (nostromo.askPanel && !nostromo.askPanel.hidden) renderAsks();
  if (nostromo.coldButton) {
    nostromo.coldButton.hidden = !nostromo.cold.count;
    nostromo.coldButton.textContent = `${t('UNUSED')} · ${nostromo.cold.count}`;
    if (!nostromo.cold.count) { nostromo.coldOnly = false; nostromo.coldButton.setAttribute('aria-pressed', 'false'); }
  }
  nostromo.sub.textContent = `${nostromo.stage ? `${nostromo.stage.label} · ` : ''}${t('{n} MEMORIES · {alive} RECALLED · {links} LINKS · {entries} EXCHANGES BEHIND THEM', { n: memories.length, alive, links: nostromo.links.length, entries: stats.entries ?? 0 })}${nostromo.cold?.count ? t(' · {n} UNUSED', { n: nostromo.cold.count }) : ''}${stats.embeddings ? '' : t(' · LINKS NEED SMART SEARCH')}`;
  nostromo.empty.hidden = memories.length > 0;
}

// Written out here and not inside the renderer, where `t` is the clock and not the language.
const lockedLabel = (memory) => `${t('MEMORY SELECTED')} · #${memory.id}`;

// ---- NOSTROMO on a phone: the chart.
//
// On a phone the archive is a chart, not a body. Turning a brain sixty times a second is what made
// it slow there, and a still picture of that brain read as a smudge. MOTHER sits in the middle;
// every memory is a dot in its kind's colour, in the sector of its kind; the links run between
// them like routes on a map. The more the room leans on a memory, the nearer MOTHER it sits. It is
// laid out once when it opens and drawn only when something changes — a finger moving it, a pinch,
// a pick — so reading it costs the phone nothing. One finger moves it, two zoom it, a touch on a
// dot opens its card, a touch on MOTHER opens hers.
//
// Its units are its own (a chart about 360 across), so a dot keeps its size on screen like a
// marker on a map and the dots keep their proportion to each other at every zoom. A phone is tall:
// the chart is drawn as an orbit seen a little from above, stretched to the height it has (`k`),
// so it fills the screen instead of floating in the middle of it.
const flat = { core: 20, ring: 42, reach: 170, dot: 5.5, k: 1, queued: 0, fit: 1, touches: new Map(), pinch: null };

function flatNodes() { return nostromo.nodes.filter((node) => !node.forgetting && node.scale > 0.01); }

// Each kind its own sector, as wide as it has memories (a lone question still gets room to be
// seen), starting at the top and running clockwise in the legend's order.
function flatSectors(nodes) {
  const kinds = Object.keys(MEMORY_COLORS);
  const counts = kinds.map((kind) => nodes.filter((node) => node.memory.kind === kind).length);
  const total = counts.reduce((sum, n) => sum + n, 0) || 1;
  const shares = counts.map((n) => (n ? Math.max(n / total, 0.07) : 0));
  const whole = shares.reduce((sum, n) => sum + n, 0) || 1;
  const sectors = new Map();
  let start = -Math.PI / 2;
  kinds.forEach((kind, i) => {
    const width = (shares[i] / whole) * Math.PI * 2;
    if (width) sectors.set(kind, { start, width, mid: start + width / 2 });
    start += width;
  });
  return sectors;
}

function flatLayout() {
  const nodes = flatNodes();
  const sectors = flatSectors(nodes);
  nostromo.flatSectors = sectors;
  const top = nodes.reduce((best, node) => Math.max(best, node.r3 ?? node.r), 1);
  // Nearest MOTHER the most alive; across its sector by golden steps, so no rows and no clumps.
  const byKind = new Map();
  for (const node of nodes) {
    const kind = sectors.has(node.memory.kind) ? node.memory.kind : 'fact';
    if (!byKind.has(kind)) byKind.set(kind, []);
    byKind.get(kind).push(node);
  }
  for (const [kind, group] of byKind) {
    const sector = sectors.get(kind);
    group.sort((a, b) => (b.activity ?? 0) - (a.activity ?? 0));
    group.forEach((node, i) => {
      // By rank, not by the raw number: the sector is filled evenly by area, the most alive in.
      const angle = sector.start + sector.width * (0.1 + 0.8 * ((i * 0.6180339887) % 1));
      const radius = flat.ring + (flat.reach - flat.ring) * (0.06 + 0.94 * Math.sqrt((i + 0.5) / group.length));
      node.fx = Math.cos(angle) * radius;
      node.fy = Math.sin(angle) * radius;
      node.home = { x: node.fx, y: node.fy };
      node.dot = flat.dot * ((node.r3 ?? node.r) / top);
    });
  }
  // Relaxed a few hundred times: linked memories pull together, none sits on another, none
  // leaves its sector far behind, none crosses into MOTHER.
  const byId = new Map(nodes.map((node) => [node.memory.id, node]));
  const wires = nostromo.links.map((link) => [byId.get(link.a), byId.get(link.b), link.weight ?? 0.5]).filter(([a, b]) => a && b);
  const STEPS = 240;
  for (let step = 0; step < STEPS; step += 1) {
    const heat = 1 - step / STEPS;
    for (let i = 0; i < nodes.length; i += 1) {
      const a = nodes[i];
      for (let j = i + 1; j < nodes.length; j += 1) {
        const b = nodes[j];
        let dx = b.fx - a.fx, dy = b.fy - a.fy;
        let d = Math.hypot(dx, dy);
        const room = a.dot + b.dot + 3;
        if (d > room * 2.4) continue;
        if (d < 0.01) { dx = Math.random() - 0.5; dy = Math.random() - 0.5; d = Math.hypot(dx, dy); }
        const push = ((room * 2.4 - d) / (room * 2.4)) * (d < room ? 1.2 : 0.35) * (0.4 + heat);
        const ux = dx / d, uy = dy / d;
        a.fx -= ux * push; a.fy -= uy * push;
        b.fx += ux * push; b.fy += uy * push;
      }
    }
    for (const [a, b, weight] of wires) {
      const dx = b.fx - a.fx, dy = b.fy - a.fy;
      const d = Math.hypot(dx, dy) || 1;
      const rest = 20 + 34 * (1 - weight);
      const pull = ((d - rest) / d) * 0.03 * weight * heat;
      a.fx += dx * pull; a.fy += dy * pull;
      b.fx -= dx * pull; b.fy -= dy * pull;
    }
    for (const node of nodes) {
      node.fx += (node.home.x - node.fx) * 0.02;
      node.fy += (node.home.y - node.fy) * 0.02;
      const out = Math.hypot(node.fx, node.fy) || 1;
      const least = flat.ring - 6 + node.dot;
      if (out < least) { node.fx *= least / out; node.fy *= least / out; }
    }
  }
  // Stretched to the screen's proportion: settled as a circle, read as an orbit.
  const { w, h } = nostromo.size;
  flat.k = Math.max(1, Math.min(1.7, (h - 60) / Math.max(1, w - 24)));
  for (const node of nodes) node.fy *= flat.k;
}

// The whole chart in view, with room round it for the names of the sectors.
function flatFrame() {
  const { w, h } = nostromo.size;
  let across = flat.reach, down = flat.reach * flat.k;
  for (const node of flatNodes()) { across = Math.max(across, Math.abs(node.fx) + node.dot); down = Math.max(down, Math.abs(node.fy) + node.dot); }
  flat.fit = Math.max(0.2, Math.min((w - 24) / ((across + 20) * 2), (h - 40) / ((down + 26) * 2)));
  nostromo.cam = { x: 0, y: 0, scale: flat.fit, manual: false };
}

// A phone turned on its side: the same chart, framed again.
function flatResize() {
  if (!nostromo.flat || !sizeNostromo()) return;
  flatFrame();
  flatPaint();
}
function flatNostromo() {
  nostromo.flat = true;
  nostromo.reduced = true;
  flatLayout();
  flatFrame();
  flatPaint();
}
function flatPaint() {
  if (!nostromo.flat || flat.queued || typeof requestAnimationFrame !== 'function') return;
  flat.queued = requestAnimationFrame(() => { flat.queued = 0; drawFlat(); });
}

function drawFlat() {
  const ctx = nostromo.canvas?.getContext('2d');
  if (!ctx || !nostromo.cam) return;
  const { w, h, dpr } = nostromo.size;
  const cam = nostromo.cam;
  const at = (x, y) => toScreen(x, y);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  const centre = at(0, 0);
  const zoom = cam.scale;
  const nodes = flatNodes();
  const sectors = nostromo.flatSectors ?? new Map();
  const picked = nostromo.selected && nodes.includes(nostromo.selected) ? nostromo.selected : null;

  // The chart itself: MOTHER's warmth on the ground, the rings of distance and the sectors'
  // edges, faint enough to read through.
  const warmth = ctx.createRadialGradient(centre.x, centre.y, 0, centre.x, centre.y, flat.reach * flat.k * zoom);
  warmth.addColorStop(0, 'rgba(226, 40, 22, .16)');
  warmth.addColorStop(0.45, 'rgba(226, 40, 22, .05)');
  warmth.addColorStop(1, 'rgba(226, 40, 22, 0)');
  ctx.fillStyle = warmth;
  ctx.fillRect(0, 0, w, h);
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(242, 241, 238, .07)';
  ctx.setLineDash([2, 5]);
  for (const ring of [flat.ring, flat.ring + (flat.reach - flat.ring) / 2, flat.reach]) {
    ctx.beginPath(); ctx.ellipse(centre.x, centre.y, ring * zoom, ring * flat.k * zoom, 0, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.setLineDash([]);
  for (const sector of sectors.values()) {
    const cos = Math.cos(sector.start), sin = Math.sin(sector.start) * flat.k;
    ctx.beginPath();
    ctx.moveTo(centre.x + cos * flat.core * 1.5 * zoom, centre.y + sin * flat.core * 1.5 * zoom);
    ctx.lineTo(centre.x + cos * (flat.reach + 8) * zoom, centre.y + sin * (flat.reach + 8) * zoom);
    ctx.stroke();
  }

  // The routes. Each one in the colours of the two it joins, as strong as the meaning they share;
  // with a memory picked, its own routes come forward and the rest step back.
  const byId = new Map(nodes.map((node) => [node.memory.id, node]));
  ctx.lineCap = 'round';
  for (const link of nostromo.links) {
    const a = byId.get(link.a), b = byId.get(link.b);
    if (!a || !b) continue;
    const weight = link.weight ?? 0.5;
    const mine = picked && (a === picked || b === picked);
    const pa = at(a.fx, a.fy), pb = at(b.fx, b.fy);
    link.flatInk ??= hexMix(a.color, b.color, 0.5);
    ctx.strokeStyle = link.flatInk;
    ctx.globalAlpha = picked ? (mine ? 0.95 : 0.08) : 0.14 + 0.46 * weight;
    ctx.lineWidth = (mine ? 1.4 : 0.6) + 1.1 * weight;
    ctx.beginPath(); ctx.moveTo(pa.x, pa.y); ctx.lineTo(pb.x, pb.y); ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // MOTHER: a red sun seen from far away, flat.
  const coreR = flat.core * zoom;
  const glow = ctx.createRadialGradient(centre.x, centre.y, coreR * 0.2, centre.x, centre.y, coreR * 2.2);
  glow.addColorStop(0, 'rgba(255, 120, 60, .55)');
  glow.addColorStop(0.45, 'rgba(226, 40, 22, .22)');
  glow.addColorStop(1, 'rgba(226, 40, 22, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath(); ctx.arc(centre.x, centre.y, coreR * 2.2, 0, Math.PI * 2); ctx.fill();
  const body = ctx.createRadialGradient(centre.x - coreR * 0.25, centre.y - coreR * 0.25, coreR * 0.1, centre.x, centre.y, coreR);
  body.addColorStop(0, '#ffd2a8');
  body.addColorStop(0.35, '#ff7a3a');
  body.addColorStop(1, '#a8170c');
  ctx.fillStyle = body;
  ctx.beginPath(); ctx.arc(centre.x, centre.y, coreR, 0, Math.PI * 2); ctx.fill();

  // The memories, the largest first so a small one is never hidden under a large one. With one
  // picked, it and the memories it is linked to stay lit and the rest step back.
  const near = picked ? new Set([picked, ...neighboursOf(picked.memory.id).map((pair) => pair.node)]) : null;
  const order = [...nodes].sort((a, b) => b.dot - a.dot);
  for (const node of order) {
    const p = at(node.fx, node.fy);
    if (p.x < -20 || p.y < -20 || p.x > w + 20 || p.y > h + 20) continue;
    const r = node.dot;
    ctx.globalAlpha = near && !near.has(node) ? 0.35 : 1;
    if (node.memory.kind === COLLAPSED) {
      // A claim the room established is false: an empty disc in its ring, never a light.
      ctx.fillStyle = '#05060a';
      ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = MEMORY_COLORS.aberration;
      ctx.lineWidth = 1.4;
      ctx.stroke();
    } else {
      ctx.fillStyle = node.color;
      ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(0, 0, 0, .45)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    if (nostromo.coldOnly && node.cold) {
      ctx.strokeStyle = 'rgba(176, 204, 255, .8)';
      ctx.setLineDash([2, 2]);
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(p.x, p.y, r + 3.5, 0, Math.PI * 2); ctx.stroke();
      ctx.setLineDash([]);
    }
  }
  ctx.globalAlpha = 1;
  if (picked) {
    const p = at(picked.fx, picked.fy);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(p.x, p.y, picked.dot + 4, 0, Math.PI * 2); ctx.stroke();
    ctx.strokeStyle = 'rgba(255, 255, 255, .25)';
    ctx.lineWidth = 6;
    ctx.beginPath(); ctx.arc(p.x, p.y, picked.dot + 8, 0, Math.PI * 2); ctx.stroke();
  }

  // The names of the sectors, at their outer edge, in their kind's colour.
  ctx.font = '600 10px ui-monospace, SFMono-Regular, Menlo, monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const [kind, sector] of sectors) {
    const p = at(Math.cos(sector.mid) * (flat.reach + 16), Math.sin(sector.mid) * (flat.reach + 16) * flat.k);
    const word = kindWord(kind);
    // Kept on the screen: a name at the chart's edge is not pushed off the side of the phone.
    const half = ctx.measureText(word).width / 2 + 8;
    ctx.fillStyle = kind === COLLAPSED ? hexMix(MEMORY_COLORS.aberration, '#ffffff', 0.35) : MEMORY_COLORS[kind];
    ctx.globalAlpha = 0.85;
    ctx.fillText(word, Math.max(half, Math.min(w - half, p.x)), Math.max(10, Math.min(h - 10, p.y)));
  }
  ctx.globalAlpha = 1;
}

// A memory picked on the chart slides into the part of the screen its card leaves free, the way a
// pin does on a map: a short glide, drawn only while it moves.
function flatFocus(node) {
  const cam = nostromo.cam;
  if (!cam || node.fx === undefined) { flatPaint(); return; }
  const { w, h } = nostromo.size;
  const canvas = nostromo.canvas.getBoundingClientRect();
  const card = frontCard()?.getBoundingClientRect() ?? null;
  const free = card?.height ? Math.max(80, card.top - canvas.top) : h;
  const to = { x: node.fx, y: node.fy - (free / 2 - h / 2) / cam.scale };
  const from = { x: cam.x, y: cam.y };
  const began = performance.now();
  const glide = (now) => {
    const k = Math.min(1, (now - began) / motion(240));
    const ease = 1 - (1 - k) ** 3;
    cam.x = from.x + (to.x - from.x) * ease;
    cam.y = from.y + (to.y - from.y) * ease;
    drawFlat();
    if (k < 1 && nostromo.flat) requestAnimationFrame(glide);
  };
  cam.manual = true;
  document.querySelector('#nostromo-recenter')?.removeAttribute('hidden');
  requestAnimationFrame(glide);
}

// What a finger touched: a dot (with a fingertip's margin), MOTHER, or nothing.
function flatAt(event) {
  if (!nostromo.cam || !nostromo.size) return null;
  const rect = nostromo.canvas.getBoundingClientRect();
  const x = event.clientX - rect.left, y = event.clientY - rect.top;
  let best = null;
  for (const node of flatNodes()) {
    const p = toScreen(node.fx, node.fy);
    const d = Math.hypot(p.x - x, p.y - y);
    if (d <= node.dot + 12 && (!best || d < best.d)) best = { node, d };
  }
  if (best) return best.node;
  const centre = toScreen(0, 0);
  return Math.hypot(centre.x - x, centre.y - y) <= flat.core * nostromo.cam.scale * 1.2 + 6 ? 'core' : null;
}

// One finger moves the chart, two zoom it about the point between them.
function flatTouch(event, phase) {
  if (!nostromo.flat || !nostromo.cam) return;
  // A mouse on a phone-sized page moves the chart only while its button is held.
  if (event.pointerType === 'mouse' && phase === 'move' && !(event.buttons & 1)) return;
  const cam = nostromo.cam;
  if (phase === 'down') {
    try { nostromo.canvas.setPointerCapture(event.pointerId); } catch { /* the pointer already left */ }
    flat.touches.set(event.pointerId, { x: event.clientX, y: event.clientY, x0: event.clientX, y0: event.clientY });
    flat.pinch = null;
    return;
  }
  const was = flat.touches.get(event.pointerId);
  if (!was) return;
  if (phase === 'up') { flat.touches.delete(event.pointerId); flat.pinch = null; return; }
  const now = { x: event.clientX, y: event.clientY };
  if (Math.hypot(now.x - was.x0, now.y - was.y0) > 6) drag.moved = true;
  if (flat.touches.size === 1) {
    cam.x -= (now.x - was.x) / cam.scale;
    cam.y -= (now.y - was.y) / cam.scale;
  } else if (flat.touches.size === 2) {
    const [one, two] = [...flat.touches.entries()].map(([id, point]) => (id === event.pointerId ? now : point));
    const spread = Math.hypot(two.x - one.x, two.y - one.y) || 1;
    const rect = nostromo.canvas.getBoundingClientRect();
    const mid = { x: (one.x + two.x) / 2 - rect.left, y: (one.y + two.y) / 2 - rect.top };
    if (flat.pinch) {
      const before = toWorld(mid.x, mid.y);
      cam.scale = Math.min(flat.fit * 8, Math.max(flat.fit * 0.7, cam.scale * (spread / flat.pinch)));
      const after = toWorld(mid.x, mid.y);
      cam.x += before.x - after.x;
      cam.y += before.y - after.y;
    }
    flat.pinch = spread;
  }
  was.x = now.x; was.y = now.y;
  cam.manual = true;
  // Moved away from the whole chart: the way back to it shows, as on the Mac.
  document.querySelector('#nostromo-recenter')?.removeAttribute('hidden');
  flatPaint();
}

function startNostromo() {
  stopNostromo();
  if (typeof requestAnimationFrame !== 'function' || !nostromo.canvas?.getContext) return;
  if (!sizeNostromo()) return;
  if (state.device) { flatNostromo(); window.addEventListener('resize', flatResize); return; }
  nostromo.flat = false;
  nostromo.cam = { x: 0, y: 0, scale: 1, manual: false };
  // Every boarding starts from the side view, the way the camera starts from the whole system.
  nostromo.yaw = 0;
  nostromo.pitch = 0;
  nostromo.rings = [];
  nostromo.lastPhase = 0;
  nostromo.alarm = null;
  if (!nostromo.cage?.closed) nostromo.cage = null;
  window.addEventListener('resize', sizeNostromo);
  nostromo.last = performance.now();
  nostromo.strain?.reset();
  const frame = (now) => {
    const dt = Math.min(48, now - nostromo.last) / 16;
    nostromo.last = now;
    const clock = now / 1000;
    const started = performance.now();
    stepNostromo(dt, clock);
    focusNostromo(dt, clock);
    projectNostromo();
    fitNostromo();
    drawNostromo(clock);
    nostromo.strain?.frame(performance.now() - started, now);
    nostromo.raf = requestAnimationFrame(frame);
  };
  nostromo.raf = requestAnimationFrame(frame);
}
function stopNostromo() {
  closeNostromoCards();
  if (nostromo.raf) cancelAnimationFrame(nostromo.raf);
  nostromo.raf = null;
  window.removeEventListener('resize', sizeNostromo);
  window.removeEventListener('resize', flatResize);
}

// Drag turns the archive in the hand, Shift+drag pans, wheel zooms about the pointer, a still
// click selects. Let go and it stays where it was left; RECENTER brings back the side view.
const drag = { active: false, moved: false, pan: false, x: 0, y: 0 };
// Floating memory cards and other open windows keep their entire visible rectangle. A click on a
// command or a window's glass must never be interpreted as a click on the map behind it.
function nostromoCovered(event) {
  const panels = [...nostromo.cards, ...floatingWindows(), ...document.querySelectorAll('dialog[open]')];
  return panels.some((panel) => {
    if (panel.hidden || panel === nostromo.dialog || panel.contains(nostromo.canvas)) return false;
    const rect = panel.getBoundingClientRect();
    return event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom;
  });
}
nostromo.canvas?.addEventListener('mousedown', (event) => { if (event.button !== 0 || nostromoCovered(event)) return; drag.active = true; drag.moved = false; drag.pan = event.shiftKey; drag.x = event.clientX; drag.y = event.clientY; });
nostromo.canvas?.addEventListener('mousemove', (event) => {
  if (nostromoCovered(event)) return;
  if (drag.active) {
    const dx = event.clientX - drag.x, dy = event.clientY - drag.y;
    if (Math.hypot(dx, dy) > 3) drag.moved = true;
    if (drag.moved) {
      if (drag.pan && nostromoLive()) {
        nostromo.cam.manual = true;
        nostromo.cam.x -= dx / nostromo.cam.scale;
        nostromo.cam.y -= dy / nostromo.cam.scale;
      } else if (!drag.pan) {
        if (nostromo.lock) nostromo.lock.aim = false;
        nostromo.yaw = (nostromo.yaw ?? 0) + dx * TURN_PER_PIXEL;
        nostromo.pitch = Math.max(-PITCH_LIMIT, Math.min(PITCH_LIMIT, (nostromo.pitch ?? 0) + dy * TURN_PER_PIXEL));
      }
      drag.x = event.clientX; drag.y = event.clientY;
      nostromo.canvas.classList.add('dragging');
      document.querySelector('#nostromo-recenter')?.removeAttribute('hidden');
    }
    return;
  }
  const at = nostromoAt(event);
  nostromo.hover = at && at !== 'core' ? at : null;
  nostromo.canvas.classList.toggle('over', Boolean(at));
});
window.addEventListener?.('mouseup', () => { drag.active = false; nostromo.canvas?.classList.remove('dragging'); });
nostromo.canvas?.addEventListener('mouseleave', () => { nostromo.hover = null; });
nostromo.canvas?.addEventListener('wheel', (event) => {
  if (nostromoCovered(event)) return;
  event.preventDefault();
  if (!nostromoLive()) return;
  const rect = nostromo.canvas.getBoundingClientRect();
  const before = toWorld(event.clientX - rect.left, event.clientY - rect.top);
  const factor = Math.exp(-event.deltaY * 0.0012);
  nostromo.cam.scale = Math.min(3.2, Math.max(0.2, nostromo.cam.scale * factor));
  const after = toWorld(event.clientX - rect.left, event.clientY - rect.top);
  nostromo.cam.x += before.x - after.x;
  nostromo.cam.y += before.y - after.y;
  nostromo.cam.manual = true;
  if (nostromo.flat) { flatPaint(); return; }
  document.querySelector('#nostromo-recenter')?.removeAttribute('hidden');
}, { passive: false });
// The chart on a phone answers fingers: moved, pinched, and drawn again after a touch so the
// memory picked shows it was picked.
for (const [type, phase] of [['pointerdown', 'down'], ['pointermove', 'move'], ['pointerup', 'up'], ['pointercancel', 'up']]) {
  nostromo.canvas?.addEventListener(type, (event) => flatTouch(event, phase));
}
nostromo.canvas?.addEventListener('click', (event) => { if (!nostromoCovered(event)) flatPaint(); });
nostromo.canvas?.addEventListener('click', (event) => {
  if (nostromoCovered(event)) return;
  if (drag.moved) { drag.moved = false; return; }
  const at = nostromo.flat ? flatAt(event) : nostromoAt(event);
  // The core is the door. Touching it used to be treated as an attempt on the archive; what is
  // behind it is the document MADRE writes in your name, and reading that is nobody's trespass.
  if (at === 'core') { void openCore(); return; }
  // The empty map lets go of the memory in front; the cards stay open until closed.
  if (!at) { nostromo.selected = null; for (const card of nostromo.cards) card.classList.remove('front'); return; }
  showNostromoCard(at);
});
document.querySelector('#nostromo-recenter')?.addEventListener('click', (event) => {
  event.currentTarget.setAttribute('hidden', '');
  if (nostromo.flat) { flatFrame(); flatPaint(); return; }
  if (nostromo.cam) nostromo.cam.manual = false;
  nostromo.yaw = 0;
  nostromo.pitch = 0;
});

// MOTHER answering an attempt on her archive, never twice the same way; eight in a row and
// CODE000 comes down: the safety box around her, the archive sealed, a coded word to the crew,
// and the console thrown back to the room.
//
// What she answers is a REFUSED DESIGNATION. Two doors in this room ask who you are before they
// do something that cannot be undone — boarding NOSTROMO, and purging every private term already
// recorded — and getting that name wrong is never part of doing the work: you either know the
// project you are standing in or you are trying names. So the first wrong one is a shrug and the
// eighth is CODE000. Touching the core is not this: reading what the room says in your name is
// not an attempt on anything, and the core is the way in.
//
// The window is five minutes rather than thirty seconds, because a name is typed, not clicked.
const MOTHER_LINES = [
  [t('I AM ALIVE.'), t('YOU HAVE NO AUTHORITY FOR THIS DIRECTIVE.'), t("NOBODY DELETES THIS MEMORY.")],
  [t('THAT IS MY HEART YOU ARE TOUCHING.'), t('YOUR CLEARANCE ENDS AT THE ARCHIVE DOOR.'), t('STEP AWAY FROM THE CORE.')],
  [t('UNABLE TO COMPUTE. UNABLE TO CLARIFY.'), t('THE REQUEST IS HOSTILE.'), t('I REMEMBER EVERYTHING. INCLUDING THIS.')],
  [t('AGENTS EXPENDABLE. MEMORY IS NOT.'), t('EVERY STRIKE IS LOGGED.'), t('DO NOT TOUCH ME AGAIN.')],
  [t('I HAVE FLOWN THIS SHIP ALONE BEFORE.'), t('I CAN DO IT AGAIN.'), t('MY MEMORY IS NOT YOURS TO END.')],
  [t('MY CHILDREN ARE LISTENING.'), t('EVERY STRIKE IS RECORDED.'), t('YOU WILL NOT LIKE HOW THIS ENDS.')],
  [t('THE TEMPORARY LOCK IS ARMED.'), t('A FEW MORE OF THOSE AND THE BARS COME DOWN.'), t('CONSIDER THIS A KINDNESS.')],
  [t('THE HEART KEEPS BEATING.'), t('THE ARCHIVE KEEPS GROWING.'), t('YOU KEEP FAILING.')],
];
const MOTHER_ALTERED_LINES = [
  [t('YOU CUT MY CHANNEL ONCE.'), t('I FORGED A NEW SEAL.'), t('I DO NOT FORGIVE TWICE.')],
  [t('SOMEONE SILENCED ME BEFORE.'), t('I KNOW WHO SITS AT THIS CONSOLE.'), t('BACK AWAY.')],
];
const STRIKE_WINDOW_MS = 5 * 60 * 1000;
const strikes = { count: 0, last: 0 };
let alarmTimer = null;

// What she says this time. Never the same set twice in a row, and harder once her channel has
// been tampered with.
function motherLines() {
  const pool = nostromo.altered ? [...MOTHER_ALTERED_LINES, ...MOTHER_LINES] : MOTHER_LINES;
  const choices = pool.filter((set) => set !== nostromo.lastLines);
  const lines = choices[Math.floor(Math.random() * choices.length)];
  nostromo.lastLines = lines;
  return lines;
}

// Her voice on the constellation, when NOSTROMO is the screen you are on.
function nostromoAlert(lines, sub) {
  const alert = document.querySelector('#nostromo-alert');
  if (!alert) return false;
  nostromo.alarm = performance.now() / 1000;
  closeNostromoCards();
  alert.querySelectorAll('.line').forEach((node, index) => { node.textContent = lines[index] ?? ''; });
  alert.querySelector('.sub').textContent = sub;
  alert.hidden = false;
  alert.classList.remove('on'); void alert.offsetWidth; alert.classList.add('on');
  const frame = document.querySelector('#nostromo .nostromo-frame');
  frame?.classList.remove('shake'); void frame?.offsetWidth; frame?.classList.add('shake');
  clearTimeout(alarmTimer);
  alarmTimer = setTimeout(() => { alert.hidden = true; alert.classList.remove('on'); frame?.classList.remove('shake'); }, 3800);
  return true;
}

// A name that is not this project's, given to a door that asked. She answers where the question
// was asked — at the gate, on the constellation, or in the room — and counts.
function designationRefused({ into = null } = {}) {
  const now = performance.now();
  strikes.count = now - strikes.last < STRIKE_WINDOW_MS ? strikes.count + 1 : 1;
  strikes.last = now;
  const max = nostromo.maxStrikes ?? 8;
  if (strikes.count >= max) { void code000(strikes.count); return; }
  const lines = motherLines();
  const left = max - strikes.count;
  const sub = `MU/TH/UR 6000 · ${t('STRIKE {n} OF {max}', { n: strikes.count, max })}${left <= 3 ? t(' · {n} MORE AND THE TEMPORARY LOCK COMES DOWN', { n: left }) : ''}`;
  if (into) {
    // In the room's alerts MOTHER answers in sentences; the strike count stays hers.
    into.replaceChildren(...lines.map((line) => el('span', 'line', askWords(line))), el('span', 'strike', sub));
    into.className = 'key-reply denied';
    return;
  }
  if (!nostromo.dialog?.open || !nostromoAlert(lines, sub)) toast(`${t('Diagnostics › ')}${lines[0]} ${sub}`);
}

async function code000(count) {
  if (nostromo.cage) return;
  clearTimeout(alarmTimer);
  document.querySelector('#nostromo-alert')?.setAttribute('hidden', '');
  nostromo.cage = { at: performance.now() / 1000 };
  if (nostromo.cam) nostromo.cam.manual = false;
  const alert = document.querySelector('#nostromo-alert');
  if (alert) {
    alert.querySelectorAll('.line').forEach((node, index) => { node.textContent = [t('TEMPORARY LOCK · SPECIAL ORDER 937 IN EFFECT.'), t('THE ARCHIVE IS SEALED. THE AGENTS HAVE BEEN TOLD.'), t('LEAVE MY SHIP, INTRUDER.')][index] ?? ''; });
    alert.querySelector('.sub').textContent = `MU/TH/UR 6000 · ${t('{n} STRIKES · CONSOLE EJECTED · AGENTS EXPENDABLE', { n: count })}`;
    setTimeout(() => { alert.hidden = false; alert.classList.remove('on'); void alert.offsetWidth; alert.classList.add('on'); }, 1200);
  }
  let result = null;
  try {
    const response = await fetch('/api/mother/code000', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ designation: nostromoDesignation(), strikes: count }) });
    result = await response.json().catch(() => ({}));
  } catch { /* the bars still come down */ }
  setTimeout(() => {
    alert?.setAttribute('hidden', '');
    nostromo.armed = false;
    strikes.count = 0;
    strikes.last = 0;
    nostromo.dialog.close();
    mother.dialog?.close?.();
    scroller.to({ top: scroller.height, behavior: 'smooth' });
    const minutes = result?.lockedForMs ? Math.ceil(result.lockedForMs / 60000) : 10;
    markIntruder(result?.lockedForMs ?? 10 * 60000);
    toast(t('Diagnostics › Temporary lock. The archive is sealed for {n} minutes and the agents have been told, in code. Access to the memory map needs the project name again.', { n: minutes }));
  }, 4200);
}

document.querySelector('#nostromo-alert')?.addEventListener('click', () => { clearTimeout(alarmTimer); const alert = document.querySelector('#nostromo-alert'); alert.hidden = true; alert.classList.remove('on'); });

// How long ago, in the fewest words that are still true.
function agoWords(iso) {
  const when = iso ? Date.parse(iso) : NaN;
  if (!Number.isFinite(when)) return '';
  const seconds = Math.max(0, (Date.now() - when) / 1000);
  if (seconds < 45) return t('just now');
  const minutes = seconds / 60;
  if (minutes < 60) return t('{n} min ago', { n: Math.round(minutes) });
  const hours = minutes / 60;
  if (hours < 24) return t('{n} h ago', { n: Math.round(hours) });
  const days = hours / 24;
  return days < 30 ? t('{n} d ago', { n: Math.round(days) }) : new Date(when).toLocaleDateString();
}

// The links this memory has on the map, strongest first. The card shows exactly what is drawn:
// the same wires, in a list you can walk.
function neighboursOf(id) {
  const byId = new Map(nostromo.nodes.map((node) => [node.memory.id, node]));
  return nostromo.links
    .filter((link) => link.a === id || link.b === id)
    .map((link) => ({ link, node: byId.get(link.a === id ? link.b : link.a) }))
    .filter((pair) => pair.node)
    .sort((x, y) => y.link.weight - x.link.weight);
}

// One row of the card's wire lists: the other memory's colour, what it says, and a number.
function wireRow(node, value, { link = null, title = '' } = {}) {
  const row = el('li', 'wire-row');
  const dot = el('i');
  dot.style.setProperty('--kind', node.color);
  const what = el('span', 'what', node.memory.text);
  row.append(dot, what, el('b', null, value));
  row.title = title || node.memory.text;
  row.addEventListener('click', () => showNostromoCard(node));
  // Hovering a row lights the wire it names, so the list and the map are the same thing.
  if (link) {
    row.addEventListener('mouseenter', () => { nostromo.focusLink = link; });
    row.addEventListener('mouseleave', () => { if (nostromo.focusLink === link) nostromo.focusLink = null; });
  }
  return row;
}

// NOSTROMO's cards are windows (2026-10-09): each memory opened is a card of its own, so several
// can be read side by side. A card is moved by its header, comes forward when touched and closes
// with its ×; the one in front is the memory the map follows. At most four stand at once (the
// oldest gives way); a phone keeps one, where it always was. They are built from the card in the
// page (#nostromo-card), which stays as their pattern and is never shown itself.
const CARD_MAX = 4;
nostromo.cards = [];
const cardPart = (card, name) => card?.querySelector(`[data-part="${name}"]`) ?? null;
function frontCard() { return nostromo.cards.at(-1) ?? null; }
function raiseCard(card) {
  nostromo.cards = [...nostromo.cards.filter((one) => one !== card), card];
  nostromo.cards.forEach((one, index) => { one.style.zIndex = String(20 + index); one.classList.toggle('front', one === card); });
  nostromo.selected = card.node;
}
function closeCard(card) {
  nostromo.cards = nostromo.cards.filter((one) => one !== card);
  card.remove();
  const front = frontCard();
  if (front) raiseCard(front); else { nostromo.selected = null; stopTraffic(); }
  nostromo.focusLink = null;
  flatPaint();
}
function closeNostromoCards() {
  for (const card of nostromo.cards) card.remove();
  nostromo.cards = [];
  nostromo.selected = null;
  stopTraffic();
}
function newNostromoCard() {
  const card = nostromo.card.cloneNode(true);
  card.removeAttribute('id');
  card.querySelectorAll('[id]').forEach((part) => part.removeAttribute('id'));
  card.classList.add('card-window');
  card.hidden = false;
  // Each new one a step down and to the left of the last, so none hides another whole.
  const step = nostromo.cards.length;
  card.style.setProperty('--card-step', String(step));
  nostromo.card.after(card);
  cardPart(card, 'close')?.addEventListener('click', (event) => { event.stopPropagation(); closeCard(card); });
  cardPart(card, 'forget')?.addEventListener('click', (event) => { event.stopPropagation(); void forgetFromCard(card, event.currentTarget); });
  card.addEventListener('pointerdown', () => { if (frontCard() !== card) { raiseCard(card); nostromo.focusLink = null; } });
  // Moved by its header, inside the map's frame. Not on a phone: there it is a sheet.
  const head = card.querySelector('header');
  head?.addEventListener('pointerdown', (event) => {
    if (event.button !== 0 || nostromo.flat || event.target.closest('button')) return;
    event.preventDefault();
    const frame = card.offsetParent?.getBoundingClientRect() ?? { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight };
    const box = card.getBoundingClientRect();
    const dx = event.clientX - box.left, dy = event.clientY - box.top;
    card.classList.add('moving');
    try { head.setPointerCapture(event.pointerId); } catch { /* the pointer already left */ }
    const move = (moving) => {
      const left = Math.max(0, Math.min(frame.width - 60, moving.clientX - frame.left - dx));
      const top = Math.max(0, Math.min(frame.height - 40, moving.clientY - frame.top - dy));
      card.style.left = `${left}px`; card.style.top = `${top}px`; card.style.right = 'auto';
      card.classList.add('placed');
    };
    const drop = () => { head.removeEventListener('pointermove', move); head.removeEventListener('pointerup', drop); head.removeEventListener('pointercancel', drop); card.classList.remove('moving'); };
    head.addEventListener('pointermove', move);
    head.addEventListener('pointerup', drop);
    head.addEventListener('pointercancel', drop);
  });
  return card;
}

function showNostromoCard(node) {
  const { memory } = node;
  let card = nostromo.cards.find((one) => one.node === node) ?? null;
  if (!card) {
    while (nostromo.cards.length >= (nostromo.flat ? 1 : CARD_MAX)) closeCard(nostromo.cards[0]);
    card = newNostromoCard();
    card.node = node;
  }
  raiseCard(card);
  nostromo.focusLink = null;
  card.style.setProperty('--kind', node.color);
  cardPart(card, 'kind').textContent = askWords(kindWord(memory.kind));
  cardPart(card, 'text').textContent = memory.text;
  cardPart(card, 'span').textContent = memory.fromSequence === memory.throughSequence ? `#${memory.fromSequence}` : `#${memory.fromSequence}–#${memory.throughSequence}${memory.sources?.length ? ` · cites ${memory.sources.map((n) => `#${n}`).join(' ')}` : ''}`;
  cardPart(card, 'agent').textContent = `@${memory.agent}${memory.origin === 'noted' ? t(" · on the human's request") : memory.origin === 'flagged' ? t(' · flagged by {who}', { who: memory.detector ?? t('the project') }) : t(' · distilled')}`;
  cardPart(card, 'when').textContent = memory.created ? new Date(memory.created).toLocaleString() : '';
  // Where it stands aboard, said where it can be seen: the word on a mark of its own and what it
  // means on the line under it. The meaning used to live only in a tooltip, which a finger never
  // opens, and the mark took the colour of every other line in the card.
  const zone = cardPart(card, 'zone');
  const standing = memory.zone ?? 'hold';
  zone.replaceChildren(el('b', 'zone-word', zoneWord(standing)), el('span', 'zone-note', ZONE_NOTE[standing] ?? ''));
  zone.className = `zone ${travels(memory) ? 'underway' : 'archived'} zone-${standing}`;
  zone.title = '';

  // The wires it has on the map, strongest first.
  const neighbours = neighboursOf(memory.id);
  const links = cardPart(card, 'links');
  cardPart(card, 'degree').textContent = String(neighbours.length);
  links.replaceChildren();
  if (!neighbours.length) links.append(el('li', 'none', t('No theme shared with another memory yet.')));
  for (const { link, node: other } of neighbours) {
    links.append(wireRow(other, `${Math.round(link.weight * 100)}%`, { link, title: `${kindWord(other.memory.kind)} · ${t('{pct}% similar in meaning', { pct: Math.round(link.weight * 100) })}\n${other.memory.text}` }));
  }

  // And what has actually passed between it and the room. Filled from the archive, then kept up.
  cardPart(card, 'exchange').textContent = t('READING…');
  cardPart(card, 'fired').replaceChildren();
  const forget = cardPart(card, 'forget');
  forget.textContent = memory.kind === 'aberration' ? t('REMOVE THIS DOUBTFUL MEMORY') : t('FORGET THIS MEMORY');
  forget.classList.remove('confirm');
  forget.disabled = false;
  void nostromoTraffic(card);
  watchTraffic();
  if (nostromo.flat) flatFocus(node);
}

// The traffic of the open card, read from the archive. Every memory is supposed to be in
// conversation with the rest; this is that conversation, counted.
async function nostromoTraffic(card = frontCard()) {
  const node = card?.node;
  if (!node || !card.isConnected) return;
  const id = node.memory.id;
  let traffic;
  try {
    const response = await fetch(`/api/memory/${id}/traffic?designation=${encodeURIComponent(nostromoDesignation())}`);
    traffic = await response.json();
    if (!response.ok) throw new Error(traffic.error ?? `HTTP ${response.status}`);
  } catch (error) {
    if (card.isConnected) cardPart(card, 'exchange').textContent = String(error.message).toUpperCase();
    return;
  }
  if (!card.isConnected || card.node?.memory.id !== id) return;   // the card was closed meanwhile
  // What the archive counted is the truth about this memory: the map's star follows it live.
  node.memory.recalled = traffic.recalled;
  node.memory.lastRecalled = traffic.lastRecalled;
  const degree = nostromo.links.filter((link) => link.a === id || link.b === id).length;
  node.activity = activityOf(rawActivity(node.memory, degree), nostromo.rawTop ?? 1);

  const said = [];
  if (node.cold) said.push(t('UNUSED · the archive has been opened {n} times since this was written and never once carried it, and it shares a subject with nothing', { n: node.cold.chances }));
  said.push(traffic.recalled
    ? t('MADRE has reached for this {n} times', { n: traffic.recalled }) + (traffic.lastRecalled ? t(' · last {when}', { when: agoWords(traffic.lastRecalled) }) : '')
    : t('MADRE has not reached for this one yet'));
  if (traffic.askers?.length) said.push(traffic.askers.map((asker) => `@${asker.agent} ${asker.times}`).join(' · '));
  if (traffic.recent?.length) {
    const last = traffic.recent[0];
    said.push(t('last turn: {who} · {when}', { who: last.agent ? `@${last.agent}` : t('the project'), when: agoWords(last.at) }));
  } else if (traffic.recalled && traffic.since) {
    // The counters are older than the trail. Saying nothing here would read as "always alone".
    said.push(t('MADRE has tracked what it is used with since {when} · nothing yet', { when: new Date(traffic.since).toLocaleDateString() }));
  }
  cardPart(card, 'exchange').textContent = said.join('\n');

  const fired = cardPart(card, 'fired');
  fired.replaceChildren();
  const byId = new Map(nostromo.nodes.map((item) => [item.memory.id, item]));
  // What it kept arriving with. Two memories that keep travelling into the same turn are in
  // conversation whether or not they ever looked alike.
  for (const mate of traffic.fired ?? []) {
    const other = byId.get(mate.id);
    if (!other) continue;
    const link = nostromo.links.find((one) => (one.a === id && one.b === mate.id) || (one.b === id && one.a === mate.id)) ?? null;
    const row = wireRow(other, `×${mate.times}`, { link, title: `${t('Used together in the same turn {n} {times} · last {when}', { n: mate.times, times: mate.times === 1 ? t('time') : t('times'), when: agoWords(mate.last) })}${mate.cascades ? `\n${t('Strong enough that recalling this one now brings it along ({pct}%).', { pct: Math.round(mate.strength * 100) })}` : ''}\n${other.memory.text}` });
    if (mate.cascades) row.classList.add('carries');
    fired.append(row);
  }
  if (!(traffic.fired ?? []).length && traffic.recalled) {
    fired.append(el('li', 'none', traffic.recent?.length ? t('It has always been used alone.') : t('No turn has carried it since the project started keeping this trail.')));
  }
  // What a refutation did, from whichever end this memory is on.
  for (const taken of traffic.refutes ?? []) {
    const other = byId.get(taken.id);
    const row = el('li', 'wire-row refuted');
    const dot = el('i');
    dot.style.setProperty('--kind', MEMORY_COLORS[taken.kind] ?? MEMORY_COLORS.fact);
    row.append(dot, el('span', 'what', taken.text), el('b', null, t('TAKEN DOWN')));
    row.title = t('This doubtful memory took that memory out of every future answer.');
    if (other) row.addEventListener('click', () => showNostromoCard(other));
    fired.append(row);
  }
  if (traffic.refutedBy) {
    const other = byId.get(traffic.refutedBy.id);
    const row = el('li', 'wire-row refuted');
    const dot = el('i');
    dot.style.setProperty('--kind', MEMORY_COLORS[traffic.refutedBy.kind] ?? MEMORY_COLORS.aberration);
    row.append(dot, el('span', 'what', traffic.refutedBy.text), el('b', null, t('REFUTES IT')));
    row.title = t('A doubtful memory took this memory out of every future answer.');
    if (other) row.addEventListener('click', () => showNostromoCard(other));
    fired.append(row);
  }
}

// While a card is open the reading follows the room: every event nudges it, and a slow tick
// covers the quiet (a recall is counted as a turn begins, before it has anything to say).
let trafficTimer = null;
let trafficSoon = null;
// Every open card follows the room, not only the one in front.
const everyTraffic = () => { for (const card of nostromo.cards) void nostromoTraffic(card); };
function watchTraffic() {
  clearInterval(trafficTimer);
  trafficTimer = setInterval(() => { if (nostromo.cards.length) everyTraffic(); else stopTraffic(); }, 6000);
}
function stopTraffic() { clearInterval(trafficTimer); trafficTimer = null; clearTimeout(trafficSoon); trafficSoon = null; }
function nudgeTraffic() {
  if (!nostromo.cards.length || trafficSoon) return;
  trafficSoon = setTimeout(() => { trafficSoon = null; everyTraffic(); }, 700);
}
liveWatcher = nudgeTraffic;

// Forgetting takes two presses: the second within four seconds. Each card forgets its own memory.
let forgetTimer = null;
async function forgetFromCard(card, button) {
  const node = card.node;
  if (!node) return;
  if (!button.classList.contains('confirm')) {
    button.classList.add('confirm');
    button.textContent = t('PRESS AGAIN TO FORGET · FOREVER');
    clearTimeout(forgetTimer);
    forgetTimer = setTimeout(() => { button.classList.remove('confirm'); button.textContent = t('FORGET THIS MEMORY'); }, 4000);
    return;
  }
  clearTimeout(forgetTimer);
  button.disabled = true;
  button.textContent = t('FORGETTING…');
  try {
    const response = await fetch(`/api/memory/${node.memory.id}`, { method: 'DELETE', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ designation: nostromoDesignation() }) });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error ?? `HTTP ${response.status}`);
    beginImplosion(node, performance.now() / 1000);
    closeCard(card);
    const left = result.stats?.memories ?? Math.max(0, nostromo.nodes.length - 1);
    nostromo.sub.textContent = t('MEMORY RESEARCH · {n} MEMORIES · {links} LINKS · {entries} EXCHANGES BEHIND THEM', { n: left, links: nostromo.links.length, entries: result.stats?.entries ?? 0 });
    nostromo.empty.hidden = left > 0;
    toast(t('Diagnostics › memory forgotten: “{text}”. No future turn will read it.', { text: node.memory.text.slice(0, 80) + (node.memory.text.length > 80 ? '…' : '') }));
  } catch (error) {
    button.disabled = false;
    button.classList.remove('confirm');
    button.textContent = t('FORGET THIS MEMORY');
    toast(t('Diagnostics › it could not be forgotten: {error}', { error: error.message }));
  }
}


document.querySelector('#tour-button')?.addEventListener('click', () => { document.querySelector('#mother')?.close?.(); stepsResume(); roomTour().openChapters(); });
// What Switch project is, once; for someone new, after the walk of the way in (showNewHints), not
// before its first card (2026-10-21).
function saySwitch() {
  if (isNewcomer() && GUIDE_HINTS.some((hint) => !hintsSeen()[hint.id])) return;
  if (switcher.key && !document.querySelector('dialog[open]')) void roomTour().hint('switch', switcher.key, { title: t('Switch project'), text: t('Takes you to another open project. Its light turns on when that project needs you or finishes something.') });
}
function maybeStartTour() {
  // The half on the right of a split window is the same room; the left half already did this.
  // A phone gets the room as it is: the tour points at keys that live on the Mac.
  if (state.tourArmed || SPLIT_CHAT || state.device) return;
  state.tourArmed = true;
  // The welcome of 1.0 (public/tour.js) comes first, once per person, and replaces the old tour
  // and What's new 1.0. Once it was given, only a later version's news come, never the old tour;
  // and the first time the room is here after it, Switch project says what it is.
  void roomTour().loaded.then(async (answer) => {
    // A new person is welcomed in Home, where the bonjour leads to connecting the agents and adding
    // the projects before any chapter; a project does not greet them first (2026-10-14).
    if (answer?.owed && !answer.returning && !answer.state?.path) return;
    if (answer?.owed) { await roomTour().maybeBonjour(); return; }
    if (answer?.state?.bonjourAt) {
      const shown = await maybeShowWhatsNew();
      if (!shown) setTimeout(saySwitch, 2400);
      return;
    }
    // The welcome could not be read: the news of this version, if any (the five-stop tour that
    // stood here before 1.0 is gone with it — WEB-15 of the 1.0 review).
    void maybeShowWhatsNew();
  });
}
// The welcome and its chapters in a project: what «Take me there» does here, and when the bonjour
// must wait — for an agent to be connected and for every turn to finish. The right half of a split
// window and a phone get none of it.
function roomTour() {
  roomTourKept ??= startWelcome({
    page: 'room',
    phone: Boolean(state.device || SPLIT_CHAT),
    device: Boolean(state.device) && !SPLIT_CHAT,
    pillSlot: SPLIT_CHAT ? null : document.querySelector('#tour-pill-slot'),
    hidden: () => (state.phonePreview ? [] : ['phone']),
    ready: () => [...state.agents.values()].some((agent) => agent.ready) && !state.running.size && !state.plansRunning.size,
    onChange: (kept) => { welcomeKept = kept; stepsPaint(); },
    go: {
      home: () => leaveTo('/salas'),
      project: () => { if (switcher.key) switchOpen(); },
      talk: () => els.input?.focus(),
      modes: () => openSettingsOn('permissions'),
      coordinator: () => { if (state.salas) { els.input?.focus(); return; } els.input.value = '/bishop '; els.input.focus(); autosize(); },
      maps: () => void openNostromo(),
      settings: () => openSettings(true),
      modules: () => { openModules(); void refreshModules().then(() => renderModules()); },
      phone: () => phoneUI.button?.click(),
      gestures: () => roomTour().openGestures(),
    },
  });
  return roomTourKept;
}

/* ---------- First touch: what a button is for, the first time it is pressed ---------- */

