  const past = others.find(([, node]) => centre < node.offsetLeft + node.offsetWidth / 2)?.[0] ?? null;
  const order = barKit.order.filter((one) => one !== drag.id);
  order.splice(past ? order.indexOf(past) : order.length, 0, drag.id);
