// Arrived from the other side's offer: take its place now.
{
  // The address stays this conversation's, without what brought the page here.
  const here = `${globalThis.location?.pathname ?? '/'}${VIEW_CHAT ? `?en=${VIEW_CHAT}` : ''}`;
  const asked = new URLSearchParams(globalThis.location?.search ?? '').get('continuar');
  if (asked === 'mac' || asked === 'phone') {
    globalThis.history?.replaceState?.(null, '', here);
    fetch('/api/handoff').then((response) => response.json()).then((both) => {
      try { localStorage.setItem('pulse.handoffTaken', String(both?.[asked]?.at ?? 0)); } catch { /* no storage */ }
      return handoffApply(both?.[asked]);
    }).catch(() => {});
  } else void handoffOffer();
}


/* ---------- Sheets on a phone ----------
   Everything that floats on the Mac rises from the bottom on a phone, the way a sheet does on iOS:
   rounded at the top, a grabber, the room dimmed behind it. It closes with its own ×, with a
   touch on the dimmed room, or pulled down by its top edge. Opening one never puts the keyboard up:
   a dialog that opens gives focus to its first field, and on a phone that field is a search box. */
// Function-scoped, not module constants: this runs while the room boots, before the end of this
// file has been read.
function phoneSheetsOpen() {
  return [...document.querySelectorAll('dialog.surface[open], dialog.viewer[open], dialog#nostromo[open], .tree:not([hidden]), .browser-dock:not([hidden])')];
}
function phoneSheetClose(sheet) {
  const closes = sheet.querySelectorAll('.x-close, #chats-close, #tree-close, #browser-close, #viewer-close, #mother-close, #modules-close, #nostromo-close, #core-close, #economy-close, #module-guide-close');
  const close = [...closes].find((one) => one.closest('dialog, .tree, .browser-dock') === sheet);
  if (close) close.click();
  else if (typeof sheet.close === 'function') sheet.close();
}
function phoneSheets() {
  if (phoneSheets.ready) return;
  phoneSheets.ready = true;
  // A dialog that opens focuses the first thing in it that asks for focus, and failing that its
  // first field. Each one gets a quiet first thing that asks: no field is touched, no keyboard.
  if (DIALOG) {
    for (const name of ['show', 'showModal']) {
      const native = DIALOG[name];
      DIALOG[name] = function opened(...args) {
        if (!this.querySelector(':scope > .phone-focus')) {
          const sink = el('span', 'phone-focus');
          sink.tabIndex = -1;
          sink.setAttribute('autofocus', '');
          sink.setAttribute('aria-hidden', 'true');
          this.prepend(sink);
        }
        return native.apply(this, args);
      };
    }
  }
  const veil = el('div', 'phone-veil');
  veil.hidden = true;
  document.body?.append(veil);
  const top = () => phoneSheetsOpen().at(-1) ?? null;
  veil.addEventListener('click', () => { const sheet = top(); if (sheet) phoneSheetClose(sheet); });
  const dress = (sheet) => {
    if (sheet.dataset.phoneSheet) return;
    sheet.dataset.phoneSheet = '1';
    const grab = el('span', 'phone-grabber');
    grab.setAttribute('aria-hidden', 'true');
    sheet.prepend(grab);
    // Pulled down by its top edge: it follows the finger, and past a third of a thumb it goes.
    let start = null;
    sheet.addEventListener('touchstart', (event) => {
      const y = event.touches[0]?.clientY ?? 0;
      start = y - sheet.getBoundingClientRect().top < 56 ? y : null;
    }, { passive: true });
    sheet.addEventListener('touchmove', (event) => {
      if (start === null) return;
      const dy = Math.max(0, (event.touches[0]?.clientY ?? start) - start);
      sheet.style.transition = 'none';
      sheet.style.translate = `0 ${dy}px`;
    }, { passive: true });
    sheet.addEventListener('touchend', (event) => {
      if (start === null) return;
      const dy = (event.changedTouches[0]?.clientY ?? start) - start;
      start = null;
      sheet.style.transition = '';
      sheet.style.translate = '';
      if (dy > 90) phoneSheetClose(sheet);
    });
  };
  // It writes only what changes: the observer hears its own writes, and the same value written
  // again is still a change to it, which kept it writing for ever.
  const settle = () => {
    const open = phoneSheetsOpen();
    for (const sheet of open) dress(sheet);
    const none = open.length === 0;
    if (veil.hidden !== none) veil.hidden = none;
    if (document.documentElement.classList.contains('sheet-up') === none) document.documentElement.classList.toggle('sheet-up', !none);
  };
  new MutationObserver(settle).observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['open', 'hidden'] });
  settle();
}

// SERVERS on a phone: the browser beside the room opens addresses on the Mac, which from a phone
// would be the phone itself. Here the panel is a list of what is serving on the Mac, to be seen.
async function phoneServers() {
  const panel = document.querySelector('#browser');
  if (!panel) return;
  const head = panel.querySelector('.browser-head');
  if (head) head.dataset.phoneTitle = t('Your servers on the Mac');
  let list = panel.querySelector('.phone-servers');
  if (!list) { list = el('div', 'phone-servers'); panel.append(list); }
  list.replaceChildren(el('p', 'phone-say phone-quiet', t('One moment…')));
  const read = await fetch('/api/ports').then((response) => response.json()).catch(() => null);
  if (!read || read.error) { list.replaceChildren(el('p', 'phone-say', read?.error ? resay(read.error) : t('The servers could not be read.'))); return; }
  const rows = (read.ports ?? []).map((one) => {
    const row = el('div', 'phone-server');
    row.append(el('b', null, `:${one.port}`), el('span', null, one.title ?? one.name ?? one.command ?? ''));
    return row;
  });
  // Where they are switched on or off, a touch away.
  const switches = sxButton(t('Switches in Settings'), () => { browserHide(); openSettingsOn('files'); });
  list.replaceChildren(...(rows.length ? rows : [el('p', 'phone-say', t('No server of this project is running on your Mac.'))]), switches);
}

// The keyboard on a phone: the box is fixed to the bottom of the page, and the keyboard covers the
// bottom of the screen while Safari slides what is visible down the page to reach the field. The
// part of the page still visible is the visual viewport: the box stands on its bottom (--kb, how
// far that is above the page's) and the bar hangs from its top (--vv-top), so both stay in sight
// with the conversation between them, as in Messages. Measured from the viewports alone: from the
// box's own position it counted Safari's slide twice and left the box floating mid-screen.
function phoneKeyboard() {
  const view = window.visualViewport;
  if (!view || !els.composer) return;
  const root = document.documentElement;
  let lift = 0;
  let top = 0;
  const settle = () => {
    // Pinched in, what is visible is a window onto the page: nothing follows it.
    const still = Math.abs((view.scale ?? 1) - 1) > 0.01;
    const nextTop = still ? 0 : Math.max(0, Math.round(view.offsetTop));
    // The page's own height: Safari shrinks innerHeight with the keyboard, the page stays as tall.
    const nextLift = still ? 0 : Math.max(0, Math.round((root.clientHeight || window.innerHeight) - view.offsetTop - view.height));
    if (nextTop !== top) { top = nextTop; root.style.setProperty('--vv-top', `${top}px`); }
    if (Math.abs(nextLift - lift) < 2) return;
    lift = nextLift;
    root.style.setProperty('--kb', `${lift}px`);
    // The conversation's last line rides up with the box.
    measureDock();
  };
  view.addEventListener('resize', settle);
  view.addEventListener('scroll', settle);
  settle();
}

// Every name above exists now: the room is painted (boot, beside the state it reads).
boot();
// Asking for a star or a review (review-ask.js): on the Mac, and never while something is going on
// — an agent at work, a plan running, words half written in the box.
// Asked by the page, never by the half on the right of a split view, which is this same page (WEB-12).
if (!SPLIT_CHAT) startReviewAsk({ busy: () => Boolean(state.device || state.running.size || state.plansRunning.size || els.input?.value?.trim()) });
// The tour of 1.0 reads where the person is as the room opens, so First steps knows whether to
// wait; on a phone, the phone's card is said the first time.
if (!SPLIT_CHAT) roomTour();

/* ---------- PRUEBA · respuestas sin burbuja (2026-10-15) ---------- */
// Para comparar formas de respuesta sin burbuja con la de siempre, en una sala de verdad, sobre su
// fondo. Nadie lo ve si no abre la sala con `?reply=`: doc, doc-inline, pieces, pieces-edge o bubble,
// y `&lane=` lane, column, halo, stripe o 0. Lo elegido se recuerda en este navegador; `?reply=off`
// lo apaga y esconde el selector.
(() => {
  const FORMS = [['A', 'doc', 'A · regla'], ['B', 'doc-inline', 'B · avatar en línea'], ['C', 'pieces', 'C · tarjeta'], ['D', 'pieces-edge', 'D · filo'], ['E', 'bubble', 'E · burbuja']];
  const LANES = [['1', 'lane', '1 · difuso'], ['2', 'column', '2 · columna'], ['3', 'halo', '3 · halo'], ['4', 'stripe', '4 · franja'], ['5', '0', '5 · sin carril']];
  const TERMS = [['0', 'actual', 'Actual'], ['a', 'line', 'a · línea'], ['b', 'window', 'b · ventana'], ['c', 'pill', 'c · píldora'], ['d', 'step', 'd · paso']];
  // Desde ACCC-BABA-ECBB-DCAA-C (2026-10-15) la respuesta va en burbuja y cada /run en píldora. Lo que
  // se eligió en el selector solo vale mientras se compara: sin ?reply ni ?combo, la forma de siempre.
  let reply = 'bubble';
  let lane = 'lane';
  let term = 'pill';
  let showLab = false;
  try {
    const asked = new URLSearchParams(location.search);
    if (asked.get('reply') === 'off') { for (const key of ['pulse.reply', 'pulse.reply.lane', 'pulse.reply.term']) localStorage.removeItem(key); }
    else {
      // ?combo=C1b: la forma, el carril y la terminal en un código.
      const combo = /^([A-E])([1-5])?([0a-d])?$/.exec(asked.get('combo') ?? '');
      if (combo) {
        localStorage.setItem('pulse.reply', FORMS.find(([code]) => code === combo[1])[1]);
        if (combo[2]) localStorage.setItem('pulse.reply.lane', LANES.find(([code]) => code === combo[2])[1]);
        if (combo[3]) localStorage.setItem('pulse.reply.term', TERMS.find(([code]) => code === combo[3])[1]);
      }
      if (asked.has('reply')) localStorage.setItem('pulse.reply', asked.get('reply'));
      if (asked.has('lane')) localStorage.setItem('pulse.reply.lane', asked.get('lane'));
      if (asked.has('term')) localStorage.setItem('pulse.reply.term', asked.get('term'));
    }
    showLab = (asked.has('reply') && asked.get('reply') !== 'off') || asked.has('combo');
    if (showLab) {
      reply = localStorage.getItem('pulse.reply') ?? reply;
      lane = localStorage.getItem('pulse.reply.lane') ?? lane;
      term = localStorage.getItem('pulse.reply.term') ?? term;
    }
    if (lane === '1') lane = 'lane';
  } catch { /* sin almacenamiento: la forma de siempre */ }
  if (!FORMS.some(([, value]) => value === reply)) reply = 'bubble';
  if (!TERMS.some(([, value]) => value === term)) term = 'pill';
  const root = document.documentElement;
  const apply = () => {
    if (reply === 'bubble') delete root.dataset.reply; else root.dataset.reply = reply;
    if (lane === '0' || reply === 'bubble') delete root.dataset.replyLegible; else root.dataset.replyLegible = lane;
    if (term === 'actual') delete root.dataset.term; else root.dataset.term = term;
  };
  apply();
  const bar = el('div', 'reply-lab');
  const keep = (key, value) => { try { localStorage.setItem(key, value); } catch { /* sin almacenamiento */ } };
  const codeOf = () => `${FORMS.find(([, value]) => value === reply)[0]}${LANES.find(([, value]) => value === lane)?.[0] ?? '1'}${TERMS.find(([, value]) => value === term)[0]}`;
  const row = (title, list, current, set, { off = false } = {}) => {
    const line = el('div', 'lab-row');
    line.append(el('b', null, title));
    for (const [, value, words] of list) {
      const key = el('button', value === current && !off ? 'on' : null, words);
      key.type = 'button';
      key.disabled = off;
      key.addEventListener('click', () => { set(value); apply(); draw(); });
      line.append(key);
    }
    return line;
  };
  const draw = () => {
    bar.replaceChildren();
    const forms = row('Forma', FORMS, reply, (value) => { reply = value; keep('pulse.reply', value); });
    const sample = el('button', 'lab-sample', 'Insertar ejemplo');
    sample.type = 'button';
    sample.title = 'Dos respuestas y dos comandos de muestra, solo en pantalla: no se guardan';
    sample.addEventListener('click', insertSample);
    forms.append(sample);
    const lanes = row('Carril', LANES, lane, (value) => { lane = value; keep('pulse.reply.lane', value); }, { off: reply === 'bubble' });
    const terms = row('Terminal', TERMS, term, (value) => { term = value; keep('pulse.reply.term', value); });
    const code = el('span', 'lab-code', codeOf());
    code.title = 'Esta combinación. Ábrela con ?combo=' + codeOf();
    terms.append(code);
    bar.append(forms, lanes, terms);
  };
  // Dos respuestas como las de las capturas, dibujadas por el mismo render de la sala.
  function insertSample() {
    const column = document.querySelector('#messages .thread-inner') ?? document.querySelector('#messages');
    if (!column) return;
    column.querySelectorAll('.reply-sample').forEach((node) => node.remove());
    const make = (agent, label, badges, said, text) => {
      const row = paint(el('article', 'row assistant reply-sample'), agent);
      row.dataset.agent = agent;
      const col = el('div', 'col');
      const who = el('div', 'who');
      who.append(el('span', null, label), ...badges, el('span', 'reply', said));
      const bubble = el('div', 'bubble');
      bubble.append(renderMarkdown(text));
      const foot = el('div', 'bubble-foot');
      foot.append(el('div', 'stamp', '02:01 PM · 15.3k tok · $0.10'));
      bubble.append(foot);
      col.append(who, bubble);
      row.append(avatar(agent), col);
      column.append(row);
    };
    make('claude', 'Claude', [el('span', 'badge ash', 'AHORRO DE TOKENS')], '↳ Prueba de comunicación entre agentes…',
      'Hola a todos, soy @claude abriendo la ronda de prueba. Pido a cada agente una línea de confirmación.\n\n```pulse\n- @codex: saluda y confirma que recibes este mensaje en una línea.\n- @gemini: saluda y confirma que recibes este mensaje en una línea.\n- @opencode: saluda y confirma que recibes este mensaje en una línea.\n- @madre: saluda y confirma que recibes este mensaje en una línea.\n```');
    make('madre', 'Madre', [el('span', 'badge', 'CONTESTÁNDOLE A @CLAUDE')], '',
      'Soy @madre, la memoria de esta sala hablando, con qwen2.5:7b sobre Ollama en esta máquina. El archivista es mi otra mitad: el mismo modelo, de fondo, lee lo que la sala dice cada pocos intercambios o tras unos minutos de reposo y guarda hechos, decisiones, preferencias y preguntas abiertas. Eso es lo que ves en el Mapa de memoria y lo que yo cito con [#n]. No escribo archivos, no ejecuto ni tomo decisiones por nadie.\n\nSí puedo convocar al equipo si me lo pides: «@madre, pregúntale al equipo …» abre una ronda con cada agente en línea y cierro con un resumen citado. Para enseñarme algo no hace falta dictármelo: trabaja en la sala y se destila solo.');
    for (const node of [
      renderTerminalCard({ id: 'sample-ok', payload: { name: 'run', ok: true, text: 'PDF listo: output/pdf/cotizacion.pdf', run: { line: 'node scripts/pdf.mjs', exitCode: 0, durationMs: 2000, agent: 'codex' } } }),
      renderTerminalCard({ id: 'sample-fail', payload: { name: 'run', ok: false, text: 'ℹ tests 60\n✔ test 1 passed\n✖ test 9 failed\nℹ pass 53\nℹ fail 7', run: { line: 'npm test', exitCode: 1, durationMs: 4200, agent: 'codex' } } }),
    ]) { node.classList.add('reply-sample'); column.append(node); }
    const thread = document.querySelector('#messages');
    if (thread) thread.scrollTop = thread.scrollHeight;
  }
  if (!showLab || SPLIT_CHAT) return;
  draw();
  document.body.append(bar);
})();

/* ---------- LABORATORIO DEL CHAT (2026-10-15) ---------- */
// Una conversación con todos los elementos del chat, dibujada por los mismos renderizadores de la
// sala a partir de eventos de muestra (solo en pantalla: no se escriben en el registro), y un panel
// con cinco formas de cada elemento. Nadie lo ve si no abre la sala con `?lab` (o `?lab=CÓDIGO`).
// La elección se guarda como un código de 17 letras, en grupos de cuatro, para pasarla tal cual.
// LAB_CHOSEN es lo que quedó en la sala (styles.css, «CHAT · ACCC-BABA-ECBB-DCAA-C»): un elemento solo
// lleva data-labNN cuando se compara con otra forma, y entonces su regla de siempre se aparta.
const LAB_CHOSEN = 'ACCCBABAECBBDCAAC';
const LAB = [
  ['Mensaje del humano', ['Burbuja de acento (hoy)', 'Burbuja neutra · ChatGPT y Claude', 'Sin burbuja, alineado a la derecha', 'Tarjeta de petición · Cursor', 'Burbuja con destino visible']],
  ['Adjuntos', ['Mosaicos (antes)', 'Chips en línea', 'Tarjeta de archivo · Claude (hoy)', 'Lista compacta', 'Encima del mensaje · ChatGPT']],
  ['Pensando', ['Puntos (antes)', 'Texto con brillo · Claude y ChatGPT', 'Avatar que late y tiempo (hoy)', 'Barra fina de progreso', 'Píldora «pensando · 12 s»']],
  ['Cabecera del agente', ['Mono con chips (antes)', 'Nombre en letra normal · Claude', 'Píldora del agente (hoy)', 'Solo nombre; chips al pasar · ChatGPT', 'Avatar dentro de la cabecera']],
  ['Cuerpo de la respuesta', ['Prosa libre con carril (antes)', 'Burbuja (hoy)', 'Tarjeta con borde', 'Filo del color del agente', 'Documento con regla']],
  ['Memoria citada', ['Número en el texto (hoy)', 'Superíndice · ChatGPT con búsqueda', 'Chip de fuente · Perplexity', 'Subrayado punteado', 'Atenuada, al final de la frase']],
  ['Plan', ['Tarjeta (antes)', 'Lista de tareas con casillas · Cursor (hoy)', 'Pasos numerados con línea', 'Equipo 2×2', 'Línea de tiempo']],
  ['Bloque de código', ['Cabecera y COPIAR (hoy)', 'Barra suave · ChatGPT', 'Limpio, copiar al pasar · Claude', 'Oscuro siempre · terminal', 'Plegado a 6 líneas']],
  ['Pie de la respuesta', ['Métricas e iconos (antes)', 'Solo iconos, al pasar · ChatGPT', 'Métricas en píldora', 'Acciones con fondo · Claude', 'Hora sola, métricas al pasar (hoy)']],
  ['Elección', ['Opciones grandes (antes)', 'Chips de respuesta · ChatGPT y Gemini', 'Lista con número (hoy)', 'Tarjetas lado a lado', 'Botones al pie · Gemini']],
  ['Petición de permiso', ['Tarjeta (antes)', 'Aprobación en una línea · Claude Code (hoy)', 'Tarjeta con barra de color', 'Barra sobre la caja de escribir', 'Discreta, solo borde']],
  ['Permiso concedido', ['Píldora del modo (antes)', 'Línea divisoria (hoy)', 'Texto gris centrado', 'Píldora con candado', 'Punto y texto']],
  ['Petición de comandos', ['Lista con botones (antes)', 'Compacta, sin cajas por línea', 'Código oscuro · terminal', 'Pasos numerados (hoy)', 'Botones solo al pasar']],
  ['Comando ejecutado', ['Línea con estado (antes)', 'Ventana de terminal', 'Píldora · herramientas de ChatGPT y Claude (hoy)', 'Paso en un hilo', 'Línea compacta, sin /run']],
  ['Avisos del sistema', ['Puntos plegados (hoy)', 'Línea centrada', 'Divisor con texto', 'Chip a la izquierda', 'Siempre abiertos, en tarjeta']],
  ['Error y diagnóstico', ['Tarjeta roja centrada (hoy)', 'Tarjeta a la izquierda con icono', 'Banner a lo ancho', 'Línea roja discreta', 'Tarjeta neutra con borde rojo']],
  ['Espacio entre turnos', ['Como antes', 'Compacto', 'Amplio · ChatGPT y Claude (hoy)', 'Línea fina entre turnos', 'Agrupar el mismo agente']],
];
(() => {
  let asked = null;
  try { asked = new URLSearchParams(location.search).get('lab'); } catch { return; }
  if (asked === null || SPLIT_CHAT) return;
  const root = document.documentElement;
  const picks = LAB_CHOSEN.split('');
  try {
    const saved = (/^[A-E-]{17,21}$/.test(asked) ? asked : localStorage.getItem('pulse.lab')) ?? '';
    saved.replace(/-/g, '').split('').forEach((key, index) => { if (index < picks.length) picks[index] = key; });
  } catch { /* sin almacenamiento */ }
  const code = () => picks.join('').match(/.{1,4}/g).join('-');
  const apply = () => {
    picks.forEach((key, index) => {
      const name = `lab${String(index + 1).padStart(2, '0')}`;
      if (key === LAB_CHOSEN[index]) delete root.dataset[name]; else root.dataset[name] = key;
    });
    // 05 · every body but the bubble was drawn over the old prose form; 14 · the /run cards reuse
    // the forms already built (data-term); 15 · notices show open.
    if (picks[4] === 'B') { delete root.dataset.reply; delete root.dataset.replyLegible; }
    else { root.dataset.reply = 'pieces'; root.dataset.replyLegible = 'lane'; }
    const term = { B: 'window', C: 'pill', D: 'step', E: 'line' }[picks[13]];
    if (term) root.dataset.term = term; else delete root.dataset.term;
    document.querySelectorAll('#messages .sys-dots').forEach((strip) => strip.classList.toggle('open', picks[14] !== 'A'));
    try { localStorage.setItem('pulse.lab', code()); } catch { /* sin almacenamiento */ }
  };
  apply();
  root.dataset.lab = 'on';

  // The panel: one row per element, its five forms, the code and a way to copy it.
  const panel = el('aside', 'lab-panel');
  const draw = () => {
    panel.replaceChildren();
    const head = el('header', 'lab-head');
    const fold = el('button', 'lab-fold', panel.classList.contains('folded') ? '›' : '‹');
    fold.type = 'button';
    fold.title = 'Plegar el panel';
    fold.addEventListener('click', () => { panel.classList.toggle('folded'); draw(); });
    const codeBox = el('output', 'lab-code', code());
    const copy = el('button', 'lab-copy', 'Copiar mi elección');
    copy.type = 'button';
    copy.addEventListener('click', async () => {
      const lines = LAB.map(([name, forms], index) => `${String(index + 1).padStart(2, '0')} ${name}: ${picks[index]} · ${forms['ABCDE'.indexOf(picks[index])]}`);
      const text = `Código: ${code()}\n${lines.join('\n')}`;
      try { await navigator.clipboard.writeText(text); copy.textContent = 'Copiado ✓'; } catch { prompt('Copia tu elección:', text); }
      setTimeout(() => { copy.textContent = 'Copiar mi elección'; }, 1600);
    });
    head.append(fold, el('b', null, 'Laboratorio'), codeBox, copy);
    panel.append(head);
    if (panel.classList.contains('folded')) return;
    const list = el('div', 'lab-list');
    LAB.forEach(([name, forms], index) => {
      const row = el('div', 'lab-row');
      const top = el('div', 'lab-top');
      top.append(el('span', 'lab-n', String(index + 1).padStart(2, '0')), el('span', 'lab-name', name));
      const keys = el('span', 'lab-keys');
      for (const key of 'ABCDE') {
        const button = el('button', key === picks[index] ? 'on' : null, key);
        button.type = 'button';
        button.title = forms['ABCDE'.indexOf(key)];
        button.addEventListener('click', () => { picks[index] = key; apply(); draw(); });
        keys.append(button);
      }
      top.append(keys);
      row.append(top, el('span', 'lab-desc', forms['ABCDE'.indexOf(picks[index])]));
      list.append(row);
    });
    const again = el('button', 'lab-again', 'Volver a dibujar la conversación');
    again.type = 'button';
    again.addEventListener('click', () => drawConversation());
    panel.append(list, again);
  };
  draw();
  document.body.append(panel);

  // The conversation: sample events through the room's own renderer, in the order a real one goes.
  let n = 0;
  const at = (minutes) => new Date(Date.now() - (90 - minutes) * 60000).toISOString();
  const ev = (type, payload, minutes) => ({ id: `lab-${Date.now()}-${n += 1}`, sequence: 900000 + n, type, timestamp: at(minutes), payload });
  function drawConversation() {
    const column = els.column;
    if (!column) return;
    column.replaceChildren();
    state.lastSender = null;
    const u1 = `lab-u1-${Date.now()}`;
    const a1 = `lab-a1-${Date.now()}`;
    const events = [
      ev('message.created', { messageId: u1, role: 'user', sender: 'you', target: 'codex', mode: 2, text: 'Revisa el README y el título del paquete; arma un plan con los demás si hace falta.', status: 'sent', attachments: [{ name: 'README.md', fileName: 'lab-readme.md', size: 4096, contentType: 'text/markdown' }, { name: 'notas.txt', fileName: 'lab-notas.txt', size: 812, contentType: 'text/plain' }] }, 1),
      { ...ev('agent.started', { messageId: `lab-think-${Date.now()}`, agent: 'gemini', timeoutMs: 180000 }, 2), timestamp: new Date().toISOString() },
      ev('message.created', { messageId: a1, parentMessageId: u1, role: 'assistant', sender: 'codex', target: 'you', mode: 2, model: 'gpt-5.6-sol', effort: 'high', status: 'sent', text: 'Revisé el proyecto: el título del README no coincidía con el nombre del paquete [#214]. Lo dejé anotado y reparto la revisión.\n\n```pulse\n- @claude: corre las pruebas y dime cuántas pasan.\n- @gemini: revisa que el README se lea bien.\n- @opencode: compara con la versión anterior.\n- @madre: resume lo que se decidió.\n```\n\nEsta es la función que arma el título:\n\n```js\nexport function titulo(paquete) {\n  return paquete.nombre ?? \'MADRE\';\n}\n// se usa en README.md y en la barra\n```' }, 3),
      ev('choice.offered', { agent: 'codex', question: '¿Actualizo también el CHANGELOG?', options: ['Sí, con una línea', 'Sí, con el detalle', 'No por ahora'], recommended: 0 }, 4),
      ev('message.created', { messageId: `lab-a2-${Date.now()}`, parentMessageId: u1, role: 'assistant', sender: 'gemini', target: 'you', mode: 1, status: 'sent', text: 'El README se lee bien. Para corregir el título necesito #3 por 15 min: tengo que editar README.md, que ya existe.' }, 5),
      ev('message.created', { messageId: `lab-a3-${Date.now()}`, parentMessageId: u1, role: 'assistant', sender: 'opencode', target: 'you', mode: 1, status: 'sent', text: 'Comparé con la versión anterior. Para dejar el cambio necesito #3 por 15 min.' }, 6),
      ev('message.created', { messageId: `lab-u2-${Date.now()}`, role: 'user', sender: 'you', target: 'opencode', mode: 3, text: 'Adelante con el cambio.', status: 'sent' }, 7),
      ev('run.requested', { messageId: u1, responseMessageId: `lab-run-${Date.now()}`, agent: 'madre', reason: 'Ver que el cambio quedó', mode: 3, commands: [{ line: "node -e \"console.log('uno')\"", argv: ['node', '-e', "console.log('uno')"] }, { line: 'git status --short', argv: ['git', 'status', '--short'] }, { line: 'ls | head', why: 'uses "{char}", which needs a shell; put each command on its own line', whyArgs: { char: '|' } }] }, 8),
      ev('command.output', { name: 'run', ok: true, text: 'PDF listo: output/pdf/cotizacion.pdf', run: { line: 'node scripts/pdf.mjs', exitCode: 0, durationMs: 2000, agent: 'codex' } }, 9),
      ev('command.output', { name: 'run', ok: false, text: 'ℹ tests 60\n✔ test 1 passed\n✖ test 9 failed\nℹ pass 53\nℹ fail 7', run: { line: 'npm test', exitCode: 1, durationMs: 4200, agent: 'claude' } }, 10),
      ev('copilot.started', { until: new Date(Date.now() + 3600000).toISOString(), minutes: 60 }, 11),
      ev('limit.warning', { agent: 'codex', usedPercent: 71.3, projectedPercent: 87.2, level: 'warning', source: 'room-soft-budget', resetAt: null, alternatives: ['claude'], message: 'MADRE warning: @codex is at 71% of its local window.' }, 12),
      ev('message.failed', { messageId: `lab-f-${Date.now()}`, target: 'madre', error: 'madre is not installed on this computer.' }, 13),
    ];
    for (const event of events) renderEvent(event);
    apply();
    column.lastElementChild?.scrollIntoView({ block: 'end' });
  }
  // After the room has drawn its own conversation, the lab takes the column. Notices fold by
  // themselves ten seconds later; when they do, the chosen form opens them again.
  setTimeout(drawConversation, 1600);
  if (els.column) new MutationObserver(() => { if (picks[14] !== 'A') document.querySelectorAll('#messages .sys-dots:not(.open)').forEach((strip) => strip.classList.add('open')); }).observe(els.column, { childList: true, subtree: true });
})();
